    /// Run Phase 1 + Step 2.1 on `storage` and simulate a clean crash right
    /// after `storage-format.json(finalized = false, pending)` is published.
    async fn crash_after_step2_1_pending(storage: &Path, generation: u64) {
        let prepared = prepare_forward_phase1(storage, generation)
            .await
            .expect("prepare_forward_phase1 must succeed");
        let mut crash_hook = |point: Phase2TestPoint, _root: &Path| -> StorageResult<()> {
            if point == Phase2TestPoint::AfterPublishPendingManifest {
                return Err(StorageBackendError::BackendInternal {
                    detail: "injected crash after Step 2.1 pending manifest".to_string(),
                });
            }
            Ok(())
        };
        let err = execute_forward_phase2_fence_and_unlink_inner(prepared, Some(&mut crash_hook))
            .await
            .expect_err("injected Step 2.1 crash must abort Phase 2");
        assert!(err.to_string().contains("injected crash after Step 2.1"));
    }

    /// Assert that `storage` with an unfinalized (`finalized == false`) manifest
    /// unconditionally fails closed with `LBR-IO-001` (`ManifestNotFinalized`)
    /// for BOTH `LIBRA_STORAGE_BACKEND=redb` and `LIBRA_STORAGE_BACKEND=sqlite`
    /// via both in-process `resolve_from_override` and isolated OS child
    /// processes invoking the real public `StorageBackendKind::resolve(dir)`.
    fn assert_rb10c_unfinalized_rejects_both_env_overrides(storage: &Path, checkpoint: &str) {
        use crate::storage::{LIBRA_STORAGE_BACKEND_ENV, manifest::detect_storage_authority};

        let auth_err = detect_storage_authority(storage)
            .expect_err("detect_storage_authority must reject unfinalized manifest");
        assert!(
            matches!(auth_err, StorageBackendError::ManifestNotFinalized { .. }),
            "[{checkpoint}] expected ManifestNotFinalized from detect_storage_authority, got {auth_err:?}"
        );
        assert_eq!(auth_err.stable_code_str(), "LBR-IO-001");

        let exe = std::env::current_exe().expect("locate current test executable");
        for env_val in ["redb", "sqlite"] {
            let inproc_err = StorageBackendKind::resolve_from_override(storage, Some(env_val))
                .expect_err("resolve_from_override must reject unfinalized manifest");
            assert!(
                matches!(inproc_err, StorageBackendError::ManifestNotFinalized { .. }),
                "[{checkpoint}] env={env_val}: expected ManifestNotFinalized, got {inproc_err:?}"
            );
            assert_eq!(inproc_err.stable_code_str(), "LBR-IO-001");

            let out = Command::new(&exe)
                .arg("--exact")
                .arg("storage::migrate::tests::forward_phase2_powerloss_torn_sector_hot_journal_rollback_and_resume")
                .arg("--nocapture")
                .env("LIBRA_RB10C_CHILD_MODE", "env_reject")
                .env("LIBRA_RB10C_TARGET_PATH", storage)
                .env(LIBRA_STORAGE_BACKEND_ENV, env_val)
                .env("LIBRA_TEST", "1")
                .output()
                .expect("spawn isolated RB-10c env-reject child");
            let stdout = String::from_utf8_lossy(&out.stdout);
            let stderr = String::from_utf8_lossy(&out.stderr);
            assert!(
                out.status.success() && stdout.contains("RB10C_ENV_REJECT_OK"),
                "[{checkpoint}] isolated public resolve() child failed for {LIBRA_STORAGE_BACKEND_ENV}={env_val} ({:?}):\nstdout:\n{stdout}\nstderr:\n{stderr}",
                out.status
            );
        }
    }

    #[tokio::test]
    async fn forward_phase2_powerloss_torn_sector_hot_journal_rollback_and_resume() {
        use crate::storage::{
            GitStore as _, RedbCaptureStore, RedbGitStore, capture_store::CaptureStore as _,
            manifest::storage_manifest_path,
        };

        // Isolated OS child-process modes (`env_reject` and `powerloss_mid_fence`).
        if let Some(mode) = std::env::var_os("LIBRA_RB10C_CHILD_MODE") {
            let target = PathBuf::from(
                std::env::var_os("LIBRA_RB10C_TARGET_PATH")
                    .expect("LIBRA_RB10C_TARGET_PATH must be set"),
            );
            match mode.to_str() {
                Some("env_reject") => {
                    let err = StorageBackendKind::resolve(&target).expect_err(
                        "public StorageBackendKind::resolve() must reject unfinalized manifest",
                    );
                    assert!(
                        matches!(err, StorageBackendError::ManifestNotFinalized { .. }),
                        "expected ManifestNotFinalized from public resolve(), got {err:?}"
                    );
                    assert_eq!(err.stable_code_str(), "LBR-IO-001");
                    println!("RB10C_ENV_REJECT_OK");
                    return;
                }
                Some("powerloss_mid_fence") => {
                    // Execute the REAL Step 2.2a fence SQL up to BEFORE `COMMIT;`,
                    // force SQLite's pager to sync the genuine hot `-journal`
                    // (containing original Page 1) AND flush dirty Page 1 to disk,
                    // assert BOTH on-disk conditions, then hard-terminate via
                    // `_exit(0)` / `ExitProcess(0)` WITHOUT running SQLite close/rollback!
                    let opts = SqliteConnectOptions::new()
                        .filename(&target)
                        .create_if_missing(false)
                        .read_only(false)
                        .shared_cache(false)
                        .busy_timeout(Duration::ZERO);
                    let mut conn = SqliteConnection::connect_with(&opts)
                        .await
                        .expect("open target db in powerloss child");
                    conn.execute("PRAGMA journal_mode = DELETE;")
                        .await
                        .expect("set DELETE mode");
                    conn.execute("PRAGMA synchronous = FULL;")
                        .await
                        .expect("set synchronous FULL");
                    conn.execute("PRAGMA locking_mode = EXCLUSIVE;")
                        .await
                        .expect("set locking_mode EXCLUSIVE");
                    conn.execute("PRAGMA cache_size = 1;")
                        .await
                        .expect("set tiny cache_size to force spill");
                    conn.execute("PRAGMA cache_spill = 1;")
                        .await
                        .expect("enable cache_spill");

                    let sv_before: i64 = sea_orm::sqlx::query_scalar("PRAGMA schema_version;")
                        .persistent(false)
                        .fetch_one(&mut conn)
                        .await
                        .expect("read schema_version before fence");

                    // List existing tables BEFORE writing the fence sentinel so we
                    // can force `pcache1` spill across distinct B-tree root pages
                    // while `writable_schema = ON` during the uncommitted fence tx.
                    let tables: Vec<String> = sea_orm::sqlx::query_scalar(
                        "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%';",
                    )
                    .persistent(false)
                    .fetch_all(&mut conn)
                    .await
                    .expect("list tables before fence to drive pager stress");

                    sea_orm::sqlx::query("BEGIN EXCLUSIVE;")
                        .persistent(false)
                        .execute(&mut conn)
                        .await
                        .expect("BEGIN EXCLUSIVE");
                    sea_orm::sqlx::query(AssertSqlSafe(format!(
                        "CREATE TABLE {SQLITE_MIGRATED_FENCE_TABLE} (x INTEGER);"
                    )))
                    .persistent(false)
                    .execute(&mut conn)
                    .await
                    .expect("CREATE TABLE fence");
                    let sv_after_create: i64 =
                        sea_orm::sqlx::query_scalar("PRAGMA schema_version;")
                            .persistent(false)
                            .fetch_one(&mut conn)
                            .await
                            .expect("read schema_version after create");
                    let mut next_sv = (sv_after_create as i32).wrapping_add(1);
                    if next_sv == sv_before as i32 {
                        next_sv = next_sv.wrapping_add(1);
                    }
                    sea_orm::sqlx::query("PRAGMA writable_schema = ON;")
                        .persistent(false)
                        .execute(&mut conn)
                        .await
                        .expect("enable writable_schema");
                    sea_orm::sqlx::query(AssertSqlSafe(format!(
                        "UPDATE sqlite_master SET sql = '{SQLITE_MIGRATED_FENCE_SQL}' WHERE type = 'table' AND name = '{SQLITE_MIGRATED_FENCE_TABLE}';"
                    )))
                    .persistent(false)
                    .execute(&mut conn)
                    .await
                    .expect("UPDATE sqlite_master fence");
                    sea_orm::sqlx::query(AssertSqlSafe(format!(
                        "PRAGMA schema_version = {next_sv};"
                    )))
                    .persistent(false)
                    .execute(&mut conn)
                    .await
                    .expect("advance schema_version");

                    // Touch pages across existing tables while `writable_schema = ON`
                    // so `pcache1` hits its minimum cap (`cache_size = 1`, `cache_spill = 1`)
                    // and `pagerStress()` syncs the genuine hot `-journal` (original Page 1)
                    // AND writes dirty Page 1 to the main `.db` file BEFORE `COMMIT`!
                    for tbl in &tables {
                        let sql = format!("SELECT COUNT(*) FROM \"{tbl}\";");
                        let _: i64 = sea_orm::sqlx::query_scalar(AssertSqlSafe(sql))
                            .persistent(false)
                            .fetch_one(&mut conn)
                            .await
                            .expect("scan table page to drive cache spill");
                    }
                    let _ = sea_orm::sqlx::query("PRAGMA shrink_memory;")
                        .persistent(false)
                        .execute(&mut conn)
                        .await;
                    sea_orm::sqlx::query("PRAGMA writable_schema = OFF;")
                        .persistent(false)
                        .execute(&mut conn)
                        .await
                        .expect("disable writable_schema");

                    let journal_path = sqlite_sidecar_path(&target, "-journal");
                    let j_bytes = fs::read(&journal_path)
                        .expect("hot -journal must exist on disk after pager spill");
                    assert!(
                        j_bytes.len() >= 512 + 4096
                            && j_bytes[..8] == SQLITE_HOT_ROLLBACK_JOURNAL_MAGIC,
                        "hot -journal must have valid SQLite hot journal magic and at least one full page (len={})",
                        j_bytes.len()
                    );
                    let db_bytes = fs::read(&target).expect("read target db bytes before crash");
                    let sentinel = SQLITE_MIGRATED_FENCE_SQL.as_bytes();
                    assert!(
                        db_bytes.windows(sentinel.len()).any(|w| w == sentinel),
                        "dirty uncommitted fence Page 1 must have spilled to disk before simulated powerloss"
                    );

                    println!("RB10C_POWERLOSS_SPILLED_OK");
                    let _ = std::io::stdout().flush();

                    // Simulate sudden powerloss / SIGKILL: terminate process
                    // immediately WITHOUT dropping `conn` or calling sqlite3_close!
                    #[cfg(unix)]
                    unsafe {
                        libc::_exit(0);
                    }
                    #[cfg(windows)]
                    unsafe {
                        windows_sys::Win32::System::Threading::ExitProcess(0);
                    }
                }
                Some("hold_wal_write_lock") => {
                    let opts = SqliteConnectOptions::new()
                        .filename(&target)
                        .create_if_missing(false)
                        .read_only(false)
                        .busy_timeout(Duration::ZERO);
                    let mut conn = SqliteConnection::connect_with(&opts)
                        .await
                        .expect("open target db in hold_wal_write_lock child");
                    set_wal_checkpoint_on_close(&mut conn, DatabaseRole::Repository, true)
                        .await
                        .expect("disable checkpoint on close in blocker");
                    conn.execute("BEGIN IMMEDIATE;")
                        .await
                        .expect("BEGIN IMMEDIATE in blocker");
                    sea_orm::sqlx::query(
                        "INSERT INTO config_kv (key, value, encrypted) VALUES ('blocker.tx', '1', 0);",
                    )
                    .execute(&mut conn)
                    .await
                    .expect("insert blocker row");
                    println!("RB10C_WRITER_READY");
                    let _ = std::io::stdout().flush();
                    let mut sink = String::new();
                    let _ = std::io::stdin().read_to_string(&mut sink);
                    let _ = conn.execute("ROLLBACK;").await;
                    let _ = conn.close().await;
                    return;
                }
                other => panic!("unexpected LIBRA_RB10C_CHILD_MODE: {other:?}"),
            }
        }

        // --------------------------------------------------------------------
        // Scenario 1 (AC1 & AC2): Exhaustive check across EVERY forward
        // `finalized == false` crash checkpoint — BOTH `LIBRA_STORAGE_BACKEND=redb`
        // AND `LIBRA_STORAGE_BACKEND=sqlite` MUST fail closed with `LBR-IO-001`!
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10c Scenario 1 tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-s1").await;

            let prepared = prepare_forward_phase1(&storage, 1)
                .await
                .expect("Phase 1 prepare must succeed");

            let mut p2_checkpoints = 0usize;
            let mut p2_hook = |point: Phase2TestPoint, root: &Path| -> StorageResult<()> {
                let m = read_storage_manifest(root)?.expect("manifest must exist");
                assert!(!m.finalized);
                assert_rb10c_unfinalized_rejects_both_env_overrides(root, &format!("{point:?}"));
                p2_checkpoints += 1;
                Ok(())
            };
            let fenced =
                execute_forward_phase2_fence_and_unlink_inner(prepared, Some(&mut p2_hook))
                    .await
                    .expect("Step 2.1-2.2b must succeed");
            assert!(
                p2_checkpoints >= 11,
                "expected at least 11 Step 2.1-2.2b checkpoints checked, got {p2_checkpoints}"
            );

            let mut fin_checkpoints = 0usize;
            let mut fin_hook = |point: Phase2FinalizeTestPoint, root: &Path| -> StorageResult<()> {
                match point {
                    Phase2FinalizeTestPoint::AfterSpoolTombstonesBeforePersistSpoolFenced
                    | Phase2FinalizeTestPoint::AfterPersistSpoolFencedBeforeFinalized => {
                        let m = read_storage_manifest(root)?.expect("manifest must exist");
                        assert!(!m.finalized);
                        assert_rb10c_unfinalized_rejects_both_env_overrides(
                            root,
                            &format!("{point:?}"),
                        );
                        fin_checkpoints += 1;
                    }
                    _ => {}
                }
                Ok(())
            };
            let report = finalize_forward_phase2_spool_tombstones_and_manifest_inner(
                fenced,
                Some(&mut fin_hook),
            )
            .expect("Step 2.3-2.4 must succeed");
            assert_eq!(fin_checkpoints, 2);
            assert!(report.manifest.finalized);
        }

        // --------------------------------------------------------------------
        // Scenario 2 (AC3 primary): Mid-fence-commit powerloss on `libra.db`
        // (genuine SQLite hot `libra.db-journal` + first 512-byte physical
        // sector of Page 1 torn with garbage) -> resume triggers SQLite hot
        // rollback journal automatic lossless rollback, verifies
        // `source_logical_sha256`, and completes fence through `finalized=true`!
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10c Scenario 2 tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-s2").await;
            crash_after_step2_1_pending(&storage, 1).await;

            let git_db = git_sqlite_db_path(&storage);
            let git_journal = sqlite_sidecar_path(&git_db, "-journal");
            let cap_db = capture_sqlite_db_path(&storage);

            // Spawn isolated child to execute real fence SQL up to page spill
            // and hard-exit without closing SQLite (leaving a real hot journal!).
            let exe = std::env::current_exe().expect("locate current test executable");
            let child_out = Command::new(&exe)
                .arg("--exact")
                .arg("storage::migrate::tests::forward_phase2_powerloss_torn_sector_hot_journal_rollback_and_resume")
                .arg("--nocapture")
                .env("LIBRA_RB10C_CHILD_MODE", "powerloss_mid_fence")
                .env("LIBRA_RB10C_TARGET_PATH", &git_db)
                .env("LIBRA_TEST", "1")
                .output()
                .expect("spawn powerloss_mid_fence child for libra.db");
            let child_stdout = String::from_utf8_lossy(&child_out.stdout);
            let child_stderr = String::from_utf8_lossy(&child_out.stderr);
            assert!(
                child_out.status.success() && child_stdout.contains("RB10C_POWERLOSS_SPILLED_OK"),
                "powerloss_mid_fence child failed ({:?}):\nstdout:\n{child_stdout}\nstderr:\n{child_stderr}",
                child_out.status
            );

            // Verify hot `libra.db-journal` survived child exit intact.
            let journal_bytes = fs::read(&git_journal).expect("hot libra.db-journal must remain");
            assert_eq!(
                &journal_bytes[..8],
                &SQLITE_HOT_ROLLBACK_JOURNAL_MAGIC,
                "hot journal magic must be intact on disk after powerloss"
            );

            // Corrupt the ENTIRE first 512-byte physical sector of Page 1 in
            // `libra.db` (destroying `"SQLite format 3\0"`, page size, change
            // counter, schema cookie, and the first 412 bytes of `sqlite_master`!).
            {
                let mut f = OpenOptions::new()
                    .read(true)
                    .write(true)
                    .open(&git_db)
                    .expect("open libra.db to inject 512-byte torn sector");
                let mut torn_sector = [0u8; 512];
                for (i, b) in torn_sector.iter_mut().enumerate() {
                    *b = if i % 2 == 0 { 0xA5 } else { 0x5A };
                }
                f.write_all(&torn_sector)
                    .expect("write 512-byte torn sector over page 1");
                f.sync_all().expect("fsync torn libra.db");
            }
            let torn_head = fs::read(&git_db).expect("read torn libra.db");
            assert_ne!(
                &torn_head[..16],
                b"SQLite format 3\0",
                "page 1 SQLite header must genuinely be torn on disk before resume"
            );

            // Verify AC1 & AC2 fail closed at this exact torn-sector + hot-journal state!
            assert_rb10c_unfinalized_rejects_both_env_overrides(
                &storage,
                "torn_sector_hot_journal",
            );

            // Resume! Must automatically trigger SQLite hot-journal rollback over
            // the torn 512-byte sector, match `source_logical_sha256` with ZERO
            // drift re-export, fence + unlink both DBs, install spool tombstones,
            // and publish `storage-format.json(finalized = true)` at generation 1!
            let resumed = resume_forward_migration(&storage)
                .await
                .expect("resume_forward_migration must recover torn page-1 sector via hot journal");

            assert_eq!(resumed.initial_generation, 1);
            assert_eq!(resumed.final_generation, 1);
            assert!(!resumed.reexported_due_to_drift);
            assert_eq!(
                resumed.git_recovery_state,
                ForwardSourceRecoveryState::CleanMatchedPending
            );
            assert_eq!(
                resumed.capture_recovery_state,
                ForwardSourceRecoveryState::CleanMatchedPending
            );
            assert!(
                resumed.git_hot_journal_recovered,
                "resume must record hot rollback journal recovery on libra.db"
            );
            assert!(!resumed.capture_hot_journal_recovered);
            assert!(resumed.finalized.manifest.finalized);
            assert_eq!(resumed.finalized.manifest.backend, StorageBackendKind::Redb);
            assert_eq!(
                resumed.finalized.manifest.phase2_progress.git_db,
                Some(Phase2DbState::Unlinked)
            );
            assert_eq!(
                resumed.finalized.manifest.phase2_progress.capture_db,
                Some(Phase2DbState::Unlinked)
            );
            assert!(resumed.finalized.manifest.phase2_progress.spool_fenced);

            // Persisted manifest on disk matches & all legacy SQLite files are gone.
            let disk_manifest = read_storage_manifest(&storage)
                .expect("read finalized manifest")
                .expect("finalized manifest must exist");
            assert!(disk_manifest.finalized);
            assert_eq!(disk_manifest.generation, 1);
            assert!(!git_db.exists(), "libra.db must be unlinked after resume");
            assert!(
                !git_journal.exists(),
                "libra.db-journal must be cleared after resume"
            );
            assert!(!cap_db.exists(), "capture.db must be unlinked after resume");
            assert!(
                !sqlite_sidecar_path(&cap_db, "-journal").exists(),
                "capture.db-journal must be cleared after resume"
            );

            // All 3 capture-spool tombstones are installed and read-only.
            for slot in CAPTURE_SPOOL_TOMBSTONE_NAMES {
                let p = capture_spool_dir_path(&storage).join(slot);
                let meta = fs::symlink_metadata(&p).expect("stat spool tombstone");
                assert!(meta.file_type().is_file());
                assert_eq!(
                    fs::read(&p).expect("read tombstone"),
                    CAPTURE_SPOOL_TOMBSTONE_SENTINEL
                );
            }

            // Target redb stores are intact and contain pre-crash records.
            let git_store = RedbGitStore::open_read_only(&resumed.finalized.git_redb_path)
                .expect("open finalized git.gen-00000001.redb");
            let refs = git_store
                .list_refs(None)
                .await
                .expect("list refs from finalized redb");
            assert!(
                !refs.is_empty(),
                "finalized git redb must preserve repository references"
            );
            let cap_store = RedbCaptureStore::open_read_only(&resumed.finalized.capture_redb_path)
                .await
                .expect("open finalized capture.gen-00000001.redb");
            let sessions = cap_store
                .list_sessions_by_started_desc()
                .await
                .expect("list sessions from finalized capture redb");
            assert!(
                !sessions.is_empty(),
                "finalized capture redb must preserve capture sessions"
            );

            // All 6 non-SQLite locks are released and re-acquirable.
            let _locks = acquire_forward_recovery_non_sqlite_locks(&storage)
                .expect("all 6 non-SQLite locks must be released after finalized resume");
        }

        // --------------------------------------------------------------------
        // Scenario 3 (AC3 `capture.db` torn sector + hot journal, AND negative
        // control: torn 512-byte sector WITHOUT hot journal MUST fail closed!)
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10c Scenario 3a tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-s3a").await;
            crash_after_step2_1_pending(&storage, 1).await;

            let cap_db = capture_sqlite_db_path(&storage);
            let exe = std::env::current_exe().expect("locate current test executable");
            let child_out = Command::new(&exe)
                .arg("--exact")
                .arg("storage::migrate::tests::forward_phase2_powerloss_torn_sector_hot_journal_rollback_and_resume")
                .arg("--nocapture")
                .env("LIBRA_RB10C_CHILD_MODE", "powerloss_mid_fence")
                .env("LIBRA_RB10C_TARGET_PATH", &cap_db)
                .env("LIBRA_TEST", "1")
                .output()
                .expect("spawn powerloss_mid_fence child for capture.db");
            let child_stdout = String::from_utf8_lossy(&child_out.stdout);
            let child_stderr = String::from_utf8_lossy(&child_out.stderr);
            assert!(
                child_out.status.success() && child_stdout.contains("RB10C_POWERLOSS_SPILLED_OK"),
                "capture.db powerloss child failed ({:?}):\nstdout:\n{child_stdout}\nstderr:\n{child_stderr}",
                child_out.status
            );
            {
                let mut f = OpenOptions::new()
                    .read(true)
                    .write(true)
                    .open(&cap_db)
                    .expect("open capture.db to tear page 1");
                f.write_all(&[0xC3u8; 512])
                    .expect("write 512-byte torn sector to capture.db");
                f.sync_all().expect("fsync torn capture.db");
            }

            let resumed = resume_forward_migration(&storage)
                .await
                .expect("resume must also recover capture.db torn sector via hot journal");
            assert!(resumed.capture_hot_journal_recovered);
            assert_eq!(resumed.final_generation, 1);
            assert!(!resumed.reexported_due_to_drift);
            assert!(resumed.finalized.manifest.finalized);
        }

        {
            // Negative control: torn first 512 bytes WITHOUT a hot `-journal`
            // MUST fail closed (`LBR-IO-001`), never silently dropping data!
            let dir = tempdir().expect("create RB-10c Scenario 3b negative tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-s3b").await;
            crash_after_step2_1_pending(&storage, 1).await;

            let git_db = git_sqlite_db_path(&storage);
            assert!(!sqlite_sidecar_path(&git_db, "-journal").exists());
            {
                let mut f = OpenOptions::new()
                    .read(true)
                    .write(true)
                    .open(&git_db)
                    .expect("open libra.db for negative torn-sector test");
                f.write_all(&[0xEEu8; 512])
                    .expect("write torn sector without hot journal");
                f.sync_all().expect("fsync torn libra.db");
            }

            let err = resume_forward_migration(&storage)
                .await
                .expect_err("torn page-1 sector without hot journal MUST fail closed");
            assert_eq!(err.stable_code_str(), "LBR-IO-001");
            assert!(
                git_db.exists(),
                "failed resume must NOT unlink corrupt libra.db"
            );
            let still_unfinalized = read_storage_manifest(&storage)
                .expect("read manifest after failed resume")
                .expect("manifest must still exist");
            assert!(!still_unfinalized.finalized);
            assert!(storage_manifest_path(&storage).exists());
        }

        // --------------------------------------------------------------------
        // Scenario 4 (Promoted redb target integrity & source-to-target binding):
        // A damaged or substituted `git.gen-00000001.redb` or
        // `capture.gen-00000001.redb` whose `META_SCHEMA` stays 100% valid MUST
        // fail closed (`LBR-IO-001`) BEFORE fencing/unlinking healthy SQLite
        // sources or publishing `finalized = true`!
        // --------------------------------------------------------------------
        {
            // 4a(i): `git.gen-00000001.redb` keeps valid `META_SCHEMA` but has
            // its `reference` business table emptied!
            let dir = tempdir().expect("create RB-10c Scenario 4a-i tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-s4a-empty").await;
            crash_after_step2_1_pending(&storage, 1).await;

            let git_redb = git_redb_path(&storage, 1);
            let git_db = git_sqlite_db_path(&storage);
            let cap_db = capture_sqlite_db_path(&storage);
            {
                let db = RedbBuilder::new()
                    .set_concurrency_mode(ConcurrencyMode::MultiWriter)
                    .open(&git_redb)
                    .expect("open promoted git.gen-00000001.redb to tamper");
                let wtx = db.begin_write().expect("begin tamper write txn");
                {
                    let mut ref_tbl = wtx
                        .open_table(redb_git::REFERENCE_TABLE)
                        .expect("open reference table");
                    let keys: Vec<(u8, String, String)> = ref_tbl
                        .iter()
                        .expect("iter refs")
                        .map(|r| {
                            let g = r.expect("ref row");
                            let (k0, k1, k2) = g.0.value();
                            (k0, k1.to_string(), k2.to_string())
                        })
                        .collect();
                    assert!(!keys.is_empty(), "fixture must have references");
                    for (k0, k1, k2) in keys {
                        let _ = ref_tbl
                            .remove((k0, k1.as_str(), k2.as_str()))
                            .expect("remove ref row");
                    }
                }
                wtx.commit().expect("commit tampered git redb");
            }

            let err = resume_forward_migration(&storage)
                .await
                .expect_err("recovery MUST reject valid-META_SCHEMA emptied git redb");
            assert_eq!(err.stable_code_str(), "LBR-IO-001");
            assert!(
                git_db.exists() && cap_db.exists(),
                "healthy SQLite sources must NOT be unlinked on tampered git redb"
            );
            let m = read_storage_manifest(&storage)
                .expect("read manifest")
                .expect("manifest must still exist");
            assert!(!m.finalized);
        }

        {
            // 4a(ii): `git.gen-00000001.redb` keeps valid `META_SCHEMA` AND
            // identical row counts, but has a mutated `config_kv` payload!
            let dir = tempdir().expect("create RB-10c Scenario 4a-ii tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-s4a-mutated").await;
            crash_after_step2_1_pending(&storage, 1).await;

            let git_redb = git_redb_path(&storage, 1);
            let git_db = git_sqlite_db_path(&storage);
            {
                let db = RedbBuilder::new()
                    .set_concurrency_mode(ConcurrencyMode::MultiWriter)
                    .open(&git_redb)
                    .expect("open promoted git.gen-00000001.redb for payload tamper");
                let wtx = db.begin_write().expect("begin payload tamper write txn");
                {
                    let mut cfg_tbl = wtx
                        .open_table(redb_cfg::CONFIG_KV_TABLE)
                        .expect("open config_kv table");
                    let first_entry = cfg_tbl
                        .first()
                        .expect("read first config_kv")
                        .expect("fixture must have config_kv rows");
                    let first_id = first_entry.0.value();
                    let mut decoded: MigConfigKvStoredRow =
                        decode_versioned(first_entry.1.value(), redb_cfg::CONFIG_KV_CODEC_VERSION)
                            .expect("decode first config_kv");
                    drop(first_entry);
                    decoded.value = "TAMPERED_PAYLOAD_VALUE".to_string();
                    let encoded = encode_versioned(redb_cfg::CONFIG_KV_CODEC_VERSION, &decoded)
                        .expect("re-encode tampered config_kv");
                    let _ = cfg_tbl
                        .insert(first_id, encoded.as_slice())
                        .expect("overwrite tampered config_kv");
                }
                wtx.commit().expect("commit payload-tampered git redb");
            }

            let err = resume_forward_migration(&storage)
                .await
                .expect_err("recovery MUST reject same-row-count payload-tampered git redb");
            assert_eq!(err.stable_code_str(), "LBR-IO-001");
            assert!(git_db.exists(), "libra.db must remain intact");
            let m = read_storage_manifest(&storage)
                .expect("read manifest")
                .expect("manifest must exist");
            assert!(!m.finalized);
        }

        {
            // 4b: `capture.gen-00000001.redb` keeps valid `META_SCHEMA` AND
            // internally consistent secondary indexes, but has `agent_session`
            // and its indexes cleared!
            let dir = tempdir().expect("create RB-10c Scenario 4b tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-s4b-cap").await;
            crash_after_step2_1_pending(&storage, 1).await;

            let cap_redb = capture_redb_path(&storage, 1);
            let git_db = git_sqlite_db_path(&storage);
            let cap_db = capture_sqlite_db_path(&storage);
            {
                let db = RedbBuilder::new()
                    .set_concurrency_mode(ConcurrencyMode::MultiWriter)
                    .open(&cap_redb)
                    .expect("open promoted capture.gen-00000001.redb to tamper");
                let wtx = db.begin_write().expect("begin capture tamper write txn");
                {
                    let mut sess_tbl = wtx
                        .open_table(redb_cap::AGENT_SESSION_TABLE)
                        .expect("open agent_session");
                    let keys: Vec<String> = sess_tbl
                        .iter()
                        .expect("iter sessions")
                        .map(|r| r.expect("sess row").0.value().to_string())
                        .collect();
                    assert!(!keys.is_empty(), "fixture must have sessions");
                    for k in keys {
                        let _ = sess_tbl.remove(k.as_str()).expect("remove session");
                    }
                    let mut sbt = wtx
                        .open_table(redb_cap::SESSIONS_BY_TIME_TABLE)
                        .expect("open sessions_by_time");
                    let sbt_keys: Vec<(u64, String)> = sbt
                        .iter()
                        .expect("iter sbt")
                        .map(|r| {
                            let g = r.expect("sbt row");
                            (g.0.value().0, g.0.value().1.to_string())
                        })
                        .collect();
                    for (ts, sid) in sbt_keys {
                        let _ = sbt.remove((ts, sid.as_str())).expect("remove sbt");
                    }
                    let mut sbp = wtx
                        .open_table(redb_cap::SESSIONS_BY_PROVIDER_TABLE)
                        .expect("open sessions_by_provider");
                    let sbp_keys: Vec<(String, String)> = sbp
                        .iter()
                        .expect("iter sbp")
                        .map(|r| {
                            let g = r.expect("sbp row");
                            (g.0.value().0.to_string(), g.0.value().1.to_string())
                        })
                        .collect();
                    for (ak, psid) in sbp_keys {
                        let _ = sbp
                            .remove((ak.as_str(), psid.as_str()))
                            .expect("remove sbp");
                    }
                }
                wtx.commit().expect("commit tampered capture redb");
            }

            let err = resume_forward_migration(&storage)
                .await
                .expect_err("recovery MUST reject valid-META_SCHEMA emptied capture redb");
            assert_eq!(err.stable_code_str(), "LBR-IO-001");
            assert!(
                git_db.exists() && cap_db.exists(),
                "healthy SQLite sources must NOT be unlinked on tampered capture redb"
            );
            let m = read_storage_manifest(&storage)
                .expect("read manifest")
                .expect("manifest must still exist");
            assert!(!m.finalized);
        }

        {
            // 4c: Unsampled interior row mutation in `reference` AND unsampled
            // table mutation in `automation_log` (keeping META_SCHEMA, counts,
            // secondary indexes, and first/mid/last sampled rows 100% identical!)
            // MUST BOTH fail closed (`LBR-IO-001`)!
            let dir = tempdir().expect("create RB-10c Scenario 4c unsampled-git tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-s4c-unsamp").await;

            // Insert 20 extra `reference` rows so interior row `unsampled-ref-0007`
            // is strictly outside first/middle/last sampled offsets!
            let git_db = git_sqlite_db_path(&storage);
            {
                let mut gconn = SqliteConnection::connect_with(
                    &SqliteConnectOptions::new()
                        .filename(&git_db)
                        .create_if_missing(false),
                )
                .await
                .expect("open libra.db to seed unsampled refs");
                for i in 0..20usize {
                    let name = format!("unsampled-ref-{i:04}");
                    let hex = format!("{:040x}", 0x1000 + i);
                    sea_orm::sqlx::query(
                        "INSERT INTO reference (name, kind, \"commit\", remote, worktree_id) VALUES (?1, 'Branch', ?2, NULL, NULL);",
                    )
                    .bind(&name)
                    .bind(&hex)
                    .execute(&mut gconn)
                    .await
                    .expect("insert unsampled ref");
                }
                gconn.close().await.expect("close gconn");
            }
            crash_after_step2_1_pending(&storage, 1).await;

            let git_redb = git_redb_path(&storage, 1);
            let orig_git_redb_bytes = fs::read(&git_redb).expect("snapshot clean git redb");

            // Subcase 4c(i): Mutate ONLY unsampled interior row `unsampled-ref-0007`!
            {
                let db = RedbBuilder::new()
                    .set_concurrency_mode(ConcurrencyMode::MultiWriter)
                    .open(&git_redb)
                    .expect("open git redb for unsampled interior ref tamper");
                let wtx = db.begin_write().expect("begin write");
                {
                    let mut tbl = wtx
                        .open_table(redb_git::REFERENCE_TABLE)
                        .expect("open reference");
                    let target_ref = RefKey::LocalBranch {
                        name: "unsampled-ref-0007".to_string(),
                    };
                    let target_key = encode_mig_ref_key(&target_ref);
                    assert!(
                        tbl.get(target_key)
                            .expect("lookup unsampled-ref-0007")
                            .is_some(),
                        "unsampled-ref-0007 must exist in promoted git redb"
                    );
                    let tampered = MigRefTargetStored {
                        target: RefTarget::Direct("deadbeef".repeat(5)),
                    };
                    let encoded = encode_versioned(redb_git::GIT_REF_CODEC_VERSION, &tampered)
                        .expect("encode tampered ref");
                    let _ = tbl
                        .insert(target_key, encoded.as_slice())
                        .expect("overwrite unsampled interior ref");
                }
                wtx.commit().expect("commit unsampled ref tamper");
            }
            let err_ref = resume_forward_migration(&storage)
                .await
                .expect_err("recovery MUST reject unsampled interior reference mutation");
            assert_eq!(err_ref.stable_code_str(), "LBR-IO-001");
            assert!(git_db.exists());
            assert!(
                !read_storage_manifest(&storage)
                    .expect("read manifest")
                    .expect("manifest exists")
                    .finalized
            );

            // Subcase 4c(ii): Restore clean git redb, then mutate ONLY a single
            // field in unsampled table `automation_log`!
            fs::write(&git_redb, &orig_git_redb_bytes).expect("restore clean git redb");
            {
                let db = RedbBuilder::new()
                    .set_concurrency_mode(ConcurrencyMode::MultiWriter)
                    .open(&git_redb)
                    .expect("open git redb for unsampled automation_log tamper");
                let wtx = db.begin_write().expect("begin write");
                {
                    let mut tbl = wtx
                        .open_table(redb_state::AUTOMATION_LOG_TABLE)
                        .expect("open automation_log");
                    let first = tbl
                        .first()
                        .expect("read first automation_log")
                        .expect("fixture must have automation_log row");
                    let key_id = first.0.value().to_string();
                    let mut rec: AutomationLogRecord =
                        decode_versioned(first.1.value(), redb_state::GIT_STATE_CODEC_VERSION)
                            .expect("decode automation_log");
                    drop(first);
                    rec.message = "TAMPERED_UNSAMPLED_TABLE".to_string();
                    let encoded = encode_versioned(redb_state::GIT_STATE_CODEC_VERSION, &rec)
                        .expect("encode tampered automation_log");
                    let _ = tbl
                        .insert(key_id.as_str(), encoded.as_slice())
                        .expect("overwrite automation_log");
                }
                wtx.commit().expect("commit automation_log tamper");
            }
            let err_auto = resume_forward_migration(&storage)
                .await
                .expect_err("recovery MUST reject mutation in unsampled git table automation_log");
            assert_eq!(err_auto.stable_code_str(), "LBR-IO-001");
            assert!(git_db.exists());
            assert!(
                !read_storage_manifest(&storage)
                    .expect("read manifest")
                    .expect("manifest exists")
                    .finalized
            );
        }

        {
            // 4d: Unsampled table mutation in `capture.gen-00000001.redb`
            // (`agent_bridge_session` — zero field sampling in Phase 1!) MUST
            // fail closed (`LBR-IO-001`) before fencing/unlinking!
            let dir = tempdir().expect("create RB-10c Scenario 4d unsampled-cap tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-s4d-unsamp").await;
            crash_after_step2_1_pending(&storage, 1).await;

            let cap_redb = capture_redb_path(&storage, 1);
            let git_db = git_sqlite_db_path(&storage);
            let cap_db = capture_sqlite_db_path(&storage);
            {
                let db = RedbBuilder::new()
                    .set_concurrency_mode(ConcurrencyMode::MultiWriter)
                    .open(&cap_redb)
                    .expect("open capture redb for unsampled agent_bridge_session tamper");
                let wtx = db.begin_write().expect("begin write");
                {
                    let mut tbl = wtx
                        .open_table(redb_cap::AGENT_BRIDGE_SESSION_TABLE)
                        .expect("open agent_bridge_session");
                    let first = tbl
                        .first()
                        .expect("read first agent_bridge_session")
                        .expect("fixture must have agent_bridge_session row");
                    let key_id = first.0.value().to_string();
                    let mut rec: AgentBridgeSessionRecord =
                        decode_versioned(first.1.value(), redb_cap::CAPTURE_CODEC_VERSION)
                            .expect("decode agent_bridge_session");
                    drop(first);
                    rec.last_acked_seq = rec.last_acked_seq.saturating_add(999);
                    let encoded = encode_versioned(redb_cap::CAPTURE_CODEC_VERSION, &rec)
                        .expect("encode tampered agent_bridge_session");
                    let _ = tbl
                        .insert(key_id.as_str(), encoded.as_slice())
                        .expect("overwrite agent_bridge_session");
                }
                wtx.commit().expect("commit agent_bridge_session tamper");
            }
            let err_cap = resume_forward_migration(&storage).await.expect_err(
                "recovery MUST reject mutation in unsampled capture table agent_bridge_session",
            );
            assert_eq!(err_cap.stable_code_str(), "LBR-IO-001");
            assert!(git_db.exists() && cap_db.exists());
            assert!(
                !read_storage_manifest(&storage)
                    .expect("read manifest")
                    .expect("manifest exists")
                    .finalized
            );
        }

        {
            // 4e: Oversized chunked spool envelope interior-chunk tamper inside
            // `MIGRATED_SPOOL_ENVELOPE_CHUNKS_TABLE` (leaving `MIGRATED_SPOOL_RECEIPTS_TABLE`,
            // chunk count, table inventory, and `META_SCHEMA` 100% intact!)
            // MUST fail closed (`LBR-IO-001`) before fencing/unlinking!
            let dir = tempdir().expect("create RB-10c Scenario 4e chunked-spool-tamper tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-s4e-chunks").await;

            // Add an oversized ~200 KiB spool event producing >= 3 chunks (0, 1, 2, ...).
            let spool_ready = capture_spool_dir_path(&storage).join(CAPTURE_SPOOL_READY_SUBDIR);
            let big_padding = "P".repeat(200 * 1024);
            fs::write(
                spool_ready.join("0002-oversized-chunked.json"),
                build_spool_envelope_bytes(
                    "codex",
                    "codex",
                    "33333333-3333-4333-8333-33333333334e",
                    Some("dedup:rb10c-s4e:oversized-chunked"),
                    "prov-rb10c-s4e-chunks",
                    "/work/rb10c-s4e-chunks",
                    &storage,
                    "tool_use",
                    "2026-11-24T01:10:00Z",
                    &big_padding,
                ),
            )
            .expect("write oversized chunked spool event");

            crash_after_step2_1_pending(&storage, 1).await;

            let cap_redb = capture_redb_path(&storage, 1);
            let git_db = git_sqlite_db_path(&storage);
            let cap_db = capture_sqlite_db_path(&storage);
            let orig_cap_redb_bytes = fs::read(&cap_redb).expect("snapshot clean capture redb");

            // Flip 1 byte in interior chunk `chunk_idx == 1` while keeping exact
            // chunk count, receipt row, table inventory, and `META_SCHEMA`!
            {
                let db = RedbBuilder::new()
                    .set_concurrency_mode(ConcurrencyMode::MultiWriter)
                    .open(&cap_redb)
                    .expect("open capture redb for chunk tamper");
                let wtx = db.begin_write().expect("begin chunk tamper write");
                {
                    let mut tbl = wtx
                        .open_table(MIGRATED_SPOOL_ENVELOPE_CHUNKS_TABLE)
                        .expect("open migrated_spool_envelope_chunks");
                    let chunk_count = tbl.len().expect("chunk table len");
                    assert!(
                        chunk_count >= 3,
                        "oversized 200 KiB spool event must span >= 3 chunks (got {chunk_count})"
                    );
                    let interior = tbl
                        .iter()
                        .expect("iter chunks")
                        .find_map(|entry| {
                            let (k, v) = entry.expect("chunk entry");
                            let (dedup_k, idx) = k.value();
                            if idx == 1 {
                                Some((dedup_k.to_string(), idx, v.value().to_vec()))
                            } else {
                                None
                            }
                        })
                        .expect("interior chunk idx=1 must exist");
                    let mut tampered_chunk = interior.2;
                    tampered_chunk[17] ^= 0xFF;
                    let _ = tbl
                        .insert((interior.0.as_str(), interior.1), tampered_chunk.as_slice())
                        .expect("overwrite interior chunk");
                }
                wtx.commit().expect("commit interior chunk tamper");
            }

            let err_chunk = resume_forward_migration(&storage).await.expect_err(
                "recovery MUST reject interior chunk mutation in MIGRATED_SPOOL_ENVELOPE_CHUNKS_TABLE",
            );
            assert_eq!(err_chunk.stable_code_str(), "LBR-IO-001");
            assert!(git_db.exists() && cap_db.exists());
            assert!(
                !read_storage_manifest(&storage)
                    .expect("read manifest")
                    .expect("manifest exists")
                    .finalized
            );

            // Restore clean `capture.gen-00000001.redb` (preserving `0o600` on Unix)
            // -> resume succeeds cleanly at `gen = 1`!
            fs::write(&cap_redb, &orig_cap_redb_bytes).expect("restore clean capture redb");
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt as _;
                fs::set_permissions(&cap_redb, fs::Permissions::from_mode(0o600))
                    .expect("restore 0600 on capture redb");
            }
            let resumed = resume_forward_migration(&storage)
                .await
                .expect("resume must succeed once chunked spool envelope matches backup");
            assert_eq!(resumed.final_generation, 1);
            assert!(resumed.finalized.manifest.finalized);
        }

        {
            // 4f: `meta_schema` tampering (extra row / changed `format_version`
            // that still passes `begin_checked_read`), unexpected ordinary table,
            // and unexpected multimap table on BOTH `git.gen-00000001.redb` AND
            // `capture.gen-00000001.redb` MUST ALL fail closed (`LBR-IO-001`)
            // before fencing/unlinking or finalization!
            use crate::storage::meta::{
                META_SCHEMA_CODEC_VERSION, META_SCHEMA_SINGLETON_KEY, META_SCHEMA_TABLE,
                MetaSchemaRecord, MetaSchemaRole,
            };
            const ROGUE_TABLE: TableDefinition<&str, &[u8]> =
                TableDefinition::new("rogue_extra_table");
            const ROGUE_MULTIMAP: redb::MultimapTableDefinition<&str, &[u8]> =
                redb::MultimapTableDefinition::new("rogue_multimap_table");

            let dir = tempdir().expect("create RB-10c Scenario 4f meta/inventory tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-s4f-inv").await;
            crash_after_step2_1_pending(&storage, 1).await;

            let git_redb = git_redb_path(&storage, 1);
            let cap_redb = capture_redb_path(&storage, 1);
            let git_db = git_sqlite_db_path(&storage);
            let cap_db = capture_sqlite_db_path(&storage);
            let orig_git_bytes = fs::read(&git_redb).expect("snapshot clean git redb");
            let orig_cap_bytes = fs::read(&cap_redb).expect("snapshot clean capture redb");

            let restore_clean = |target: &Path, bytes: &[u8], mode: u32| {
                fs::write(target, bytes).expect("restore clean redb");
                #[cfg(unix)]
                {
                    use std::os::unix::fs::PermissionsExt as _;
                    fs::set_permissions(target, fs::Permissions::from_mode(mode))
                        .expect("restore redb permissions");
                }
                #[cfg(not(unix))]
                let _ = mode;
            };

            for (label, target_path, orig_bytes, mode, role_tag) in [
                (
                    "git",
                    git_redb.as_path(),
                    orig_git_bytes.as_slice(),
                    0o644u32,
                    MetaSchemaRole::Repository,
                ),
                (
                    "capture",
                    cap_redb.as_path(),
                    orig_cap_bytes.as_slice(),
                    0o600u32,
                    MetaSchemaRole::Capture,
                ),
            ] {
                // Case 1a: Tamper ONLY the singleton `meta_schema` value bytes
                // (`format_version = 99`, keeping exact table len == 1 and
                // `min_reader_version = 1` so `begin_checked_read` passes!).
                {
                    let db = RedbBuilder::new()
                        .set_concurrency_mode(ConcurrencyMode::MultiWriter)
                        .open(target_path)
                        .expect("open redb for singleton meta_schema value tamper");
                    let wtx = db.begin_write().expect("begin write");
                    {
                        let mut tbl = wtx.open_table(META_SCHEMA_TABLE).expect("open meta_schema");
                        let altered = MetaSchemaRecord {
                            role: role_tag,
                            format_version: 99,
                            min_reader_version: 1,
                        };
                        let encoded = encode_versioned(META_SCHEMA_CODEC_VERSION, &altered)
                            .expect("encode altered meta_schema");
                        let _ = tbl
                            .insert(META_SCHEMA_SINGLETON_KEY, encoded.as_slice())
                            .expect("overwrite singleton meta_schema");
                    }
                    wtx.commit().expect("commit singleton meta_schema tamper");
                }
                let err_meta_val = resume_forward_migration(&storage)
                    .await
                    .expect_err(&format!(
                        "recovery MUST reject singleton meta_schema value tamper in {label} redb"
                    ));
                assert_eq!(err_meta_val.stable_code_str(), "LBR-IO-001");
                assert!(git_db.exists() && cap_db.exists());
                assert!(
                    !read_storage_manifest(&storage)
                        .expect("read manifest")
                        .expect("manifest exists")
                        .finalized
                );
                restore_clean(target_path, orig_bytes, mode);

                // Case 1b: Insert ONLY an extra row into `meta_schema` while
                // leaving the singleton record 100% untouched!
                {
                    let db = RedbBuilder::new()
                        .set_concurrency_mode(ConcurrencyMode::MultiWriter)
                        .open(target_path)
                        .expect("open redb for extra meta_schema row");
                    let wtx = db.begin_write().expect("begin write");
                    {
                        let mut tbl = wtx.open_table(META_SCHEMA_TABLE).expect("open meta_schema");
                        let _ = tbl
                            .insert("extra_meta_row", b"rogue".as_slice())
                            .expect("insert extra meta_schema row");
                    }
                    wtx.commit().expect("commit extra meta_schema row");
                }
                let err_meta_row = resume_forward_migration(&storage)
                    .await
                    .expect_err(&format!(
                        "recovery MUST reject extra meta_schema row in {label} redb"
                    ));
                assert_eq!(err_meta_row.stable_code_str(), "LBR-IO-001");
                assert!(git_db.exists() && cap_db.exists());
                assert!(
                    !read_storage_manifest(&storage)
                        .expect("read manifest")
                        .expect("manifest exists")
                        .finalized
                );
                restore_clean(target_path, orig_bytes, mode);

                // Case 2: Add unexpected ordinary table (`rogue_extra_table`).
                {
                    let db = RedbBuilder::new()
                        .set_concurrency_mode(ConcurrencyMode::MultiWriter)
                        .open(target_path)
                        .expect("open redb for rogue ordinary table");
                    let wtx = db.begin_write().expect("begin write");
                    {
                        let mut tbl = wtx
                            .open_table(ROGUE_TABLE)
                            .expect("create rogue ordinary table");
                        let _ = tbl
                            .insert("k", b"v".as_slice())
                            .expect("insert rogue ordinary row");
                    }
                    wtx.commit().expect("commit rogue ordinary table");
                }
                let err_extra = resume_forward_migration(&storage)
                    .await
                    .expect_err(&format!(
                        "recovery MUST reject unexpected ordinary table in {label} redb"
                    ));
                assert_eq!(err_extra.stable_code_str(), "LBR-IO-001");
                assert!(git_db.exists() && cap_db.exists());
                assert!(
                    !read_storage_manifest(&storage)
                        .expect("read manifest")
                        .expect("manifest exists")
                        .finalized
                );
                restore_clean(target_path, orig_bytes, mode);

                // Case 3: Add unexpected multimap table (`rogue_multimap_table`).
                {
                    let db = RedbBuilder::new()
                        .set_concurrency_mode(ConcurrencyMode::MultiWriter)
                        .open(target_path)
                        .expect("open redb for rogue multimap table");
                    let wtx = db.begin_write().expect("begin write");
                    {
                        let mut tbl = wtx
                            .open_multimap_table(ROGUE_MULTIMAP)
                            .expect("create rogue multimap table");
                        let _ = tbl
                            .insert("k", b"v".as_slice())
                            .expect("insert rogue multimap row");
                    }
                    wtx.commit().expect("commit rogue multimap table");
                }
                let err_mm = resume_forward_migration(&storage)
                    .await
                    .expect_err(&format!(
                        "recovery MUST reject unexpected multimap table in {label} redb"
                    ));
                assert_eq!(err_mm.stable_code_str(), "LBR-IO-001");
                assert!(git_db.exists() && cap_db.exists());
                assert!(
                    !read_storage_manifest(&storage)
                        .expect("read manifest")
                        .expect("manifest exists")
                        .finalized
                );
                restore_clean(target_path, orig_bytes, mode);
            }

            // Once both clean files are restored, resume succeeds at `gen = 1`!
            let resumed = resume_forward_migration(&storage)
                .await
                .expect("resume must succeed once clean meta_schema and table inventory restored");
            assert_eq!(resumed.final_generation, 1);
            assert!(resumed.finalized.manifest.finalized);
        }

        // --------------------------------------------------------------------
        // Scenario 5 (Spool backup authentication after complete tombstoning —
        // including `quarantine/` — AND Windows spool NTFS junction check):
        // Even when all 3 live tombstones (`tmp`, `ready`, `quarantine`) are
        // already installed and `spool_fenced = true`, a modified or deleted
        // file in `sqlite-backup/<gen>/capture-spool/quarantine/` MUST fail
        // closed (`LBR-IO-001`) instead of finalizing!
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10c Scenario 5 spool-backup-auth tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-s5-spoolbk").await;

            // Add a retained quarantine event before Phase 1 so `spool_manifest_sha256`
            // binds BOTH `ready/` AND `quarantine/`.
            let quar_dir = capture_spool_dir_path(&storage).join(CAPTURE_SPOOL_QUARANTINE_SUBDIR);
            fs::create_dir_all(&quar_dir).expect("create capture-spool/quarantine");
            let quar_bytes = b"{\"quarantined\":\"corrupt-event-retained\"}".to_vec();
            fs::write(quar_dir.join("corrupt-event.json"), &quar_bytes)
                .expect("write retained quarantine event");

            let prepared = prepare_forward_phase1(&storage, 1)
                .await
                .expect("Phase 1 prepare for Scenario 5");
            let fenced = execute_forward_phase2_fence_and_unlink(prepared)
                .await
                .expect("Phase 2 fence + unlink for Scenario 5");

            // Crash right AFTER all 3 spool tombstones AND `spool_fenced = true`
            // are persisted, right BEFORE `finalized = true`!
            let mut stop_before_final = |pt: Phase2FinalizeTestPoint, _root: &Path| {
                if pt == Phase2FinalizeTestPoint::AfterPersistSpoolFencedBeforeFinalized {
                    return Err(StorageBackendError::BackendInternal {
                        detail: "injected crash after spool_fenced before finalized".to_string(),
                    });
                }
                Ok(())
            };
            let _ = finalize_forward_phase2_spool_tombstones_and_manifest_inner(
                fenced,
                Some(&mut stop_before_final),
            )
            .expect_err("injected crash before finalized must abort");

            let m_pre = read_storage_manifest(&storage)
                .expect("read manifest")
                .expect("manifest exists");
            assert!(!m_pre.finalized);
            assert!(m_pre.phase2_progress.spool_fenced);

            let bk_quar_file = sqlite_backup_dir_path(&storage, 1)
                .join(CAPTURE_SPOOL_SUBDIR)
                .join(CAPTURE_SPOOL_QUARANTINE_SUBDIR)
                .join("corrupt-event.json");
            assert!(bk_quar_file.is_file());

            // 5a: Tamper 1 byte in backed-up `quarantine/corrupt-event.json` -> MUST fail closed!
            let mut tampered_quar = quar_bytes.clone();
            tampered_quar[2] ^= 0xFF;
            fs::write(&bk_quar_file, &tampered_quar).expect("tamper backup quarantine file");
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt as _;
                fs::set_permissions(&bk_quar_file, fs::Permissions::from_mode(0o600))
                    .expect("preserve 0600 on tampered backup file");
            }
            let err_mod = resume_forward_migration(&storage).await.expect_err(
                "modified backed-up quarantine file after tombstoning MUST fail closed",
            );
            assert_eq!(err_mod.stable_code_str(), "LBR-IO-001");
            assert!(
                !read_storage_manifest(&storage)
                    .expect("read manifest")
                    .expect("manifest exists")
                    .finalized
            );

            // 5b: Delete backed-up `quarantine/corrupt-event.json` -> MUST fail closed!
            fs::remove_file(&bk_quar_file).expect("delete backup quarantine file");
            let err_del = resume_forward_migration(&storage)
                .await
                .expect_err("missing backed-up quarantine file after tombstoning MUST fail closed");
            assert_eq!(err_del.stable_code_str(), "LBR-IO-001");
            assert!(
                !read_storage_manifest(&storage)
                    .expect("read manifest")
                    .expect("manifest exists")
                    .finalized
            );

            // 5c: Restore exact authentic backup file -> resume MUST succeed at gen = 1!
            fs::write(&bk_quar_file, &quar_bytes)
                .expect("restore authentic backup quarantine file");
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt as _;
                fs::set_permissions(&bk_quar_file, fs::Permissions::from_mode(0o600))
                    .expect("restore 0600 mode on backup quarantine file");
            }
            let resumed = resume_forward_migration(&storage)
                .await
                .expect("resume must succeed once complete spool backup matches manifest");
            assert_eq!(resumed.final_generation, 1);
            assert!(resumed.finalized.manifest.finalized);
            assert!(resumed.finalized.manifest.phase2_progress.spool_fenced);
        }

        #[cfg(windows)]
        {
            // 5d (Windows NTFS junction regression for live spool inspection):
            // Replacing `capture-spool/quarantine` with an NTFS directory junction
            // pointing outside `.libra/` MUST fail closed (`LBR-IO-001`)!
            let dir = tempdir().expect("create RB-10c Scenario 5d win-spool-junction tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-s5d-junc").await;
            crash_after_step2_1_pending(&storage, 1).await;

            let outside_dir = dir.path().join("outside-spool-decoy");
            fs::create_dir_all(&outside_dir).expect("create outside spool decoy dir");
            let decoy_file = outside_dir.join("secret.json");
            fs::write(&decoy_file, b"DO_NOT_TRAVERSE").expect("write decoy file");

            let quar_junc = capture_spool_dir_path(&storage).join(CAPTURE_SPOOL_QUARANTINE_SUBDIR);
            if quar_junc.exists() {
                let _ = fs::remove_dir_all(&quar_junc);
            }
            let mklink_status = Command::new("cmd")
                .args(["/C", "mklink", "/J"])
                .arg(&quar_junc)
                .arg(&outside_dir)
                .status()
                .expect("spawn cmd mklink /J for spool inspection junction test");
            assert!(
                mklink_status.success(),
                "cmd /C mklink /J failed: {mklink_status:?}"
            );
            let err_junc = resume_forward_migration(&storage)
                .await
                .expect_err("NTFS junction at capture-spool/quarantine MUST fail closed");
            assert_eq!(err_junc.stable_code_str(), "LBR-IO-001");
            assert_eq!(
                fs::read(&decoy_file).expect("outside junction file untouched"),
                b"DO_NOT_TRAVERSE"
            );
            fs::remove_dir(&quar_junc).expect("remove planted test spool junction");
        }
    }

    #[tokio::test]
    async fn forward_phase2_crash_before_fence_drift_reexports_gen_plus_1() {
        use crate::storage::{
            ConfigStore as _, GitStore as _, RedbCaptureStore, RedbConfigStore, RedbGitStore,
            RefKey, capture_store::CaptureStore as _,
        };

        // Isolated OS child mode: pre-opened legacy SQLite process opened BEFORE
        // Phase 1 / Phase 2 begins, warming its schema & page cache, staying open
        // across the injected Step 2.1 crash, and writing post-crash rows through
        // that EXACT SAME pre-opened connection (`RB-10c` AC4).
        if let Some(preopen_role) = std::env::var_os("LIBRA_RB10C_PREOPEN_LEGACY_MODE") {
            let db_path = PathBuf::from(
                std::env::var_os("LIBRA_RB10C_PREOPEN_DB")
                    .expect("LIBRA_RB10C_PREOPEN_DB must be set"),
            );
            let mut conn = SqliteConnection::connect_with(
                &SqliteConnectOptions::new()
                    .filename(&db_path)
                    .create_if_missing(false)
                    .shared_cache(false),
            )
            .await
            .expect("open pre-crash legacy SQLite connection");

            match preopen_role.to_str() {
                Some("git") => {
                    // Warm SQLite's schema cookie and page cache BEFORE migration starts
                    // (autocommit read releases SHARED lock immediately so Phase 1 can
                    // quiesce cleanly while this connection remains open in RAM!).
                    let prior_refs: i64 =
                        sea_orm::sqlx::query_scalar("SELECT COUNT(*) FROM reference;")
                            .persistent(true)
                            .fetch_one(&mut conn)
                            .await
                            .expect("warm git reference cache before migration");
                    let prior_cfg: i64 =
                        sea_orm::sqlx::query_scalar("SELECT COUNT(*) FROM config_kv;")
                            .persistent(true)
                            .fetch_one(&mut conn)
                            .await
                            .expect("warm git config_kv cache before migration");
                    assert!(prior_refs > 0 && prior_cfg > 0);
                    println!("RB10C_PREOPEN_READY pid={}", std::process::id());
                    let _ = std::io::stdout().flush();

                    // Hold connection open across Phase 1 + Step 2.1 crash until parent
                    // closes stdin (or sends a line), then write through THIS EXACT SAME
                    // pre-opened connection!
                    let mut cmd_buf = String::new();
                    let _ = std::io::stdin().read_to_string(&mut cmd_buf);
                    if cmd_buf.trim() == "WRITE_POST_CRASH" {
                        conn.execute("BEGIN IMMEDIATE;")
                            .await
                            .expect("pre-opened git BEGIN IMMEDIATE after crash");
                        for i in 0..620usize {
                            let ref_name = format!("post-crash-branch-{i:04}");
                            let commit_hex = format!("{i:040x}");
                            sea_orm::sqlx::query(
                                "INSERT INTO reference (name, kind, \"commit\", remote, worktree_id) VALUES (?1, 'Branch', ?2, NULL, NULL);",
                            )
                            .bind(&ref_name)
                            .bind(&commit_hex)
                            .execute(&mut conn)
                            .await
                            .expect("pre-opened git insert post-crash reference");
                        }
                        sea_orm::sqlx::query(
                            "INSERT INTO config_kv (key, value, encrypted) VALUES ('postcrash.marker', 'preserved-100-percent', 0);",
                        )
                        .execute(&mut conn)
                        .await
                        .expect("pre-opened git insert post-crash config_kv");
                        conn.execute("COMMIT;")
                            .await
                            .expect("pre-opened git COMMIT after crash");
                        println!("RB10C_PREOPEN_WRITTEN");
                        let _ = std::io::stdout().flush();
                    }
                    conn.close().await.expect("close pre-opened git conn");
                    return;
                }
                Some("capture") => {
                    let prior_sess: i64 =
                        sea_orm::sqlx::query_scalar("SELECT COUNT(*) FROM agent_session;")
                            .persistent(true)
                            .fetch_one(&mut conn)
                            .await
                            .expect("warm capture agent_session cache before migration");
                    assert!(prior_sess > 0);
                    println!("RB10C_PREOPEN_READY pid={}", std::process::id());
                    let _ = std::io::stdout().flush();

                    let mut cmd_buf = String::new();
                    let _ = std::io::stdin().read_to_string(&mut cmd_buf);
                    if cmd_buf.trim() == "WRITE_POST_CRASH" {
                        conn.execute("BEGIN IMMEDIATE;")
                            .await
                            .expect("pre-opened capture BEGIN IMMEDIATE after crash");
                        sea_orm::sqlx::query(
                            "INSERT INTO agent_session (session_id, agent_kind, provider_session_id, thread_id, state, working_dir, worktree_id, parent_commit, parent_session_id, metadata_json, redaction_report, started_at, last_event_at, stopped_at, schema_version, sync_revision, repo_id, workspace_id, workspace_fence, scope_state) VALUES ('sess-post-crash-001', 'codex', 'prov-post-crash', NULL, 'active', '/work/post-crash', 'wt-1', NULL, NULL, '{}', '{}', 1795402000, 1795402010, NULL, 1, 1, 'repo-1', 'ws-1', 1, 'scoped');",
                        )
                        .execute(&mut conn)
                        .await
                        .expect("pre-opened capture insert post-crash agent_session");
                        conn.execute("COMMIT;")
                            .await
                            .expect("pre-opened capture COMMIT after crash");
                        println!("RB10C_PREOPEN_WRITTEN");
                        let _ = std::io::stdout().flush();
                    }
                    conn.close().await.expect("close pre-opened capture conn");
                    return;
                }
                other => panic!("unexpected LIBRA_RB10C_PREOPEN_LEGACY_MODE: {other:?}"),
            }
        }

        // Isolated OS child mode measuring real kernel physical memory peak
        // (`<= 64 MiB`) and streaming batch cap (`<= 500` rows/batch) on a
        // ~20 MiB drifted Layout C `gen+1` re-export (`RB-10c` perf budget).
        if let Some(dir_os) = std::env::var_os("LIBRA_RB10C_MEM_CHILD_DIR") {
            let storage = PathBuf::from(dir_os);
            let (before_live, _before_peak) =
                measure_process_live_and_peak_heap().expect("measure baseline footprint");
            let report = resume_forward_migration(&storage)
                .await
                .expect("child drift re-export resume must succeed");
            let (_after_live, after_peak) =
                measure_process_live_and_peak_heap().expect("measure post-reexport peak footprint");
            let extra_peak = after_peak.saturating_sub(before_live);
            assert_eq!(report.initial_generation, 1);
            assert_eq!(report.final_generation, 2);
            assert!(report.reexported_due_to_drift);
            assert!(
                report.max_reexport_batch_rows > 0
                    && report.max_reexport_batch_rows <= FORWARD_MIGRATION_STREAM_BATCH_ROWS,
                "drift re-export batch rows {} exceeded cap {}",
                report.max_reexport_batch_rows,
                FORWARD_MIGRATION_STREAM_BATCH_ROWS
            );
            assert!(
                extra_peak <= FORWARD_MIGRATION_EXTRA_HEAP_BUDGET_BYTES,
                "drift re-export extra peak memory {} bytes exceeded 64 MiB budget ({} bytes)",
                extra_peak,
                FORWARD_MIGRATION_EXTRA_HEAP_BUDGET_BYTES
            );
            println!(
                "RB10C_MEM_CHILD_OK extra_peak={extra_peak} max_batch={}",
                report.max_reexport_batch_rows
            );
            return;
        }

        /// RAII guard for an isolated OS legacy process whose SQLite connection
        /// is opened & warmed BEFORE Phase 1/2 starts and stays alive across the
        /// injected crash before writing post-crash rows.
        struct PreOpenedLegacyWriterChild {
            child: Option<Child>,
            stdin: Option<ChildStdin>,
            stdout: Option<BufReader<ChildStdout>>,
        }
        impl PreOpenedLegacyWriterChild {
            fn spawn_before_migration(role: &str, db_path: &Path) -> Self {
                let exe = std::env::current_exe().expect("locate current test executable");
                let mut child = Command::new(&exe)
                    .arg("--exact")
                    .arg("storage::migrate::tests::forward_phase2_crash_before_fence_drift_reexports_gen_plus_1")
                    .arg("--nocapture")
                    .env("LIBRA_RB10C_PREOPEN_LEGACY_MODE", role)
                    .env("LIBRA_RB10C_PREOPEN_DB", db_path)
                    .env("LIBRA_TEST", "1")
                    .stdin(Stdio::piped())
                    .stdout(Stdio::piped())
                    .stderr(Stdio::piped())
                    .spawn()
                    .expect("spawn pre-opened legacy SQLite child");
                let stdin = child.stdin.take().expect("capture pre-open child stdin");
                let mut reader =
                    BufReader::new(child.stdout.take().expect("capture pre-open child stdout"));
                let mut saw_ready = false;
                let mut captured = String::new();
                loop {
                    let mut line = String::new();
                    let n = reader.read_line(&mut line).expect("read pre-open stdout");
                    if n == 0 {
                        break;
                    }
                    captured.push_str(&line);
                    if line.trim().starts_with("RB10C_PREOPEN_READY") {
                        saw_ready = true;
                        break;
                    }
                }
                if !saw_ready {
                    let mut err_buf = String::new();
                    if let Some(mut s) = child.stderr.take() {
                        let _ = s.read_to_string(&mut err_buf);
                    }
                    let status = child.wait().expect("wait failed pre-open child");
                    panic!(
                        "pre-opened legacy child `{role}` failed before READY ({status:?}):\nstdout:\n{captured}\nstderr:\n{err_buf}"
                    );
                }
                Self {
                    child: Some(child),
                    stdin: Some(stdin),
                    stdout: Some(reader),
                }
            }

            fn write_post_crash_and_wait(mut self) {
                let mut stdin = self.stdin.take().expect("pre-open child stdin");
                stdin
                    .write_all(b"WRITE_POST_CRASH\n")
                    .expect("signal pre-open child to write post-crash rows");
                drop(stdin);
                let mut trailing = String::new();
                if let Some(mut reader) = self.stdout.take() {
                    let _ = reader.read_to_string(&mut trailing);
                }
                let out = self
                    .child
                    .take()
                    .expect("pre-open child handle")
                    .wait_with_output()
                    .expect("wait pre-open child exit");
                assert!(
                    out.status.success() && trailing.contains("RB10C_PREOPEN_WRITTEN"),
                    "pre-opened legacy child failed post-crash write ({:?}):\nstdout:\n{trailing}\nstderr:\n{}",
                    out.status,
                    String::from_utf8_lossy(&out.stderr)
                );
            }
        }
        impl Drop for PreOpenedLegacyWriterChild {
            fn drop(&mut self) {
                drop(self.stdin.take());
                if let Some(mut c) = self.child.take() {
                    let _ = c.kill();
                    let _ = c.wait();
                }
            }
        }

        // --------------------------------------------------------------------
        // Scenario 1 (AC4 primary): Separate legacy OS processes open & warm
        // connections to BOTH `libra.db` and `capture.db` BEFORE Phase 1/2
        // begins, keep those EXACT connections open across the Step 2.1
        // `phase2_progress == "pending"` crash (`gen = 1`), and then write
        // 620 new `reference` rows + `config_kv` + `agent_session` through
        // those pre-opened connections -> resume detects `source_logical_sha256`
        // drift, re-exports to exact `gen + 1` (`2`), refreshes `VACUUM INTO`
        // backups, updates manifest to `gen = 2`, fences & finalizes with 100%
        // of post-crash writes preserved!
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10c AC4 Scenario 1 tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-ac4-s1").await;

            let git_db = git_sqlite_db_path(&storage);
            let cap_db = capture_sqlite_db_path(&storage);

            // Start BOTH legacy OS processes and warm their SQLite connections
            // BEFORE Phase 1 & Phase 2 even begin!
            let preopen_git = PreOpenedLegacyWriterChild::spawn_before_migration("git", &git_db);
            let preopen_cap =
                PreOpenedLegacyWriterChild::spawn_before_migration("capture", &cap_db);

            // Run Phase 1 + Step 2.1 and crash right after `phase2_progress == "pending"`
            // WHILE both pre-opened legacy connections remain alive in separate OS PIDs!
            crash_after_step2_1_pending(&storage, 1).await;

            // Both env overrides remain fail-closed (`LBR-IO-001`) before resume.
            assert_rb10c_unfinalized_rejects_both_env_overrides(&storage, "ac4_pending_drift");

            // Now signal BOTH pre-opened legacy connections to commit post-crash
            // writes through their existing warmed SQLite connections!
            const POST_CRASH_REF_COUNT: usize = 620;
            preopen_git.write_post_crash_and_wait();
            preopen_cap.write_post_crash_and_wait();

            // Resume! Must detect drift on BOTH sources and re-export to `gen = 2`.
            let resumed = resume_forward_migration(&storage)
                .await
                .expect("resume_forward_migration must re-export drifted pending sources to gen+1");

            assert_eq!(resumed.initial_generation, 1);
            assert_eq!(resumed.final_generation, 2);
            assert!(resumed.reexported_due_to_drift);
            assert_eq!(
                resumed.git_recovery_state,
                ForwardSourceRecoveryState::DriftedLivePending
            );
            assert_eq!(
                resumed.capture_recovery_state,
                ForwardSourceRecoveryState::DriftedLivePending
            );
            assert!(
                resumed.max_reexport_batch_rows > 0
                    && resumed.max_reexport_batch_rows <= FORWARD_MIGRATION_STREAM_BATCH_ROWS,
                "re-export batch rows {} must be in 1..={}",
                resumed.max_reexport_batch_rows,
                FORWARD_MIGRATION_STREAM_BATCH_ROWS
            );
            assert!(resumed.finalized.manifest.finalized);
            assert_eq!(resumed.finalized.manifest.generation, 2);
            assert_eq!(
                resumed.finalized.manifest.git_path.as_deref(),
                Some("redb/git.gen-00000002.redb")
            );
            assert_eq!(
                resumed.finalized.manifest.capture_path.as_deref(),
                Some("private/capture.gen-00000002.redb")
            );
            assert_eq!(
                resumed.finalized.manifest.backup_dir.as_deref(),
                Some("sqlite-backup/00000002")
            );
            assert!(resumed.finalized.manifest.phase2_progress.spool_fenced);

            // Legacy SQLite files are fenced & unlinked; spool tombstones installed.
            assert!(
                !git_db.exists(),
                "libra.db must be unlinked after gen+1 finalize"
            );
            assert!(
                !cap_db.exists(),
                "capture.db must be unlinked after gen+1 finalize"
            );
            for slot in CAPTURE_SPOOL_TOMBSTONE_NAMES {
                let p = capture_spool_dir_path(&storage).join(slot);
                assert_eq!(
                    fs::read(&p).expect("read spool tombstone"),
                    CAPTURE_SPOOL_TOMBSTONE_SENTINEL
                );
            }

            // 100% of post-crash writes preserved in `git.gen-00000002.redb`!
            let git_store = RedbGitStore::open_read_only(&resumed.finalized.git_redb_path)
                .expect("open git.gen-00000002.redb");
            for i in [0usize, 1, 250, 499, 500, 619] {
                let name = format!("post-crash-branch-{i:04}");
                let target = git_store
                    .get_ref(&RefKey::LocalBranch { name })
                    .await
                    .expect("read post-crash ref")
                    .expect("post-crash ref must be 100% preserved");
                assert_eq!(target, RefTarget::Direct(format!("{i:040x}")));
            }
            let all_refs = git_store.list_refs(None).await.expect("list all refs");
            let post_crash_ref_hits = all_refs
                .iter()
                .filter(|r| match &r.key {
                    RefKey::LocalBranch { name } => name.starts_with("post-crash-branch-"),
                    _ => false,
                })
                .count();
            assert_eq!(
                post_crash_ref_hits, POST_CRASH_REF_COUNT,
                "ALL 620 post-crash references must be preserved in gen+1 redb"
            );

            let cfg_store = RedbConfigStore::open_read_only(
                &resumed.finalized.git_redb_path,
                DatabaseRole::Repository,
            )
            .expect("open RedbConfigStore on gen+1");
            let marker = cfg_store
                .get("postcrash.marker")
                .await
                .expect("read post-crash config_kv")
                .expect("post-crash config_kv marker must exist");
            assert_eq!(marker.value, "preserved-100-percent");

            // 100% of post-crash capture writes + spool + queue preserved in `capture.gen-00000002.redb`!
            let cap_store = RedbCaptureStore::open_read_only(&resumed.finalized.capture_redb_path)
                .await
                .expect("open capture.gen-00000002.redb");
            let post_sess = cap_store
                .get_session("sess-post-crash-001")
                .await
                .expect("read post-crash session")
                .expect("post-crash capture session must be 100% preserved");
            assert_eq!(post_sess.provider_session_id, "prov-post-crash");
            assert_eq!(post_sess.working_dir, "/work/post-crash");

            // Refreshed `gen + 1` (`00000002`) backups pass SHA-256 + `PRAGMA integrity_check`
            // AND contain the post-crash writes!
            let bk_git = sqlite_backup_git_db_path(&storage, 2);
            let bk_cap = sqlite_backup_capture_db_path(&storage, 2);
            assert!(bk_git.exists() && bk_cap.exists());
            let disk_m = read_storage_manifest(&storage)
                .expect("read finalized manifest")
                .expect("manifest must exist");
            let bk_git_snap = verify_sqlite_backup_for_recovery(
                &storage,
                "sqlite-backup/00000002",
                DatabaseRole::Repository,
                disk_m
                    .source_digests
                    .git_backup_sha256
                    .as_deref()
                    .expect("git_backup_sha256"),
                #[cfg(unix)]
                &[],
            )
            .await
            .expect("gen+1 git backup must pass SHA-256 + integrity_check");
            let mut bk_conn = SqliteConnection::connect_with(
                &SqliteConnectOptions::new()
                    .filename(&bk_git_snap.snapshot_path)
                    .read_only(true),
            )
            .await
            .expect("open gen+1 git backup");
            let bk_post_cnt: i64 = sea_orm::sqlx::query_scalar(
                "SELECT COUNT(*) FROM reference WHERE name LIKE 'post-crash-branch-%';",
            )
            .fetch_one(&mut bk_conn)
            .await
            .expect("count post-crash refs in gen+1 backup");
            let bk_marker: String = sea_orm::sqlx::query_scalar(
                "SELECT value FROM config_kv WHERE key = 'postcrash.marker';",
            )
            .fetch_one(&mut bk_conn)
            .await
            .expect("read postcrash.marker in gen+1 git backup");
            bk_conn.close().await.expect("close bk_conn");
            drop(bk_git_snap);
            assert_eq!(bk_post_cnt as usize, POST_CRASH_REF_COUNT);
            assert_eq!(bk_marker, "preserved-100-percent");

            let bk_cap_snap = verify_sqlite_backup_for_recovery(
                &storage,
                "sqlite-backup/00000002",
                DatabaseRole::Capture,
                disk_m
                    .source_digests
                    .cap_backup_sha256
                    .as_deref()
                    .expect("cap_backup_sha256"),
                #[cfg(unix)]
                &[],
            )
            .await
            .expect("gen+1 capture backup must pass SHA-256 + integrity_check");
            let mut bk_cap_conn = SqliteConnection::connect_with(
                &SqliteConnectOptions::new()
                    .filename(&bk_cap_snap.snapshot_path)
                    .read_only(true),
            )
            .await
            .expect("open gen+1 capture backup");
            let bk_cap_row: (String, String) = sea_orm::sqlx::query_as(
                "SELECT provider_session_id, working_dir FROM agent_session WHERE session_id = 'sess-post-crash-001';",
            )
            .fetch_one(&mut bk_cap_conn)
            .await
            .expect("read post-crash agent_session in gen+1 capture backup");
            bk_cap_conn.close().await.expect("close bk_cap_conn");
            drop(bk_cap_snap);
            assert_eq!(bk_cap_row.0, "prov-post-crash");
            assert_eq!(bk_cap_row.1, "/work/post-crash");

            let _locks = acquire_forward_recovery_non_sqlite_locks(&storage)
                .expect("all 6 locks must be released after gen+1 finalize");
        }

        // --------------------------------------------------------------------
        // Scenario 2 (AC4 WAL legacy write + busy contention + Layout A inline):
        // Post-crash legacy writer switches Layout A `libra.db` to WAL mode and
        // commits new repository + inline capture rows into offline `-wal`.
        // Active external writer fails closed (`LBR-IO-001`, manifest stays
        // `gen = 1, finalized = false`); once released, resume quiesces WAL ->
        // DELETE, re-exports to `gen = 2`, and preserves 100% of WAL writes!
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10c AC4 Scenario 2 tempdir");
            let storage = dir.path().join(".libra");
            fs::create_dir_all(&storage).expect("create .libra");
            let git_db = git_sqlite_db_path(&storage);
            populate_all_61_repository_tables(&git_db).await;
            populate_capture_rows_via_sql(&git_db, 0, None).await;
            switch_fixture_db_to_delete_mode(&git_db).await;

            crash_after_step2_1_pending(&storage, 1).await;

            // Legacy writer enables WAL mode and leaves real offline `-wal` frames
            // (`NO_CKPT_ON_CLOSE = 1` simulates a legacy process leaving uncheckpointed WAL).
            {
                let mut wconn = SqliteConnection::connect_with(
                    &SqliteConnectOptions::new()
                        .filename(&git_db)
                        .create_if_missing(false),
                )
                .await
                .expect("open Layout A libra.db for post-crash WAL write");
                set_wal_checkpoint_on_close(&mut wconn, DatabaseRole::Repository, true)
                    .await
                    .expect("disable checkpoint on close");
                let mode: String = sea_orm::sqlx::query_scalar("PRAGMA journal_mode = WAL;")
                    .fetch_one(&mut wconn)
                    .await
                    .expect("enable WAL");
                assert!(mode.eq_ignore_ascii_case("wal"));
                sea_orm::sqlx::query(
                    "INSERT INTO reference (name, kind, \"commit\", remote, worktree_id) VALUES ('post-crash-wal', 'Branch', 'abababababababababababababababababababab', NULL, NULL);",
                )
                .execute(&mut wconn)
                .await
                .expect("insert WAL ref");
                sea_orm::sqlx::query(
                    "INSERT INTO agent_session (session_id, agent_kind, provider_session_id, thread_id, state, working_dir, worktree_id, parent_commit, parent_session_id, metadata_json, redaction_report, started_at, last_event_at, stopped_at, schema_version, sync_revision, repo_id, workspace_id, workspace_fence, scope_state) VALUES ('sess-wal-inline-001', 'codex', 'prov-wal', NULL, 'active', '/work/wal', 'wt-1', NULL, NULL, '{}', '{}', 1795403000, 1795403010, NULL, 1, 1, 'repo-1', 'ws-1', 1, 'scoped');",
                )
                .execute(&mut wconn)
                .await
                .expect("insert WAL inline session");
                wconn.close().await.expect("close WAL writer");
            }
            assert!(
                fs::symlink_metadata(sqlite_sidecar_path(&git_db, "-wal"))
                    .is_ok_and(|m| m.len() > 0),
                "offline -wal must be non-empty before resume"
            );

            // While an external OS writer holds `libra.db`, resume MUST fail
            // closed with `LBR-IO-001` leaving `gen = 1, finalized = false` untouched!
            let exe = std::env::current_exe().expect("locate current test executable");
            let mut blocker_child = Command::new(&exe)
                .arg("--exact")
                .arg("storage::migrate::tests::forward_phase2_powerloss_torn_sector_hot_journal_rollback_and_resume")
                .arg("--nocapture")
                .env("LIBRA_RB10C_CHILD_MODE", "hold_wal_write_lock")
                .env("LIBRA_RB10C_TARGET_PATH", &git_db)
                .env("LIBRA_TEST", "1")
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .expect("spawn RB-10c WAL blocker child");
            let blocker_stdin = blocker_child.stdin.take().expect("blocker stdin");
            let mut blocker_stdout =
                BufReader::new(blocker_child.stdout.take().expect("blocker stdout"));
            let mut ready_line = String::new();
            let mut saw_ready = false;
            loop {
                ready_line.clear();
                let n = blocker_stdout
                    .read_line(&mut ready_line)
                    .expect("read blocker stdout");
                if n == 0 {
                    break;
                }
                if ready_line.trim() == "RB10C_WRITER_READY" {
                    saw_ready = true;
                    break;
                }
            }
            assert!(
                saw_ready,
                "RB-10c WAL blocker child did not emit ready marker"
            );
            let busy_err = resume_forward_migration(&storage)
                .await
                .expect_err("resume must fail closed when external writer holds libra.db");
            assert_eq!(busy_err.stable_code_str(), "LBR-IO-001");
            let unchanged = read_storage_manifest(&storage)
                .expect("read manifest after busy reject")
                .expect("manifest must still exist");
            assert_eq!(unchanged.generation, 1);
            assert!(!unchanged.finalized);
            drop(blocker_stdin);
            let blocker_out = blocker_child
                .wait_with_output()
                .expect("wait for RB-10c blocker child");
            assert!(
                blocker_out.status.success(),
                "RB-10c blocker child exited abnormally: {:?}",
                blocker_out.status
            );

            // Once external writer exits, resume succeeds and preserves 100% of WAL rows!
            let resumed = resume_forward_migration(&storage)
                .await
                .expect("resume must quiesce offline WAL and re-export to gen+1");
            assert_eq!(resumed.initial_generation, 1);
            assert_eq!(resumed.final_generation, 2);
            assert!(resumed.reexported_due_to_drift);
            assert_eq!(
                resumed.git_recovery_state,
                ForwardSourceRecoveryState::DriftedLivePending
            );
            assert_eq!(
                resumed.capture_recovery_state,
                ForwardSourceRecoveryState::Absent
            );
            assert!(!git_db.exists());
            assert!(!sqlite_sidecar_path(&git_db, "-wal").exists());
            assert!(!sqlite_sidecar_path(&git_db, "-shm").exists());

            let git_store = RedbGitStore::open_read_only(&resumed.finalized.git_redb_path)
                .expect("open Layout A gen+1 git redb");
            let wal_ref = git_store
                .get_ref(&RefKey::LocalBranch {
                    name: "post-crash-wal".to_string(),
                })
                .await
                .expect("read WAL ref")
                .expect("WAL post-crash ref must be preserved");
            assert_eq!(
                wal_ref,
                RefTarget::Direct("abababababababababababababababababababab".to_string())
            );
            let cap_store = RedbCaptureStore::open_read_only(&resumed.finalized.capture_redb_path)
                .await
                .expect("open Layout A gen+1 capture redb");
            let wal_sess = cap_store
                .get_session("sess-wal-inline-001")
                .await
                .expect("read WAL inline session")
                .expect("WAL inline capture session must be preserved");
            assert_eq!(wal_sess.provider_session_id, "prov-wal");
            assert_eq!(wal_sess.working_dir, "/work/wal");
        }

        // --------------------------------------------------------------------
        // Scenario 3 (Performance Budget): Isolated OS child process verifies
        // streaming batch cap (`<= 500` rows/batch) AND kernel-tracked extra
        // peak physical memory (`<= 64 MiB`) on a ~20 MiB drifted re-export!
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10c AC4 Scenario 3 mem-budget tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-ac4-mem").await;
            crash_after_step2_1_pending(&storage, 1).await;

            // Append ~20 MiB of wide post-crash rows (160 x 128 KiB config_kv values)
            // + 550 reference rows to exercise both row-cap and byte-cap batching.
            let git_db = git_sqlite_db_path(&storage);
            {
                let mut gconn = SqliteConnection::connect_with(
                    &SqliteConnectOptions::new()
                        .filename(&git_db)
                        .create_if_missing(false),
                )
                .await
                .expect("open libra.db for ~20 MiB drift payload");
                let wide_val = "W".repeat(128 * 1024);
                gconn.execute("BEGIN IMMEDIATE;").await.expect("begin wide");
                for i in 0..160usize {
                    let key = format!("driftwide.wide_{i:04}");
                    sea_orm::sqlx::query(
                        "INSERT INTO config_kv (key, value, encrypted) VALUES (?1, ?2, 0);",
                    )
                    .bind(&key)
                    .bind(&wide_val)
                    .execute(&mut gconn)
                    .await
                    .expect("insert 128 KiB wide drift row");
                }
                for i in 0..550usize {
                    let name = format!("drift-mem-{i:04}");
                    let hex = format!("{i:040x}");
                    sea_orm::sqlx::query(
                        "INSERT INTO reference (name, kind, \"commit\", remote, worktree_id) VALUES (?1, 'Branch', ?2, NULL, NULL);",
                    )
                    .bind(&name)
                    .bind(&hex)
                    .execute(&mut gconn)
                    .await
                    .expect("insert drift ref");
                }
                gconn.execute("COMMIT;").await.expect("commit wide");
                gconn.close().await.expect("close wide");
            }

            let exe = std::env::current_exe().expect("locate current test executable");
            let mem_out = Command::new(&exe)
                .arg("--exact")
                .arg("storage::migrate::tests::forward_phase2_crash_before_fence_drift_reexports_gen_plus_1")
                .arg("--nocapture")
                .env("LIBRA_RB10C_MEM_CHILD_DIR", &storage)
                .env("LIBRA_TEST", "1")
                .output()
                .expect("spawn isolated RB-10c memory-budget child");
            let stdout = String::from_utf8_lossy(&mem_out.stdout);
            let stderr = String::from_utf8_lossy(&mem_out.stderr);
            assert!(
                mem_out.status.success() && stdout.contains("RB10C_MEM_CHILD_OK"),
                "isolated memory-budget child failed ({:?}):\nstdout:\n{stdout}\nstderr:\n{stderr}",
                mem_out.status
            );

            // Spot-check wide post-crash rows preserved in `git.gen-00000002.redb`.
            let cfg_store = RedbConfigStore::open_read_only(
                git_redb_path(&storage, 2),
                DatabaseRole::Repository,
            )
            .expect("open gen-2 redb after mem-budget child");
            let last_wide = cfg_store
                .get("driftwide.wide_0159")
                .await
                .expect("read last wide row")
                .expect("wide_0159 must be preserved");
            assert_eq!(last_wide.value.len(), 128 * 1024);
        }

        // --------------------------------------------------------------------
        // Scenario 4 (Repeated interrupted `gen + 1` drift re-export crashes
        // at BOTH artifact-creation and post-promotion pre-manifest boundaries):
        // Under held migration locks, unreferenced `gen + 1` staging/promoted
        // artifacts are safely reconciled & removed so recovery NEVER skips to
        // `gen + 2` and NEVER exhausts any retry window, always finalizing at
        // exact `gen + 1` (`2`)! Symlinked unreferenced artifacts fail closed.
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10c AC4 Scenario 4 interrupted-reexport tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10c-ac4-s4").await;

            let git_db = git_sqlite_db_path(&storage);
            let preopen_git = PreOpenedLegacyWriterChild::spawn_before_migration("git", &git_db);
            crash_after_step2_1_pending(&storage, 1).await;
            preopen_git.write_post_crash_and_wait();

            // Interrupt #1: SIGKILL right after creating `gen + 1` (`2`) `.tmp` files!
            let err1 = resume_forward_migration_inner(
                DatabaseRole::Repository,
                &storage,
                None,
                None,
                Some(ForwardDriftReexportCrashPoint::AfterArtifactCreation),
            )
            .await
            .expect_err("injected AfterArtifactCreation crash must abort");
            assert!(
                err1.to_string().contains("AfterArtifactCreation")
                    || err1.to_string().contains("artifact creation")
            );
            assert!(
                git_redb_tmp_path(&storage, 2).exists()
                    && capture_redb_tmp_path(&storage, 2).exists(),
                "simulated SIGKILL must leave unreferenced gen=2 .tmp files on disk"
            );
            let m_after_1 = read_storage_manifest(&storage)
                .expect("read manifest after crash 1")
                .expect("manifest must still exist");
            assert_eq!(m_after_1.generation, 1);
            assert!(!m_after_1.finalized);

            // Interrupt #2: Resume cleans up stale `gen=2` `.tmp`, runs full
            // export + promote + `sqlite-backup/00000002/`, then SIGKILLs right
            // BEFORE updating `storage-format.json`!
            let err2 = resume_forward_migration_inner(
                DatabaseRole::Repository,
                &storage,
                None,
                None,
                Some(ForwardDriftReexportCrashPoint::AfterPromotionBeforeManifest),
            )
            .await
            .expect_err("injected AfterPromotionBeforeManifest crash must abort");
            assert!(err2.to_string().contains("promotion before manifest"));
            assert!(
                git_redb_path(&storage, 2).exists()
                    && capture_redb_path(&storage, 2).exists()
                    && sqlite_backup_dir_path(&storage, 2).exists(),
                "simulated SIGKILL must leave unreferenced promoted gen=2 artifacts + backup dir on disk"
            );
            let m_after_2 = read_storage_manifest(&storage)
                .expect("read manifest after crash 2")
                .expect("manifest must still exist");
            assert_eq!(m_after_2.generation, 1);
            assert!(!m_after_2.finalized);

            // Interrupt #3 (repeat): Another post-promotion crash proves repeated
            // interruptions NEVER skip `gen = 2` or exhaust a retry counter!
            let _err3 = resume_forward_migration_inner(
                DatabaseRole::Repository,
                &storage,
                None,
                None,
                Some(ForwardDriftReexportCrashPoint::AfterPromotionBeforeManifest),
            )
            .await
            .expect_err("repeated AfterPromotionBeforeManifest crash must abort cleanly");

            // Negative security check: if a symlink (Unix) or NTFS directory
            // junction (Windows) is planted inside unreferenced `gen = 2`
            // artifacts/backup, reconciliation MUST fail closed (`LBR-IO-001`)
            // without touching any target outside `.libra/`!
            #[cfg(unix)]
            {
                let decoy_target = dir.path().join("decoy-outside.txt");
                fs::write(&decoy_target, b"DO_NOT_DELETE").expect("write decoy");
                let tmp2 = git_redb_tmp_path(&storage, 2);
                let _ = fs::remove_file(&tmp2);
                std::os::unix::fs::symlink(&decoy_target, &tmp2)
                    .expect("plant symlink at gen=2 .tmp");
                let sym_err = resume_forward_migration(&storage)
                    .await
                    .expect_err("symlink at unreferenced gen=2 path must fail closed");
                assert_eq!(sym_err.stable_code_str(), "LBR-IO-001");
                assert_eq!(
                    fs::read(&decoy_target).expect("decoy must stay untouched"),
                    b"DO_NOT_DELETE"
                );
                fs::remove_file(&tmp2).expect("remove planted test symlink");
            }
            #[cfg(windows)]
            {
                let outside_dir = dir.path().join("decoy-outside-dir");
                fs::create_dir_all(&outside_dir).expect("create outside decoy dir");
                let decoy_file = outside_dir.join("decoy.txt");
                fs::write(&decoy_file, b"DO_NOT_DELETE").expect("write outside decoy");
                let junction_path = sqlite_backup_dir_path(&storage, 2).join("escape-junction");
                let mklink_status = Command::new("cmd")
                    .args(["/C", "mklink", "/J"])
                    .arg(&junction_path)
                    .arg(&outside_dir)
                    .status()
                    .expect("spawn cmd mklink /J for junction regression test");
                assert!(
                    mklink_status.success(),
                    "cmd /C mklink /J failed: {mklink_status:?}"
                );
                let junc_err = resume_forward_migration(&storage)
                    .await
                    .expect_err("NTFS junction inside unreferenced gen=2 backup must fail closed");
                assert_eq!(junc_err.stable_code_str(), "LBR-IO-001");
                assert_eq!(
                    fs::read(&decoy_file).expect("outside junction target must stay untouched"),
                    b"DO_NOT_DELETE"
                );
                fs::remove_dir(&junction_path).expect("remove planted test junction");
            }

            // Final resume: cleanly removes all unreferenced `gen = 2` artifacts
            // and finalizes at EXACT `final_generation == 2` (`gen + 1`), NEVER `gen + 2`!
            let resumed = resume_forward_migration(&storage)
                .await
                .expect("resume after repeated interrupted gen+1 crashes must succeed at gen+1");
            assert_eq!(resumed.initial_generation, 1);
            assert_eq!(
                resumed.final_generation, 2,
                "interrupted gen+1 re-exports MUST converge to exact gen+1 (2), never gen+2"
            );
            assert!(resumed.reexported_due_to_drift);
            assert!(resumed.finalized.manifest.finalized);
            assert_eq!(resumed.finalized.manifest.generation, 2);
            assert!(!git_redb_path(&storage, 3).exists());
            assert!(!sqlite_backup_dir_path(&storage, 3).exists());

            let git_store = RedbGitStore::open_read_only(&resumed.finalized.git_redb_path)
                .expect("open gen=2 git redb");
            let preserved = git_store
                .get_ref(&RefKey::LocalBranch {
                    name: "post-crash-branch-0619".to_string(),
                })
                .await
                .expect("read post-crash branch 619")
                .expect("post-crash branch from pre-opened legacy conn must be preserved");
            assert_eq!(preserved, RefTarget::Direct(format!("{:040x}", 619usize)));
            let cfg_store = RedbConfigStore::open_read_only(
                &resumed.finalized.git_redb_path,
                DatabaseRole::Repository,
            )
            .expect("open gen=2 config store");
            assert_eq!(
                cfg_store
                    .get("postcrash.marker")
                    .await
                    .expect("read postcrash.marker")
                    .expect("postcrash.marker must exist")
                    .value,
                "preserved-100-percent"
            );
        }
    }

    // ========================================================================
    // RB-10k: Forward Migration Phase 2 Post-Fence Pre-Unlink & Dual-Source
    // Post-Unlink Legally-Absent Recovery (`AC1`, `AC2`, `AC3`, `AC4`, `<= 500ms`)
    // ========================================================================

    /// Run Phase 1 + Phase 2 up to `target_point` and inject a deterministic
    /// crash error there, leaving `storage-format.json(finalized = false)` and
    /// all Phase 1 / Phase 2 artifacts on disk with locks cleanly released.
    async fn crash_forward_phase2_at_point(
        storage: &Path,
        generation: u64,
        target_point: Phase2TestPoint,
    ) {
        let prepared = prepare_forward_phase1(storage, generation)
            .await
            .expect("prepare_forward_phase1 must succeed");
        let mut crash_hook = |point: Phase2TestPoint, _root: &Path| -> StorageResult<()> {
            if point == target_point {
                return Err(StorageBackendError::BackendInternal {
                    detail: format!("injected RB-10k crash at {target_point:?}"),
                });
            }
            Ok(())
        };
        let err = execute_forward_phase2_fence_and_unlink_inner(prepared, Some(&mut crash_hook))
            .await
            .expect_err("injected RB-10k crash point must abort Phase 2");
        assert!(
            err.to_string()
                .contains(&format!("injected RB-10k crash at {target_point:?}")),
            "unexpected Phase 2 error before reaching {target_point:?}: {err}"
        );
    }

    /// Assert that `durability` contains `UnlinkSource` for `role` (`expected_file`)
    /// IMMEDIATELY followed by `ParentDirFsyncAfterUnlink` (`expected_parent`),
    /// and that `PublishManifestUnlinked` for `role` occurs strictly afterward (`RB-10k` AC2).
    fn assert_unlink_followed_immediately_by_dir_fsync(
        durability: &Phase2DurabilityReceipt,
        role: DatabaseRole,
        expected_file: &str,
        expected_parent: &str,
        label: &str,
    ) {
        let unlink_positions: Vec<usize> = durability
            .ops
            .iter()
            .enumerate()
            .filter_map(|(idx, op)| {
                (op.kind == Phase2DurabilityOpKind::UnlinkSource
                    && op.role == Some(role)
                    && op.rel_target == expected_file)
                    .then_some(idx)
            })
            .collect();
        assert_eq!(
            unlink_positions.len(),
            1,
            "[{label}] expected exactly one UnlinkSource({role}, {expected_file}), got {:?}",
            durability.ops
        );
        let unlink_idx = unlink_positions[0];
        let next_op = durability.ops.get(unlink_idx + 1).unwrap_or_else(|| {
            panic!(
                "[{label}] missing immediate ParentDirFsyncAfterUnlink after UnlinkSource({role}): {:?}",
                durability.ops
            )
        });
        assert_eq!(
            next_op.kind,
            Phase2DurabilityOpKind::ParentDirFsyncAfterUnlink,
            "[{label}] expected ParentDirFsyncAfterUnlink immediately after UnlinkSource({role}), got {next_op:?}"
        );
        assert_eq!(next_op.role, Some(role), "[{label}] wrong fsync_dir role");
        assert_eq!(
            next_op.rel_target, expected_parent,
            "[{label}] wrong fsync_dir target parent"
        );

        #[cfg(unix)]
        {
            let close_idx = durability
                .ops
                .iter()
                .position(|op| {
                    op.kind == Phase2DurabilityOpKind::CloseMigrationConn && op.role == Some(role)
                })
                .expect("expected CloseMigrationConn for unlinked role on Unix");
            assert!(
                close_idx > unlink_idx + 1,
                "[{label}] Unix unlink + fsync_dir must finish BEFORE CloseMigrationConn (unlink={unlink_idx}, close={close_idx})"
            );
        }

        let publish_unlinked_idx = durability
            .ops
            .iter()
            .position(|op| {
                op.kind == Phase2DurabilityOpKind::PublishManifestUnlinked && op.role == Some(role)
            })
            .expect("expected PublishManifestUnlinked for unlinked role");
        assert!(
            publish_unlinked_idx > unlink_idx + 1,
            "[{label}] PublishManifestUnlinked must occur after UnlinkSource + ParentDirFsyncAfterUnlink"
        );
    }

    /// Write a cold zeroed 512-byte `-journal` sidecar simulating power loss
    /// under SQLite `locking_mode = EXCLUSIVE` after `COMMIT` (and optionally
    /// after `unlink(db) + fsync_dir`) before `c_mig.close()` could unlink it.
    fn plant_cold_zeroed_journal(db_path: &Path) -> PathBuf {
        let j_path = sqlite_sidecar_path(db_path, "-journal");
        let mut opts = OpenOptions::new();
        opts.create(true).write(true).truncate(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt as _;
            opts.mode(0o600);
        }
        let mut f = opts.open(&j_path).expect("create cold zeroed -journal");
        f.write_all(&[0u8; 512])
            .expect("write 512 zero bytes to cold -journal");
        f.sync_all().expect("fsync cold -journal");
        j_path
    }

    /// Overwrite an existing backup file in place while preserving its Unix `0o600` mode.
    fn overwrite_backup_bytes_preserving_mode(path: &Path, bytes: &[u8]) {
        let mut f = OpenOptions::new()
            .write(true)
            .truncate(true)
            .open(path)
            .expect("open backup file for overwrite");
        f.write_all(bytes).expect("write backup bytes");
        f.sync_all().expect("fsync overwritten backup");
    }

    /// Corrupt a non-header B-tree page (page 2, offset 4096) of a valid SQLite
    /// database so `SqliteConnection::connect_with` still opens cleanly while
    /// `PRAGMA integrity_check` deterministically fails (`RB-10k` AC3/AC4).
    fn corrupt_sqlite_btree_page2(original: &[u8]) -> Vec<u8> {
        assert!(
            original.len() >= 8192,
            "fixture SQLite backup must have at least 2 pages (len={})",
            original.len()
        );
        let mut out = original.to_vec();
        for b in &mut out[4096..4128] {
            *b = 0xFE;
        }
        out
    }

    fn sha256_hex_bytes(bytes: &[u8]) -> String {
        let mut hasher = Sha256::new();
        hasher.update(bytes);
        format!("{:x}", hasher.finalize())
    }

    /// Assert that a finalized Layout C `RB-10k` recovery report has 100% intact
    /// git, capture, spool, and queue records, installed `capture-spool`
    /// tombstones, absent legacy `.db` files, and all 6 locks released.
    async fn assert_rb10k_layout_c_converged(
        storage: &Path,
        resumed: &ForwardPhase2ResumeReport,
        tag: &str,
        label: &str,
    ) {
        use crate::storage::{
            GitStore as _, RedbCaptureStore, RedbGitStore, capture_store::CaptureStore as _,
        };

        assert_eq!(
            resumed.initial_generation, 1,
            "[{label}] initial_generation"
        );
        assert_eq!(resumed.final_generation, 1, "[{label}] final_generation");
        assert!(
            !resumed.reexported_due_to_drift,
            "[{label}] clean post-fence/post-unlink recovery must not drift-reexport"
        );
        assert!(
            resumed.finalized.manifest.finalized,
            "[{label}] manifest must be finalized"
        );
        assert_eq!(
            resumed.finalized.manifest.backend,
            StorageBackendKind::Redb,
            "[{label}] manifest backend must be redb"
        );
        assert_eq!(
            resumed.finalized.manifest.phase2_progress.git_db,
            Some(Phase2DbState::Unlinked),
            "[{label}] git_db must be unlinked"
        );
        assert_eq!(
            resumed.finalized.manifest.phase2_progress.capture_db,
            Some(Phase2DbState::Unlinked),
            "[{label}] capture_db must be unlinked"
        );
        assert!(
            resumed.finalized.manifest.phase2_progress.spool_fenced,
            "[{label}] spool_fenced must be true"
        );

        let disk_manifest = read_storage_manifest(storage)
            .expect("read finalized manifest")
            .expect("manifest must exist on disk");
        assert!(disk_manifest.finalized, "[{label}] disk manifest finalized");
        assert_eq!(disk_manifest.generation, 1, "[{label}] disk manifest gen");
        assert_eq!(
            disk_manifest.phase2_progress.git_db,
            Some(Phase2DbState::Unlinked)
        );
        assert_eq!(
            disk_manifest.phase2_progress.capture_db,
            Some(Phase2DbState::Unlinked)
        );
        assert!(disk_manifest.phase2_progress.spool_fenced);

        let git_db = git_sqlite_db_path(storage);
        let cap_db = capture_sqlite_db_path(storage);
        assert!(!git_db.exists(), "[{label}] libra.db must be unlinked");
        assert!(!cap_db.exists(), "[{label}] capture.db must be unlinked");
        for suffix in ["-wal", "-shm", "-journal"] {
            assert!(
                !sqlite_sidecar_path(&git_db, suffix).exists(),
                "[{label}] libra.db{suffix} must be absent"
            );
            assert!(
                !sqlite_sidecar_path(&cap_db, suffix).exists(),
                "[{label}] capture.db{suffix} must be absent"
            );
        }

        for slot in CAPTURE_SPOOL_TOMBSTONE_NAMES {
            let p = capture_spool_dir_path(storage).join(slot);
            let meta = fs::symlink_metadata(&p).expect("stat spool tombstone");
            assert!(
                meta.file_type().is_file(),
                "[{label}] tombstone must be file"
            );
            assert_eq!(
                fs::read(&p).expect("read spool tombstone"),
                CAPTURE_SPOOL_TOMBSTONE_SENTINEL,
                "[{label}] tombstone sentinel bytes"
            );
        }

        let git_store = RedbGitStore::open_read_only(&resumed.finalized.git_redb_path)
            .expect("open finalized git.gen-00000001.redb");
        let refs = git_store.list_refs(None).await.expect("list git refs");
        assert!(!refs.is_empty(), "[{label}] git refs must be intact");

        let cap_store = RedbCaptureStore::open_read_only(&resumed.finalized.capture_redb_path)
            .await
            .expect("open finalized capture.gen-00000001.redb");
        let sessions = cap_store
            .list_sessions_by_started_desc()
            .await
            .expect("list capture sessions");
        assert!(
            sessions
                .iter()
                .any(|s| s.provider_session_id == format!("prov-{tag}")),
            "[{label}] migrated capture-spool session prov-{tag} must be intact"
        );
        let cap_db_ro =
            open_redb_read_only(&resumed.finalized.capture_redb_path, DatabaseRole::Capture)
                .expect("open capture redb read-only to check queue record");
        let cap_rtx =
            begin_checked_read(&cap_db_ro, DatabaseRole::Capture).expect("begin capture read txn");
        let usage_tbl = cap_rtx
            .open_table(redb_cap::AGENT_USAGE_STATS_TABLE)
            .expect("open agent_usage_stats table");
        let queue_usage_id = format!("usage-{tag}-1");
        assert!(
            usage_tbl
                .get(queue_usage_id.as_str())
                .expect("lookup queue usage_stats")
                .is_some(),
            "[{label}] migrated capture-queue record {queue_usage_id} must be intact"
        );

        let _locks = acquire_forward_recovery_non_sqlite_locks(storage)
            .expect("all 6 non-SQLite locks must be released after finalized resume");
    }

    #[tokio::test]
    async fn forward_phase2_crash_after_fence_before_unlink() {
        use crate::storage::{
            GitStore as _, RedbCaptureStore, RedbGitStore, capture_store::CaptureStore as _,
        };

        const RESUME_BUDGET_MS: u128 = 500;

        // --------------------------------------------------------------------
        // Scenario 1A (AC1 + AC2): Crash immediately after `libra.db` fence
        // `COMMIT`, BEFORE persisting `fenced_ready_to_unlink` and BEFORE
        // `unlink(libra.db)` (`phase2_progress.git_db == "pending"`), including
        // a genuine cold zeroed `libra.db-journal` left behind by power loss
        // under `locking_mode = EXCLUSIVE`.
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10k 1A tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10k-1a").await;
            crash_forward_phase2_at_point(
                &storage,
                1,
                Phase2TestPoint::AfterFenceCommitBeforePersistReady(DatabaseRole::Repository),
            )
            .await;

            let git_db = git_sqlite_db_path(&storage);
            let cap_db = capture_sqlite_db_path(&storage);
            assert!(
                git_db.exists(),
                "fenced libra.db must still exist pre-unlink"
            );
            assert!(cap_db.exists(), "capture.db must still exist pre-unlink");
            let m_before = read_storage_manifest(&storage)
                .expect("read pre-resume manifest")
                .expect("manifest must exist");
            assert!(!m_before.finalized);
            assert_eq!(
                m_before.phase2_progress.git_db,
                Some(Phase2DbState::Pending)
            );
            assert_eq!(
                m_before.phase2_progress.capture_db,
                Some(Phase2DbState::Pending)
            );

            // Independently confirm `libra.db` rejects normal opens with
            // `SQLITE_CORRUPT (11)` on `__libra_migrated_fence__`, and that
            // `PRAGMA writable_schema = ON` reveals the exact fence sentinel.
            {
                let mut probe = SqliteConnection::connect_with(
                    &SqliteConnectOptions::new()
                        .filename(&git_db)
                        .read_only(true),
                )
                .await
                .expect("connect read-only to fenced libra.db");
                let err = sea_orm::sqlx::query_scalar::<_, String>(
                    "SELECT name FROM sqlite_master LIMIT 1;",
                )
                .fetch_optional(&mut probe)
                .await
                .expect_err("normal query on fenced libra.db must fail with SQLITE_CORRUPT");
                assert_eq!(sqlite_error_exact_numeric_code(&err), Some(11));
                assert!(err.to_string().contains(SQLITE_MIGRATED_FENCE_TABLE));
                probe
                    .execute("PRAGMA writable_schema = ON;")
                    .await
                    .expect("enable writable_schema for test check");
                let sentinel: (String, String, String, i64, String) = sea_orm::sqlx::query_as(
                    "SELECT type, name, tbl_name, rootpage, sql FROM sqlite_master WHERE name = ?1;",
                )
                .bind(SQLITE_MIGRATED_FENCE_TABLE)
                .fetch_one(&mut probe)
                .await
                .expect("read exact fence sentinel row");
                assert_eq!(sentinel.0, "table");
                assert_eq!(sentinel.1, SQLITE_MIGRATED_FENCE_TABLE);
                assert_eq!(sentinel.2, SQLITE_MIGRATED_FENCE_TABLE);
                assert!(sentinel.3 > 0);
                assert_eq!(sentinel.4, SQLITE_MIGRATED_FENCE_SQL);
                probe.close().await.expect("close fenced probe");
            }

            // Plant cold zeroed `libra.db-journal` left behind by `SIGKILL`
            // after fence `COMMIT` under `locking_mode = EXCLUSIVE`.
            let cold_journal = plant_cold_zeroed_journal(&git_db);
            assert!(cold_journal.exists());
            assert_rb10c_unfinalized_rejects_both_env_overrides(
                &storage,
                "rb10k_1a_fenced_pending",
            );

            let started = Instant::now();
            let resumed = resume_forward_migration(&storage)
                .await
                .expect("resume after libra.db fence COMMIT (pending) must succeed");
            let elapsed_ms = started.elapsed().as_millis();
            assert!(
                elapsed_ms <= RESUME_BUDGET_MS,
                "RB-10k 1A resume took {elapsed_ms}ms (budget <= {RESUME_BUDGET_MS}ms)"
            );
            assert_eq!(
                resumed.git_recovery_state,
                ForwardSourceRecoveryState::FencedPreUnlink
            );
            assert_eq!(
                resumed.capture_recovery_state,
                ForwardSourceRecoveryState::CleanMatchedPending
            );
            assert_unlink_followed_immediately_by_dir_fsync(
                &resumed.finalized.durability,
                DatabaseRole::Repository,
                LEGACY_SQLITE_DB_FILE,
                ".libra",
                "rb10k-1a-git",
            );
            assert_unlink_followed_immediately_by_dir_fsync(
                &resumed.finalized.durability,
                DatabaseRole::Capture,
                LEGACY_CAPTURE_SQLITE_REL_PATH,
                PRIVATE_SUBDIR,
                "rb10k-1a-capture",
            );
            assert_rb10k_layout_c_converged(&storage, &resumed, "rb10k-1a", "rb10k-1a").await;
        }

        // --------------------------------------------------------------------
        // Scenario 1B (AC1 + AC2): Crash after persisting `git_db =
        // "fenced_ready_to_unlink"`, right BEFORE `unlink(libra.db)`.
        // Includes negative checks proving BOTH `backup_sha256` AND exact
        // `sqlite_master` fence SQL are verified BEFORE `unlink`!
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10k 1B tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10k-1b").await;
            crash_forward_phase2_at_point(
                &storage,
                1,
                Phase2TestPoint::AfterPersistReadyBeforeUnlink(DatabaseRole::Repository),
            )
            .await;

            let git_db = git_sqlite_db_path(&storage);
            let m_before = read_storage_manifest(&storage)
                .expect("read manifest 1B")
                .expect("manifest must exist");
            assert!(!m_before.finalized);
            assert_eq!(
                m_before.phase2_progress.git_db,
                Some(Phase2DbState::FencedReadyToUnlink)
            );
            assert!(git_db.exists());

            // Negative check 1: Corrupt `sqlite-backup/00000001/libra.db` ->
            // resume MUST fail closed (`LBR-IO-001`) WITHOUT unlinking `libra.db`!
            let git_bk = sqlite_backup_git_db_path(&storage, 1);
            let valid_git_bk = fs::read(&git_bk).expect("read valid git backup");
            let mut tampered_bk = valid_git_bk.clone();
            tampered_bk[64] ^= 0xFF;
            overwrite_backup_bytes_preserving_mode(&git_bk, &tampered_bk);
            let bk_err = resume_forward_migration(&storage)
                .await
                .expect_err("corrupt git backup must block post-fence unlink");
            assert_eq!(bk_err.stable_code_str(), "LBR-IO-001");
            assert!(
                bk_err.to_string().contains("backup_sha256 mismatch"),
                "expected backup_sha256 mismatch error, got: {bk_err}"
            );
            assert!(
                git_db.exists(),
                "fenced libra.db MUST NOT be unlinked when backup_sha256 fails"
            );
            assert!(
                !read_storage_manifest(&storage)
                    .expect("read manifest")
                    .expect("manifest")
                    .finalized
            );
            overwrite_backup_bytes_preserving_mode(&git_bk, &valid_git_bk);

            // Negative check 2: Mutate `__libra_migrated_fence__` SQL to a
            // non-exact syntax error -> resume MUST reject via `PRAGMA writable_schema`
            // WITHOUT unlinking `libra.db`!
            {
                let mut conn = SqliteConnection::connect_with(
                    &SqliteConnectOptions::new()
                        .filename(&git_db)
                        .create_if_missing(false),
                )
                .await
                .expect("open fenced libra.db to tamper sentinel SQL");
                conn.execute("PRAGMA writable_schema = ON;")
                    .await
                    .expect("writable_schema ON");
                sea_orm::sqlx::query(
                    "UPDATE sqlite_master SET sql = 'NON_EXACT_FENCE_SYNTAX_ERROR' WHERE name = ?1;",
                )
                .bind(SQLITE_MIGRATED_FENCE_TABLE)
                .execute(&mut conn)
                .await
                .expect("tamper sentinel SQL");
                conn.execute("PRAGMA writable_schema = OFF;")
                    .await
                    .expect("writable_schema OFF");
                conn.close().await.expect("close tampered conn");
            }
            let sentinel_err = resume_forward_migration(&storage)
                .await
                .expect_err("non-exact fence sentinel SQL must be rejected fail-closed");
            assert_eq!(sentinel_err.stable_code_str(), "LBR-IO-001");
            assert!(
                sentinel_err
                    .to_string()
                    .contains("non-exact fence sentinel"),
                "expected non-exact fence sentinel error, got: {sentinel_err}"
            );
            assert!(
                git_db.exists(),
                "libra.db MUST NOT be unlinked on non-exact fence sentinel"
            );

            // Restore exact canonical fence sentinel SQL and verify clean convergence.
            {
                let mut conn = SqliteConnection::connect_with(
                    &SqliteConnectOptions::new()
                        .filename(&git_db)
                        .create_if_missing(false),
                )
                .await
                .expect("open libra.db to restore canonical fence sentinel");
                conn.execute("PRAGMA writable_schema = ON;")
                    .await
                    .expect("writable_schema ON");
                sea_orm::sqlx::query("UPDATE sqlite_master SET sql = ?1 WHERE name = ?2;")
                    .bind(SQLITE_MIGRATED_FENCE_SQL)
                    .bind(SQLITE_MIGRATED_FENCE_TABLE)
                    .execute(&mut conn)
                    .await
                    .expect("restore canonical sentinel SQL");
                conn.execute("PRAGMA writable_schema = OFF;")
                    .await
                    .expect("writable_schema OFF");
                conn.close().await.expect("close restored conn");
            }

            let started = Instant::now();
            let resumed = resume_forward_migration(&storage)
                .await
                .expect("resume after libra.db fenced_ready_to_unlink must succeed");
            let elapsed_ms = started.elapsed().as_millis();
            assert!(
                elapsed_ms <= RESUME_BUDGET_MS,
                "RB-10k 1B resume took {elapsed_ms}ms (budget <= {RESUME_BUDGET_MS}ms)"
            );
            assert_eq!(
                resumed.git_recovery_state,
                ForwardSourceRecoveryState::FencedPreUnlink
            );
            assert_eq!(
                resumed.capture_recovery_state,
                ForwardSourceRecoveryState::CleanMatchedPending
            );
            assert_unlink_followed_immediately_by_dir_fsync(
                &resumed.finalized.durability,
                DatabaseRole::Repository,
                LEGACY_SQLITE_DB_FILE,
                ".libra",
                "rb10k-1b-git",
            );
            assert_rb10k_layout_c_converged(&storage, &resumed, "rb10k-1b", "rb10k-1b").await;
        }

        // --------------------------------------------------------------------
        // Scenario 1C (AC1 + AC2): Crash after `capture.db` fence `COMMIT`,
        // BEFORE `unlink(capture.db)`, at BOTH `pending` and
        // `fenced_ready_to_unlink` manifest progress checkpoints!
        // --------------------------------------------------------------------
        for (idx, crash_point, expected_cap_state) in [
            (
                "1c-pending",
                Phase2TestPoint::AfterFenceCommitBeforePersistReady(DatabaseRole::Capture),
                Phase2DbState::Pending,
            ),
            (
                "1c-ready",
                Phase2TestPoint::AfterPersistReadyBeforeUnlink(DatabaseRole::Capture),
                Phase2DbState::FencedReadyToUnlink,
            ),
        ] {
            let dir = tempdir().expect("create RB-10k 1C tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, idx).await;
            crash_forward_phase2_at_point(&storage, 1, crash_point).await;

            let git_db = git_sqlite_db_path(&storage);
            let cap_db = capture_sqlite_db_path(&storage);
            assert!(!git_db.exists(), "[{idx}] libra.db already unlinked");
            assert!(
                cap_db.exists(),
                "[{idx}] fenced capture.db must remain pre-unlink"
            );
            let m_before = read_storage_manifest(&storage)
                .expect("read manifest 1C")
                .expect("manifest must exist");
            assert!(!m_before.finalized);
            assert_eq!(
                m_before.phase2_progress.git_db,
                Some(Phase2DbState::Unlinked)
            );
            assert_eq!(
                m_before.phase2_progress.capture_db,
                Some(expected_cap_state)
            );

            let _cold_cap_journal = plant_cold_zeroed_journal(&cap_db);

            // Corrupt `capture.db` backup -> MUST block `unlink(capture.db)`!
            let cap_bk = sqlite_backup_capture_db_path(&storage, 1);
            let valid_cap_bk = fs::read(&cap_bk).expect("read valid capture backup");
            let mut bad_cap_bk = valid_cap_bk.clone();
            bad_cap_bk[64] ^= 0xFF;
            overwrite_backup_bytes_preserving_mode(&cap_bk, &bad_cap_bk);
            let cap_bk_err = resume_forward_migration(&storage)
                .await
                .expect_err("corrupt capture backup must block post-fence capture.db unlink");
            assert_eq!(cap_bk_err.stable_code_str(), "LBR-IO-001");
            assert!(
                cap_db.exists(),
                "[{idx}] fenced capture.db MUST NOT be unlinked when backup fails"
            );
            overwrite_backup_bytes_preserving_mode(&cap_bk, &valid_cap_bk);

            let started = Instant::now();
            let resumed = resume_forward_migration(&storage)
                .await
                .expect("resume after capture.db fence before unlink must succeed");
            let elapsed_ms = started.elapsed().as_millis();
            assert!(
                elapsed_ms <= RESUME_BUDGET_MS,
                "RB-10k {idx} resume took {elapsed_ms}ms (budget <= {RESUME_BUDGET_MS}ms)"
            );
            assert_eq!(
                resumed.git_recovery_state,
                ForwardSourceRecoveryState::LegallyAbsentPostUnlink
            );
            assert_eq!(
                resumed.capture_recovery_state,
                ForwardSourceRecoveryState::FencedPreUnlink
            );
            assert_unlink_followed_immediately_by_dir_fsync(
                &resumed.finalized.durability,
                DatabaseRole::Capture,
                LEGACY_CAPTURE_SQLITE_REL_PATH,
                PRIVATE_SUBDIR,
                idx,
            );
            assert_rb10k_layout_c_converged(&storage, &resumed, idx, idx).await;
        }

        // --------------------------------------------------------------------
        // Scenario 1D (Layout A — `capture_db == absent`): Crash after
        // `libra.db` fence `COMMIT`, before `unlink(libra.db)`.
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10k 1D Layout A tempdir");
            let storage = dir.path().join(".libra");
            fs::create_dir_all(&storage).expect("create .libra");
            let git_db = git_sqlite_db_path(&storage);
            populate_all_61_repository_tables(&git_db).await;
            populate_capture_rows_via_sql(&git_db, 0, None).await;
            switch_fixture_db_to_delete_mode(&git_db).await;

            crash_forward_phase2_at_point(
                &storage,
                1,
                Phase2TestPoint::AfterFenceCommitBeforePersistReady(DatabaseRole::Repository),
            )
            .await;

            let started = Instant::now();
            let resumed = resume_forward_migration(&storage)
                .await
                .expect("Layout A resume after libra.db fence must succeed");
            let elapsed_ms = started.elapsed().as_millis();
            assert!(
                elapsed_ms <= RESUME_BUDGET_MS,
                "RB-10k 1D Layout A resume took {elapsed_ms}ms (budget <= {RESUME_BUDGET_MS}ms)"
            );
            assert_eq!(
                resumed.git_recovery_state,
                ForwardSourceRecoveryState::FencedPreUnlink
            );
            assert_eq!(
                resumed.capture_recovery_state,
                ForwardSourceRecoveryState::Absent
            );
            assert!(resumed.finalized.manifest.finalized);
            assert!(!git_db.exists());
            assert_unlink_followed_immediately_by_dir_fsync(
                &resumed.finalized.durability,
                DatabaseRole::Repository,
                LEGACY_SQLITE_DB_FILE,
                ".libra",
                "rb10k-1d-layout-a",
            );
            let git_store = RedbGitStore::open_read_only(&resumed.finalized.git_redb_path)
                .expect("open Layout A git redb");
            assert!(
                !git_store
                    .list_refs(None)
                    .await
                    .expect("list refs")
                    .is_empty()
            );
            let cap_store = RedbCaptureStore::open_read_only(&resumed.finalized.capture_redb_path)
                .await
                .expect("open Layout A capture redb");
            assert!(
                !cap_store
                    .list_sessions_by_started_desc()
                    .await
                    .expect("list Layout A inline sessions")
                    .is_empty()
            );
        }
    }

    #[tokio::test]
    async fn forward_phase2_crash_immediately_after_libra_db_unlink() {
        use crate::storage::{
            GitStore as _, RedbCaptureStore, RedbGitStore, capture_store::CaptureStore as _,
        };

        const RESUME_BUDGET_MS: u128 = 500;

        // --------------------------------------------------------------------
        // Scenario 2A (AC3 — `phase2_progress.git_db == "fenced_ready_to_unlink"`):
        // Crash IMMEDIATELY after `unlink(libra.db) + fsync_dir`, BEFORE
        // updating `git_db = "unlinked"` and BEFORE fencing `capture.db`.
        // Verifies cold zeroed `libra.db-journal` cleanup, active/symlink/hardlink
        // sidecar rejection, AND independent `backup_sha256` + `PRAGMA integrity_check`
        // enforcement before converging to `finalized = true` (`<= 500ms`).
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10k 2A tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10k-2a").await;
            crash_forward_phase2_at_point(
                &storage,
                1,
                Phase2TestPoint::AfterParentDirFsyncBeforeClose(DatabaseRole::Repository),
            )
            .await;

            let git_db = git_sqlite_db_path(&storage);
            let cap_db = capture_sqlite_db_path(&storage);
            assert!(!git_db.exists(), "libra.db must already be unlinked");
            assert!(cap_db.exists(), "capture.db must still exist unfenced");
            let m_before = read_storage_manifest(&storage)
                .expect("read manifest 2A")
                .expect("manifest must exist");
            assert!(!m_before.finalized);
            assert_eq!(
                m_before.phase2_progress.git_db,
                Some(Phase2DbState::FencedReadyToUnlink)
            );
            assert_eq!(
                m_before.phase2_progress.capture_db,
                Some(Phase2DbState::Pending)
            );

            assert_rb10c_unfinalized_rejects_both_env_overrides(
                &storage,
                "rb10k_2a_post_git_unlink",
            );

            // Negative check 1: Active (non-zero) `libra.db-journal` alongside
            // missing `libra.db` MUST fail closed (`LBR-IO-001`)!
            let git_journal = sqlite_sidecar_path(&git_db, "-journal");
            fs::write(&git_journal, SQLITE_HOT_ROLLBACK_JOURNAL_MAGIC)
                .expect("write non-zero libra.db-journal");
            let hot_j_err = resume_forward_migration(&storage).await.expect_err(
                "non-zero libra.db-journal alongside unlinked libra.db must fail closed",
            );
            assert_eq!(hot_j_err.stable_code_str(), "LBR-IO-001");
            assert!(
                cap_db.exists(),
                "capture.db must stay untouched on rejection"
            );
            fs::remove_file(&git_journal).expect("remove active journal");

            // Negative check 2: Stray `libra.db-wal` alongside missing `libra.db`
            // MUST fail closed (`LBR-IO-001`)!
            let git_wal = sqlite_sidecar_path(&git_db, "-wal");
            fs::write(&git_wal, b"stray-wal").expect("write stray libra.db-wal");
            let wal_err = resume_forward_migration(&storage)
                .await
                .expect_err("stray libra.db-wal alongside unlinked libra.db must fail closed");
            assert_eq!(wal_err.stable_code_str(), "LBR-IO-001");
            fs::remove_file(&git_wal).expect("remove stray wal");

            // Negative check 3 (Unix): Symlinked or hard-linked `libra.db-journal`
            // MUST fail closed (`LBR-IO-001`) WITHOUT touching outside target!
            #[cfg(unix)]
            {
                let decoy = dir.path().join("decoy-journal-target.bin");
                fs::write(&decoy, [0u8; 512]).expect("write decoy file");
                std::os::unix::fs::symlink(&decoy, &git_journal).expect("symlink libra.db-journal");
                let sym_err = resume_forward_migration(&storage)
                    .await
                    .expect_err("symlinked libra.db-journal must fail closed");
                assert_eq!(sym_err.stable_code_str(), "LBR-IO-001");
                assert!(decoy.exists(), "decoy target must stay untouched");
                fs::remove_file(&git_journal).expect("remove test symlink");

                fs::hard_link(&decoy, &git_journal).expect("hardlink libra.db-journal");
                let hl_err = resume_forward_migration(&storage)
                    .await
                    .expect_err("hard-linked libra.db-journal (nlink>1) must fail closed");
                assert_eq!(hl_err.stable_code_str(), "LBR-IO-001");
                assert!(decoy.exists(), "hard-linked decoy must stay untouched");
                fs::remove_file(&git_journal).expect("remove test hardlink");
            }

            // Plant genuine cold zeroed 512-byte `libra.db-journal` (power loss
            // between `unlink(libra.db) + fsync_dir` and `c_mig.close()`).
            let _cold_git_journal = plant_cold_zeroed_journal(&git_db);

            // Negative check 4: Corrupt `sqlite-backup/00000001/libra.db` ->
            // `backup_sha256` mismatch MUST fail closed (`LBR-IO-001`)!
            let git_bk = sqlite_backup_git_db_path(&storage, 1);
            let valid_git_bk = fs::read(&git_bk).expect("read valid git backup");
            let corrupt_git_bk = corrupt_sqlite_btree_page2(&valid_git_bk);
            overwrite_backup_bytes_preserving_mode(&git_bk, &corrupt_git_bk);
            let sha_err = resume_forward_migration(&storage)
                .await
                .expect_err("backup_sha256 mismatch on unlinked libra.db backup must fail closed");
            assert_eq!(sha_err.stable_code_str(), "LBR-IO-001");
            assert!(
                sha_err.to_string().contains("backup_sha256 mismatch"),
                "expected backup_sha256 mismatch, got: {sha_err}"
            );

            // Negative check 5: Even if `git_backup_sha256` in manifest matches
            // the corrupted backup bytes, `PRAGMA integrity_check` MUST catch
            // the B-tree corruption and fail closed (`LBR-IO-001`)!
            let manifest_path = crate::storage::manifest::storage_manifest_path(&storage);
            let valid_manifest_bytes = fs::read(&manifest_path).expect("read valid manifest bytes");
            let mut m_tampered = m_before.clone();
            m_tampered.source_digests.git_backup_sha256 = Some(sha256_hex_bytes(&corrupt_git_bk));
            fs::write(
                &manifest_path,
                serde_json::to_vec_pretty(&m_tampered).expect("serialize tampered manifest"),
            )
            .expect("write manifest with matching corrupt backup sha");
            let ic_err = resume_forward_migration(&storage).await.expect_err(
                "corrupt git backup must fail PRAGMA integrity_check even if sha matches",
            );
            assert_eq!(ic_err.stable_code_str(), "LBR-IO-001");
            assert!(
                ic_err.to_string().contains("integrity_check"),
                "expected PRAGMA integrity_check failure, got: {ic_err}"
            );
            assert!(
                cap_db.exists(),
                "capture.db must remain untouched on backup failure"
            );

            // Restore valid backup + manifest and verify clean idempotent convergence!
            overwrite_backup_bytes_preserving_mode(&git_bk, &valid_git_bk);
            fs::write(&manifest_path, &valid_manifest_bytes).expect("restore valid manifest");

            let started = Instant::now();
            let resumed = resume_forward_migration(&storage).await.expect(
                "resume after unlink(libra.db)+fsync_dir (fenced_ready_to_unlink) must succeed",
            );
            let elapsed_ms = started.elapsed().as_millis();
            assert!(
                elapsed_ms <= RESUME_BUDGET_MS,
                "RB-10k 2A resume took {elapsed_ms}ms (budget <= {RESUME_BUDGET_MS}ms)"
            );
            assert_eq!(
                resumed.git_recovery_state,
                ForwardSourceRecoveryState::LegallyAbsentPostUnlink
            );
            assert_eq!(
                resumed.capture_recovery_state,
                ForwardSourceRecoveryState::CleanMatchedPending
            );
            assert_unlink_followed_immediately_by_dir_fsync(
                &resumed.finalized.durability,
                DatabaseRole::Capture,
                LEGACY_CAPTURE_SQLITE_REL_PATH,
                PRIVATE_SUBDIR,
                "rb10k-2a-capture",
            );
            assert_rb10k_layout_c_converged(&storage, &resumed, "rb10k-2a", "rb10k-2a").await;
        }

        // --------------------------------------------------------------------
        // Scenario 2B (AC3 — `phase2_progress.git_db == "unlinked"`):
        // Crash immediately AFTER persisting `git_db = "unlinked"`, BEFORE
        // fencing `capture.db`.
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10k 2B tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10k-2b").await;
            crash_forward_phase2_at_point(
                &storage,
                1,
                Phase2TestPoint::AfterPersistUnlinked(DatabaseRole::Repository),
            )
            .await;

            let m_before = read_storage_manifest(&storage)
                .expect("read manifest 2B")
                .expect("manifest must exist");
            assert!(!m_before.finalized);
            assert_eq!(
                m_before.phase2_progress.git_db,
                Some(Phase2DbState::Unlinked)
            );
            assert_eq!(
                m_before.phase2_progress.capture_db,
                Some(Phase2DbState::Pending)
            );
            assert!(!git_sqlite_db_path(&storage).exists());
            assert!(capture_sqlite_db_path(&storage).exists());

            // Verify missing `libra.db` backup fails closed before restoring it.
            let git_bk = sqlite_backup_git_db_path(&storage, 1);
            let git_bk_backup_tmp = dir.path().join("saved-git-bk.db");
            fs::rename(&git_bk, &git_bk_backup_tmp).expect("temporarily move git backup away");
            let missing_err = resume_forward_migration(&storage)
                .await
                .expect_err("missing libra.db backup must fail closed");
            assert_eq!(missing_err.stable_code_str(), "LBR-IO-001");
            fs::rename(&git_bk_backup_tmp, &git_bk).expect("restore git backup");

            let started = Instant::now();
            let resumed = resume_forward_migration(&storage)
                .await
                .expect("resume after git_db=unlinked must succeed");
            let elapsed_ms = started.elapsed().as_millis();
            assert!(
                elapsed_ms <= RESUME_BUDGET_MS,
                "RB-10k 2B resume took {elapsed_ms}ms (budget <= {RESUME_BUDGET_MS}ms)"
            );
            assert_eq!(
                resumed.git_recovery_state,
                ForwardSourceRecoveryState::LegallyAbsentPostUnlink
            );
            assert_eq!(
                resumed.capture_recovery_state,
                ForwardSourceRecoveryState::CleanMatchedPending
            );
            assert_rb10k_layout_c_converged(&storage, &resumed, "rb10k-2b", "rb10k-2b").await;
        }

        // --------------------------------------------------------------------
        // Scenario 2C (AC3 Layout A — `capture_db == "absent"`):
        // Both `git_db == "fenced_ready_to_unlink"` AND `git_db == "unlinked"`.
        // --------------------------------------------------------------------
        for (tag, point, expected_git_state) in [
            (
                "2c-ready",
                Phase2TestPoint::AfterParentDirFsyncBeforeClose(DatabaseRole::Repository),
                Phase2DbState::FencedReadyToUnlink,
            ),
            (
                "2c-unlinked",
                Phase2TestPoint::AfterPersistUnlinked(DatabaseRole::Repository),
                Phase2DbState::Unlinked,
            ),
        ] {
            let dir = tempdir().expect("create RB-10k 2C Layout A tempdir");
            let storage = dir.path().join(".libra");
            fs::create_dir_all(&storage).expect("create .libra");
            let git_db = git_sqlite_db_path(&storage);
            populate_all_61_repository_tables(&git_db).await;
            populate_capture_rows_via_sql(&git_db, 0, None).await;
            switch_fixture_db_to_delete_mode(&git_db).await;

            crash_forward_phase2_at_point(&storage, 1, point).await;
            assert!(!git_db.exists(), "[{tag}] libra.db must be unlinked");
            let m_before = read_storage_manifest(&storage)
                .expect("read manifest 2C")
                .expect("manifest must exist");
            assert!(!m_before.finalized);
            assert_eq!(m_before.phase2_progress.git_db, Some(expected_git_state));
            assert_eq!(
                m_before.phase2_progress.capture_db,
                Some(Phase2DbState::Absent)
            );

            let started = Instant::now();
            let resumed = resume_forward_migration(&storage)
                .await
                .expect("Layout A resume after libra.db unlink must succeed");
            let elapsed_ms = started.elapsed().as_millis();
            assert!(
                elapsed_ms <= RESUME_BUDGET_MS,
                "RB-10k {tag} resume took {elapsed_ms}ms (budget <= {RESUME_BUDGET_MS}ms)"
            );
            assert_eq!(
                resumed.git_recovery_state,
                ForwardSourceRecoveryState::LegallyAbsentPostUnlink
            );
            assert_eq!(
                resumed.capture_recovery_state,
                ForwardSourceRecoveryState::Absent
            );
            assert!(resumed.finalized.manifest.finalized);
            assert_eq!(
                resumed.finalized.manifest.phase2_progress.git_db,
                Some(Phase2DbState::Unlinked)
            );
            let git_store = RedbGitStore::open_read_only(&resumed.finalized.git_redb_path)
                .expect("open Layout A git redb");
            assert!(
                !git_store
                    .list_refs(None)
                    .await
                    .expect("list refs")
                    .is_empty()
            );
            let cap_store = RedbCaptureStore::open_read_only(&resumed.finalized.capture_redb_path)
                .await
                .expect("open Layout A capture redb");
            assert!(
                !cap_store
                    .list_sessions_by_started_desc()
                    .await
                    .expect("list Layout A inline sessions")
                    .is_empty()
            );
        }
    }

    #[tokio::test]
    async fn forward_phase2_crash_immediately_after_capture_db_unlink() {
        const RESUME_BUDGET_MS: u128 = 500;

        // --------------------------------------------------------------------
        // Scenario 3A (AC4 — `phase2_progress.capture_db == "fenced_ready_to_unlink"`):
        // Crash IMMEDIATELY after `unlink(capture.db) + fsync_dir`, BEFORE
        // updating `capture_db = "unlinked"` and BEFORE Step 2.3 spool tombstones.
        // Verifies cold zeroed `capture.db-journal` cleanup, active/symlink/hardlink
        // sidecar rejection, AND independent `cap_backup_sha256` +
        // `PRAGMA integrity_check` enforcement before converging to `finalized = true`
        // (`<= 500ms`).
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10k 3A tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10k-3a").await;
            crash_forward_phase2_at_point(
                &storage,
                1,
                Phase2TestPoint::AfterParentDirFsyncBeforeClose(DatabaseRole::Capture),
            )
            .await;

            let git_db = git_sqlite_db_path(&storage);
            let cap_db = capture_sqlite_db_path(&storage);
            assert!(!git_db.exists(), "libra.db must already be unlinked");
            assert!(!cap_db.exists(), "capture.db must already be unlinked");
            let m_before = read_storage_manifest(&storage)
                .expect("read manifest 3A")
                .expect("manifest must exist");
            assert!(!m_before.finalized);
            assert_eq!(
                m_before.phase2_progress.git_db,
                Some(Phase2DbState::Unlinked)
            );
            assert_eq!(
                m_before.phase2_progress.capture_db,
                Some(Phase2DbState::FencedReadyToUnlink)
            );
            assert!(!m_before.phase2_progress.spool_fenced);

            assert_rb10c_unfinalized_rejects_both_env_overrides(
                &storage,
                "rb10k_3a_post_capture_unlink",
            );

            // Negative check 1: Active non-zero `capture.db-journal` MUST fail closed!
            let cap_journal = sqlite_sidecar_path(&cap_db, "-journal");
            fs::write(&cap_journal, SQLITE_HOT_ROLLBACK_JOURNAL_MAGIC)
                .expect("write active capture.db-journal");
            let hot_err = resume_forward_migration(&storage).await.expect_err(
                "active capture.db-journal alongside missing capture.db must fail closed",
            );
            assert_eq!(hot_err.stable_code_str(), "LBR-IO-001");
            fs::remove_file(&cap_journal).expect("remove active capture journal");

            // Negative check 2: Stray `capture.db-wal` MUST fail closed!
            let cap_wal = sqlite_sidecar_path(&cap_db, "-wal");
            fs::write(&cap_wal, b"stray-cap-wal").expect("write stray capture.db-wal");
            let wal_err = resume_forward_migration(&storage)
                .await
                .expect_err("stray capture.db-wal alongside missing capture.db must fail closed");
            assert_eq!(wal_err.stable_code_str(), "LBR-IO-001");
            fs::remove_file(&cap_wal).expect("remove stray capture wal");

            // Negative check 3 (Unix): Symlinked or hard-linked `capture.db-journal`
            // MUST fail closed WITHOUT touching decoy!
            #[cfg(unix)]
            {
                let decoy = dir.path().join("decoy-cap-journal.bin");
                fs::write(&decoy, [0u8; 512]).expect("write decoy file");
                std::os::unix::fs::symlink(&decoy, &cap_journal)
                    .expect("symlink capture.db-journal");
                let sym_err = resume_forward_migration(&storage)
                    .await
                    .expect_err("symlinked capture.db-journal must fail closed");
                assert_eq!(sym_err.stable_code_str(), "LBR-IO-001");
                assert!(decoy.exists(), "decoy target must stay untouched");
                fs::remove_file(&cap_journal).expect("remove capture symlink");

                fs::hard_link(&decoy, &cap_journal).expect("hardlink capture.db-journal");
                let hl_err = resume_forward_migration(&storage)
                    .await
                    .expect_err("hard-linked capture.db-journal must fail closed");
                assert_eq!(hl_err.stable_code_str(), "LBR-IO-001");
                assert!(decoy.exists(), "hard-linked decoy must stay untouched");
                fs::remove_file(&cap_journal).expect("remove capture hardlink");
            }

            // Plant genuine cold zeroed 512-byte `capture.db-journal` (power loss
            // between `unlink(capture.db) + fsync_dir` and `c_mig.close()`).
            let _cold_cap_journal = plant_cold_zeroed_journal(&cap_db);

            // Negative check 4: Corrupt `sqlite-backup/00000001/capture.db` ->
            // `backup_sha256` mismatch MUST fail closed (`LBR-IO-001`)!
            let cap_bk = sqlite_backup_capture_db_path(&storage, 1);
            let valid_cap_bk = fs::read(&cap_bk).expect("read valid capture backup");
            let corrupt_cap_bk = corrupt_sqlite_btree_page2(&valid_cap_bk);
            overwrite_backup_bytes_preserving_mode(&cap_bk, &corrupt_cap_bk);
            let sha_err = resume_forward_migration(&storage)
                .await
                .expect_err("corrupt capture backup must fail backup_sha256 check");
            assert_eq!(sha_err.stable_code_str(), "LBR-IO-001");
            assert!(
                sha_err.to_string().contains("backup_sha256 mismatch"),
                "expected backup_sha256 mismatch, got: {sha_err}"
            );

            // Negative check 5: Even when `cap_backup_sha256` matches the
            // corrupted bytes, `PRAGMA integrity_check` MUST fail closed (`LBR-IO-001`)!
            let manifest_path = crate::storage::manifest::storage_manifest_path(&storage);
            let valid_manifest_bytes = fs::read(&manifest_path).expect("read valid manifest");
            let mut m_tampered = m_before.clone();
            m_tampered.source_digests.cap_backup_sha256 = Some(sha256_hex_bytes(&corrupt_cap_bk));
            fs::write(
                &manifest_path,
                serde_json::to_vec_pretty(&m_tampered).expect("serialize tampered manifest"),
            )
            .expect("write manifest with matching corrupt cap backup sha");
            let ic_err = resume_forward_migration(&storage).await.expect_err(
                "corrupt capture backup must fail PRAGMA integrity_check even if sha matches",
            );
            assert_eq!(ic_err.stable_code_str(), "LBR-IO-001");
            assert!(
                ic_err.to_string().contains("integrity_check"),
                "expected PRAGMA integrity_check failure, got: {ic_err}"
            );
            assert!(
                !read_storage_manifest(&storage)
                    .expect("read manifest")
                    .expect("manifest")
                    .finalized
            );

            // Restore valid backup + manifest and verify idempotent convergence!
            overwrite_backup_bytes_preserving_mode(&cap_bk, &valid_cap_bk);
            fs::write(&manifest_path, &valid_manifest_bytes).expect("restore valid manifest");

            let started = Instant::now();
            let resumed = resume_forward_migration(&storage).await.expect(
                "resume after unlink(capture.db)+fsync_dir (fenced_ready_to_unlink) must succeed",
            );
            let elapsed_ms = started.elapsed().as_millis();
            assert!(
                elapsed_ms <= RESUME_BUDGET_MS,
                "RB-10k 3A resume took {elapsed_ms}ms (budget <= {RESUME_BUDGET_MS}ms)"
            );
            assert_eq!(
                resumed.git_recovery_state,
                ForwardSourceRecoveryState::LegallyAbsentPostUnlink
            );
            assert_eq!(
                resumed.capture_recovery_state,
                ForwardSourceRecoveryState::LegallyAbsentPostUnlink
            );
            assert_rb10k_layout_c_converged(&storage, &resumed, "rb10k-3a", "rb10k-3a").await;
        }

        // --------------------------------------------------------------------
        // Scenario 3B (AC4 — `phase2_progress.capture_db == "unlinked"`):
        // Crash immediately AFTER persisting `capture_db = "unlinked"`, right
        // BEFORE Step 2.3 spool tombstones & Step 2.4 `finalized = true`.
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("create RB-10k 3B tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10k-3b").await;
            crash_forward_phase2_at_point(
                &storage,
                1,
                Phase2TestPoint::AfterPersistUnlinked(DatabaseRole::Capture),
            )
            .await;

            let m_before = read_storage_manifest(&storage)
                .expect("read manifest 3B")
                .expect("manifest must exist");
            assert!(!m_before.finalized);
            assert_eq!(
                m_before.phase2_progress.git_db,
                Some(Phase2DbState::Unlinked)
            );
            assert_eq!(
                m_before.phase2_progress.capture_db,
                Some(Phase2DbState::Unlinked)
            );
            assert!(!m_before.phase2_progress.spool_fenced);

            // Missing `capture.db` backup MUST fail closed (`LBR-IO-001`)!
            let cap_bk = sqlite_backup_capture_db_path(&storage, 1);
            let cap_bk_tmp = dir.path().join("saved-cap-bk.db");
            fs::rename(&cap_bk, &cap_bk_tmp).expect("temporarily move capture backup away");
            let missing_err = resume_forward_migration(&storage)
                .await
                .expect_err("missing capture.db backup must fail closed");
            assert_eq!(missing_err.stable_code_str(), "LBR-IO-001");
            fs::rename(&cap_bk_tmp, &cap_bk).expect("restore capture backup");

            let started = Instant::now();
            let resumed = resume_forward_migration(&storage)
                .await
                .expect("resume after capture_db=unlinked must succeed");
            let elapsed_ms = started.elapsed().as_millis();
            assert!(
                elapsed_ms <= RESUME_BUDGET_MS,
                "RB-10k 3B resume took {elapsed_ms}ms (budget <= {RESUME_BUDGET_MS}ms)"
            );
            assert_eq!(
                resumed.git_recovery_state,
                ForwardSourceRecoveryState::LegallyAbsentPostUnlink
            );
            assert_eq!(
                resumed.capture_recovery_state,
                ForwardSourceRecoveryState::LegallyAbsentPostUnlink
            );
            assert_rb10k_layout_c_converged(&storage, &resumed, "rb10k-3b", "rb10k-3b").await;
        }
    }

    /// `RB-10d` AC1–AC4: unexpected missing `pending` sources (`libra.db` and
    /// `capture.db`), damaged page-1 headers without a hot rollback journal or
    /// fence sentinel, and non-sentinel schema corruption (both unrelated table
    /// syntax corruption and tampered `__libra_migrated_fence__` SQL text) on
    /// BOTH `libra.db` and `capture.db` all fail closed with `LBR-IO-001` within
    /// the `<= 100ms` budget without discarding or mutating source bytes.
    #[tokio::test]
    async fn forward_phase2_unexpected_missing_pending_and_corrupt_non_sentinel_reject() {
        const FAIL_CLOSED_BUDGET_MS: u128 = 100;

        // AC1: `phase2_progress.git_db == "pending"` with unexpectedly missing `libra.db`.
        {
            let dir = tempdir().expect("rb10d ac1 tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10d-ac1").await;
            crash_after_step2_1_pending(&storage, 1).await;
            let cap_before = fs::read(capture_sqlite_db_path(&storage)).expect("read capture.db");
            fs::remove_file(git_sqlite_db_path(&storage)).expect("remove pending libra.db");

            let started = Instant::now();
            let err = resume_forward_migration(&storage)
                .await
                .expect_err("AC1 missing pending libra.db must fail closed");
            assert_eq!(err.stable_code_str(), "LBR-IO-001", "AC1");
            assert!(
                started.elapsed().as_millis() <= FAIL_CLOSED_BUDGET_MS,
                "AC1 fail-closed took {}ms (budget <= {FAIL_CLOSED_BUDGET_MS}ms)",
                started.elapsed().as_millis()
            );
            assert!(
                !read_storage_manifest(&storage)
                    .expect("read manifest")
                    .expect("manifest present")
                    .finalized
            );
            assert_eq!(
                fs::read(capture_sqlite_db_path(&storage)).expect("re-read capture.db"),
                cap_before,
                "AC1 must leave capture.db untouched"
            );
        }

        // AC2: `phase2_progress.capture_db == "pending"` with unexpectedly missing `capture.db`.
        {
            let dir = tempdir().expect("rb10d ac2 tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10d-ac2").await;
            crash_after_step2_1_pending(&storage, 1).await;
            let git_before = fs::read(git_sqlite_db_path(&storage)).expect("read libra.db");
            fs::remove_file(capture_sqlite_db_path(&storage)).expect("remove pending capture.db");

            let started = Instant::now();
            let err = resume_forward_migration(&storage)
                .await
                .expect_err("AC2 missing pending capture.db must fail closed");
            assert_eq!(err.stable_code_str(), "LBR-IO-001", "AC2");
            assert!(
                started.elapsed().as_millis() <= FAIL_CLOSED_BUDGET_MS,
                "AC2 fail-closed took {}ms (budget <= {FAIL_CLOSED_BUDGET_MS}ms)",
                started.elapsed().as_millis()
            );
            assert!(
                !read_storage_manifest(&storage)
                    .expect("read manifest")
                    .expect("manifest present")
                    .finalized
            );
            assert_eq!(
                fs::read(git_sqlite_db_path(&storage)).expect("re-read libra.db"),
                git_before,
                "AC2 must leave libra.db untouched"
            );
        }

        // AC3: damaged page-1 header (zeroed first 512 bytes, no hot journal, no
        // sentinel) on BOTH `libra.db` and `capture.db` fails closed and never
        // discards source bytes.
        for (label, corrupt_capture) in [("git-header", false), ("cap-header", true)] {
            let dir = tempdir().expect("rb10d ac3 tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, label).await;
            crash_after_step2_1_pending(&storage, 1).await;
            let target = if corrupt_capture {
                capture_sqlite_db_path(&storage)
            } else {
                git_sqlite_db_path(&storage)
            };
            let mut bytes = fs::read(&target).expect("read target db");
            bytes[..512].fill(0);
            fs::write(&target, &bytes).expect("write torn page-1 header");

            let started = Instant::now();
            let err = resume_forward_migration(&storage)
                .await
                .expect_err("AC3 torn page header must fail closed");
            assert_eq!(err.stable_code_str(), "LBR-IO-001", "AC3 {label}");
            assert!(
                started.elapsed().as_millis() <= FAIL_CLOSED_BUDGET_MS,
                "AC3 {label} fail-closed took {}ms (budget <= {FAIL_CLOSED_BUDGET_MS}ms)",
                started.elapsed().as_millis()
            );
            assert_eq!(
                fs::read(&target).expect("re-read target db"),
                bytes,
                "AC3 {label} must never mutate or silently drop source data"
            );
            assert!(
                !read_storage_manifest(&storage)
                    .expect("read manifest")
                    .expect("manifest present")
                    .finalized
            );
        }

        // AC4: non-sentinel schema corruption (both malformed non-sentinel table
        // SQL AND tampered `__libra_migrated_fence__` SQL) on BOTH `libra.db`
        // and `capture.db` fails closed without silently dropping source data.
        for (label, corrupt_capture, sql_mutation) in [
            (
                "git-non-sentinel-table",
                false,
                "UPDATE sqlite_master SET sql = 'CREATE TABLE bogus (' WHERE name = 'reference';",
            ),
            (
                "cap-non-sentinel-table",
                true,
                "UPDATE sqlite_master SET sql = 'CREATE TABLE bogus (' WHERE name = 'agent_session';",
            ),
            (
                "git-tampered-sentinel-sql",
                false,
                "CREATE TABLE __libra_migrated_fence__ (x INTEGER); PRAGMA writable_schema = ON; UPDATE sqlite_master SET sql = 'CORRUPT_BUT_NOT_OUR_SENTINEL' WHERE name = '__libra_migrated_fence__'; PRAGMA writable_schema = OFF;",
            ),
            (
                "cap-tampered-sentinel-sql",
                true,
                "CREATE TABLE __libra_migrated_fence__ (x INTEGER); PRAGMA writable_schema = ON; UPDATE sqlite_master SET sql = 'CORRUPT_BUT_NOT_OUR_SENTINEL' WHERE name = '__libra_migrated_fence__'; PRAGMA writable_schema = OFF;",
            ),
        ] {
            let dir = tempdir().expect("rb10d ac4 tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, label).await;
            crash_after_step2_1_pending(&storage, 1).await;
            let target = if corrupt_capture {
                capture_sqlite_db_path(&storage)
            } else {
                git_sqlite_db_path(&storage)
            };
            {
                let opts = SqliteConnectOptions::new()
                    .filename(&target)
                    .create_if_missing(false)
                    .busy_timeout(Duration::ZERO);
                let mut conn = SqliteConnection::connect_with(&opts)
                    .await
                    .expect("open target sqlite for non-sentinel corruption");
                conn.execute("PRAGMA writable_schema = ON;")
                    .await
                    .expect("enable writable_schema");
                conn.execute(sql_mutation)
                    .await
                    .expect("inject non-sentinel schema corruption");
                conn.execute("PRAGMA writable_schema = OFF;")
                    .await
                    .expect("disable writable_schema");
                conn.close().await.expect("close target sqlite");
            }
            let bytes_before = fs::read(&target).expect("snapshot corrupted source bytes");

            let started = Instant::now();
            let err = resume_forward_migration(&storage)
                .await
                .expect_err("AC4 non-sentinel schema corruption must fail closed");
            assert_eq!(err.stable_code_str(), "LBR-IO-001", "AC4 {label}");
            assert!(
                started.elapsed().as_millis() <= FAIL_CLOSED_BUDGET_MS,
                "AC4 {label} fail-closed took {}ms (budget <= {FAIL_CLOSED_BUDGET_MS}ms)",
                started.elapsed().as_millis()
            );
            assert_eq!(
                fs::read(&target).expect("re-read target db"),
                bytes_before,
                "AC4 {label} must never mutate or silently drop source data"
            );
            assert!(
                !read_storage_manifest(&storage)
                    .expect("read manifest")
                    .expect("manifest present")
                    .finalized
            );
        }
    }

    /// `RB-10d` AC5–AC6: missing or `backup_sha256`-mismatched backups for
    /// legally unlinked `libra.db` and `capture.db` each fail closed with
    /// `LBR-IO-001` within the `<= 100ms` budget.
    #[tokio::test]
    async fn forward_phase2_post_unlink_corrupt_backup_fails_closed() {
        const FAIL_CLOSED_BUDGET_MS: u128 = 100;

        for (label, target_capture, tamper_instead_of_delete) in [
            ("ac5-missing-git-backup", false, false),
            ("ac5-missing-cap-backup", true, false),
            ("ac6-tampered-git-backup", false, true),
            ("ac6-tampered-cap-backup", true, true),
        ] {
            let dir = tempdir().expect("rb10d ac5/ac6 tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, label).await;
            crash_forward_phase2_at_point(
                &storage,
                1,
                Phase2TestPoint::AfterParentDirFsyncBeforeClose(DatabaseRole::Capture),
            )
            .await;
            assert!(!git_sqlite_db_path(&storage).exists());
            assert!(!capture_sqlite_db_path(&storage).exists());

            let backup = if target_capture {
                sqlite_backup_capture_db_path(&storage, 1)
            } else {
                sqlite_backup_git_db_path(&storage, 1)
            };
            if tamper_instead_of_delete {
                let mut bytes = fs::read(&backup).expect("read backup");
                let mid = bytes.len() / 2;
                bytes[mid] ^= 0xFF;
                overwrite_backup_bytes_preserving_mode(&backup, &bytes);
            } else {
                fs::remove_file(&backup).expect("remove backup file");
            }

            let started = Instant::now();
            let err = resume_forward_migration(&storage)
                .await
                .expect_err("AC5/AC6 missing or tampered backup must fail closed");
            assert_eq!(err.stable_code_str(), "LBR-IO-001", "{label}");
            assert!(
                started.elapsed().as_millis() <= FAIL_CLOSED_BUDGET_MS,
                "{label} fail-closed took {}ms (budget <= {FAIL_CLOSED_BUDGET_MS}ms)",
                started.elapsed().as_millis()
            );
            assert!(
                !read_storage_manifest(&storage)
                    .expect("read manifest")
                    .expect("manifest present")
                    .finalized
            );
        }
    }

    /// `RB-10h` AC1 + AC4: after `libra.db` is already fenced and legally
    /// unlinked (`phase2_progress.git_db == "unlinked"`), post-crash writes to
    /// live `capture.db` and newly appended `capture-queue/` frames are
    /// reconciled via immutable verified `libra.db` backup + live `capture.db` +
    /// latest queue frames into `gen + 1` WITHOUT EVER resurrecting live
    /// `.libra/libra.db` (even if re-export crashes before publishing `gen + 1`
    /// manifest!).
    #[tokio::test]
    async fn forward_phase2_crash_capture_db_and_queue_post_crash_reexport() {
        use crate::storage::{
            FRAME_FLAG_NONE, GitStore as _, RedbCaptureStore, RedbGitStore, append_postcard_frame,
            capture_store::CaptureStore as _,
        };

        let dir = tempdir().expect("rb10h ac1/ac4 tempdir");
        let storage = dir.path().join(".libra");
        build_rb10c_layout_c_fixture(&storage, "rb10h-drift").await;
        let git_db = git_sqlite_db_path(&storage);
        let cap_db = capture_sqlite_db_path(&storage);

        crash_forward_phase2_at_point(
            &storage,
            1,
            Phase2TestPoint::AfterPersistUnlinked(DatabaseRole::Repository),
        )
        .await;
        assert!(!git_db.exists(), "libra.db must already be unlinked");
        assert!(cap_db.exists(), "capture.db must still be pending");

        // Post-crash legacy write to live `capture.db`.
        {
            let opts = SqliteConnectOptions::new()
                .filename(&cap_db)
                .create_if_missing(false)
                .busy_timeout(Duration::ZERO);
            let mut conn = SqliteConnection::connect_with(&opts)
                .await
                .expect("open live capture.db");
            conn.execute(
                "INSERT INTO agent_session (session_id, agent_kind, provider_session_id, thread_id, state, working_dir, worktree_id, parent_commit, parent_session_id, metadata_json, redaction_report, started_at, last_event_at, stopped_at, schema_version, sync_revision, repo_id, workspace_id, workspace_fence, scope_state) VALUES ('sess-rb10h-post', 'codex', 'prov-rb10h-post', NULL, 'active', '/work/rb10h', 'wt-1', NULL, NULL, '{}', '{}', 1795402000, 1795402010, NULL, 1, 1, 'repo-1', 'ws-1', 1, 'scoped');",
            )
            .await
            .expect("insert post-crash capture session");
            conn.close().await.expect("close capture.db");
        }

        // Post-crash queue frame append (AC4).
        let usage = AgentUsageStatsRecord {
            id: "usage-rb10h-post".to_string(),
            session_id: None,
            thread_id: None,
            agent_run_id: None,
            run_id: None,
            provider: "openai".to_string(),
            model: "gpt-5".to_string(),
            request_kind: "chat".to_string(),
            intent: None,
            prompt_tokens: 11,
            completion_tokens: 22,
            cached_tokens: 0,
            reasoning_tokens: 0,
            total_tokens: 33,
            tool_call_count: 0,
            wall_clock_ms: 4,
            provider_latency_ms: None,
            cost_estimate_micro_dollars: None,
            cost_usd: None,
            usage_estimated: false,
            started_at: None,
            finished_at: None,
            success: true,
            error_kind: None,
            schema_version: 1,
            created_at: "2026-11-24T02:00:00Z".to_string(),
            agent_name: Some("codex".to_string()),
            repo_id: Some("repo-1".to_string()),
            turn_id: Some("turn-rb10h-post".to_string()),
            event_id: Some("evt-rb10h-post".to_string()),
        };
        append_postcard_frame(
            &storage,
            CaptureQueueLane::Normal,
            FRAME_FLAG_NONE,
            "dedup:rb10h:q-post",
            CAPTURE_QUEUE_PAYLOAD_SCHEMA_VERSION,
            &CaptureBatchPayload::InsertUsageStats(usage),
        )
        .expect("append post-crash queue frame");

        // Crash-safety proof: even if `gen + 1` re-export suffers SIGKILL after
        // promotion and BEFORE manifest publish, live `.libra/libra.db` MUST
        // NEVER be resurrected and the next resume MUST still converge cleanly!
        resume_forward_migration_inner(
            DatabaseRole::Repository,
            &storage,
            None,
            None,
            Some(ForwardDriftReexportCrashPoint::AfterPromotionBeforeManifest),
        )
        .await
        .expect_err("injected SIGKILL before gen+1 manifest publish");
        assert!(
            !git_db.exists(),
            "cross-source re-export MUST NEVER resurrect unlinked live libra.db"
        );

        let resumed = resume_forward_migration(&storage).await.expect(
            "resume must merge verified libra.db backup + live capture.db + queue into gen+1",
        );
        assert_eq!(resumed.initial_generation, 1);
        assert_eq!(resumed.final_generation, 2, "AC1 exact gen+1");
        assert!(
            resumed.reexported_due_to_drift,
            "AC1 reexported_due_to_drift"
        );
        assert!(
            resumed.max_reexport_batch_rows <= FORWARD_MIGRATION_STREAM_BATCH_ROWS,
            "streaming batch cap <= 500"
        );
        assert_eq!(
            resumed.git_recovery_state,
            ForwardSourceRecoveryState::LegallyAbsentPostUnlink
        );
        assert_eq!(
            resumed.capture_recovery_state,
            ForwardSourceRecoveryState::DriftedLivePending
        );
        assert!(resumed.queue_drift_detected, "AC4 queue drift detected");
        assert!(resumed.finalized.manifest.finalized);
        assert!(!git_db.exists(), "libra.db remains unlinked");
        assert!(!cap_db.exists(), "capture.db fenced and unlinked");

        // Verify Git rows (from verified backup), pre-crash + post-crash Capture
        // rows, pre-crash Spool event, and pre-crash + post-crash Queue frames
        // are 100% preserved in `gen-00000002`!
        let git_store = RedbGitStore::open_read_only(&resumed.finalized.git_redb_path)
            .expect("open git.gen-00000002.redb");
        assert!(
            !git_store
                .list_refs(None)
                .await
                .expect("list git refs")
                .is_empty(),
            "AC1 backed-up git rows preserved in gen+1"
        );
        let cap_store = RedbCaptureStore::open_read_only(&resumed.finalized.capture_redb_path)
            .await
            .expect("open capture.gen-00000002.redb");
        assert!(
            cap_store
                .get_session("sess-rb10h-post")
                .await
                .expect("get post-crash capture session")
                .is_some(),
            "AC1 post-crash capture.db session preserved"
        );
        assert!(
            cap_store
                .get_usage_stats("usage-rb10h-drift-1")
                .await
                .expect("get pre-crash queue usage")
                .is_some(),
            "AC4 pre-crash queue frame preserved"
        );
        assert!(
            cap_store
                .get_usage_stats("usage-rb10h-post")
                .await
                .expect("get post-crash queue usage")
                .is_some(),
            "AC4 post-crash queue frame preserved"
        );
        let sessions = cap_store
            .list_sessions_by_started_desc()
            .await
            .expect("list capture sessions");
        let providers: Vec<&str> = sessions
            .iter()
            .map(|s| s.provider_session_id.as_str())
            .collect();
        assert!(
            providers.contains(&"prov-rb10h-drift"),
            "AC1 pre-crash spool session preserved: {providers:?}"
        );
    }

    /// `RB-10h` AC2 + AC3: crash in the gap between removing `capture-spool/`
    /// subdirectories and installing `0400` tombstones:
    /// - AC2 (no concurrent hook): reacquires in-place `capacity.lock`, verifies
    ///   backed-up `.libra/sqlite-backup/<gen>/capture-spool/`, installs all 3
    ///   `0400` tombstones, and converges on `gen = 1` with zero data loss.
    /// - AC3 (concurrent old hook recreates `ready/` and publishes new confirmed
    ///   events, including a same-filename collision sub-case): reacquires
    ///   in-place `capacity.lock`, merges **backup ∪ live `capture-spool/ready/`**
    ///   by dedup key into `gen + 1` (without ever resurrecting `libra.db` or
    ///   `capture.db`), backs up the full union into `gen + 1`, installs all 3
    ///   `0400` tombstones, and preserves BOTH pre-crash backed-up events AND
    ///   concurrent-hook live events 100% losslessly.
    #[tokio::test]
    async fn forward_phase2_spool_tombstone_gap_crash_and_concurrent_hook_reconcile() {
        use crate::storage::{RedbCaptureStore, capture_store::CaptureStore as _};

        // --------------------------------------------------------------------
        // AC2: Spool tombstone gap crash with NO concurrent legacy hook writes.
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("rb10h ac2 tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10h-gap").await;
            let prepared = prepare_forward_phase1(&storage, 1)
                .await
                .expect("Phase 1 prepare");
            let fenced = execute_forward_phase2_fence_and_unlink(prepared)
                .await
                .expect("Phase 2 fence + unlink");
            let mut hook = |point: Phase2FinalizeTestPoint, _root: &Path| -> StorageResult<()> {
                if point == Phase2FinalizeTestPoint::AfterRmdirBeforeLinkTombstone("ready") {
                    return Err(StorageBackendError::BackendInternal {
                        detail: "RB-10h AC2 injected spool gap crash".to_string(),
                    });
                }
                Ok(())
            };
            finalize_forward_phase2_spool_tombstones_and_manifest_inner(fenced, Some(&mut hook))
                .expect_err("injected AC2 spool gap crash");
            assert!(
                !read_storage_manifest(&storage)
                    .expect("read manifest")
                    .expect("manifest present")
                    .finalized
            );

            let resumed = resume_forward_migration(&storage)
                .await
                .expect("AC2 resume must verify backup, install 3 tombstones, and finalize");
            assert_eq!(resumed.final_generation, 1, "AC2 stays on gen=1");
            assert!(!resumed.reexported_due_to_drift, "AC2 no drift re-export");
            assert!(resumed.finalized.manifest.finalized, "AC2 finalized");
            assert!(resumed.finalized.manifest.phase2_progress.spool_fenced);
            for slot in CAPTURE_SPOOL_TOMBSTONE_NAMES {
                let path = capture_spool_dir_path(&storage).join(slot);
                assert_eq!(
                    fs::read(&path).expect("read AC2 tombstone"),
                    CAPTURE_SPOOL_TOMBSTONE_SENTINEL,
                    "AC2 tombstone {slot}"
                );
                #[cfg(unix)]
                {
                    use std::os::unix::fs::PermissionsExt as _;
                    let mode = fs::symlink_metadata(&path)
                        .expect("stat tombstone")
                        .permissions()
                        .mode()
                        & 0o777;
                    assert_eq!(mode, 0o400, "AC2 tombstone {slot} must be 0400");
                }
            }
            assert_rb10k_layout_c_converged(&storage, &resumed, "rb10h-gap", "rb10h-gap").await;
        }

        // --------------------------------------------------------------------
        // AC3: Spool tombstone gap crash WITH concurrent legacy hook recreating
        // `ready/` and writing BOTH a fresh filename AND a colliding filename
        // carrying a new event payload (plus a duplicate-dedup-key event).
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("rb10h ac3 tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10h-hook").await;
            let prepared = prepare_forward_phase1(&storage, 1)
                .await
                .expect("Phase 1 prepare");
            let fenced = execute_forward_phase2_fence_and_unlink(prepared)
                .await
                .expect("Phase 2 fence + unlink");
            let mut hook = |point: Phase2FinalizeTestPoint, _root: &Path| -> StorageResult<()> {
                if point == Phase2FinalizeTestPoint::AfterRmdirBeforeLinkTombstone("ready") {
                    return Err(StorageBackendError::BackendInternal {
                        detail: "RB-10h AC3 injected spool gap crash".to_string(),
                    });
                }
                Ok(())
            };
            finalize_forward_phase2_spool_tombstones_and_manifest_inner(fenced, Some(&mut hook))
                .expect_err("injected AC3 spool gap crash");

            // Confirm both SQLite sources are already unlinked & live `ready/`
            // is gone while the pre-crash event survives in gen-1 backup.
            assert!(!git_sqlite_db_path(&storage).exists());
            assert!(!capture_sqlite_db_path(&storage).exists());
            let ready = capture_spool_dir_path(&storage).join(CAPTURE_SPOOL_READY_SUBDIR);
            assert!(!ready.exists());

            // Compute the exact SHA-256 prefix of the gen-1 backed-up spool file so
            // we can also test a secondary collision against the primary disambiguated
            // candidate name (`prior-gen-00000001-<sha8>-0001-rb10h-hook.json`).
            let gen1_file_bytes = fs::read(
                sqlite_backup_capture_spool_dir_path(&storage, 1)
                    .join(CAPTURE_SPOOL_READY_SUBDIR)
                    .join("0001-rb10h-hook.json"),
            )
            .expect("read gen-1 backed-up spool file");
            let mut gen1_hasher = Sha256::new();
            gen1_hasher.update(&gen1_file_bytes);
            let gen1_sha8 = sha256_hex_from_hasher(gen1_hasher)[..8].to_string();
            let primary_disambig_name =
                format!("prior-gen-00000001-{gen1_sha8}-0001-rb10h-hook.json");

            // Concurrent legacy hook recreates `ready/` and publishes:
            // 1. A brand-new event file (`0002-rb10h-hook.json`).
            // 2. A colliding filename (`0001-rb10h-hook.json` — exact same filename
            //    as the pre-crash backed-up spool file!) carrying a distinct event.
            // 3. A secondary-collision file literally named `primary_disambig_name`
            //    carrying another distinct event (proving the union backup NEVER
            //    silently omits a prior event when the primary disambiguated name
            //    is already occupied by different bytes!).
            // 4. A duplicate-dedup-key replay (`0003-rb10h-hook-dup.json` with
            //    `dedup:rb10h-hook:spool-1`) proving dedup across backup ∪ live
            //    ignores replays with zero double-counting.
            fs::create_dir_all(&ready).expect("recreate ready dir");
            fs::write(
                ready.join("0002-rb10h-hook.json"),
                build_spool_envelope_bytes(
                    "codex",
                    "codex",
                    "33333333-3333-4333-8333-333333333399",
                    Some("dedup:rb10h:hook-1"),
                    "prov-rb10h-hook-live-1",
                    "/work/rb10h-hook",
                    &storage,
                    "session_start",
                    "2026-11-24T03:00:00Z",
                    "",
                ),
            )
            .expect("write concurrent hook event 1");
            fs::write(
                ready.join("0001-rb10h-hook.json"),
                build_spool_envelope_bytes(
                    "codex",
                    "codex",
                    "44444444-4444-4444-8444-444444444488",
                    Some("dedup:rb10h:hook-collision"),
                    "prov-rb10h-hook-live-collision",
                    "/work/rb10h-hook",
                    &storage,
                    "session_start",
                    "2026-11-24T03:05:00Z",
                    "",
                ),
            )
            .expect("write concurrent hook colliding-name event");
            fs::write(
                ready.join(&primary_disambig_name),
                build_spool_envelope_bytes(
                    "codex",
                    "codex",
                    "66666666-6666-4666-8666-666666666666",
                    Some("dedup:rb10h:hook-disambig-collision"),
                    "prov-rb10h-hook-live-disambig-collision",
                    "/work/rb10h-hook",
                    &storage,
                    "session_start",
                    "2026-11-24T03:05:30Z",
                    "",
                ),
            )
            .expect("write concurrent hook secondary disambiguated collision event");
            fs::write(
                ready.join("0003-rb10h-hook-dup.json"),
                build_spool_envelope_bytes(
                    "codex",
                    "codex",
                    "55555555-5555-4555-8555-555555555577",
                    Some("dedup:rb10h-hook:spool-1"),
                    "prov-rb10h-hook-dup-ignored",
                    "/work/rb10h-hook",
                    &storage,
                    "session_start",
                    "2026-11-24T03:06:00Z",
                    "",
                ),
            )
            .expect("write concurrent hook duplicate-dedup-key replay");

            let resumed = resume_forward_migration(&storage)
                .await
                .expect("AC3 resume must union backup ∪ live spool events into gen+1");
            assert_eq!(resumed.initial_generation, 1);
            assert_eq!(resumed.final_generation, 2, "AC3 exact gen+1");
            assert!(resumed.reexported_due_to_drift, "AC3 drift re-export");
            assert!(resumed.spool_drift_detected, "AC3 spool drift detected");
            assert!(resumed.finalized.manifest.finalized, "AC3 finalized");
            assert!(resumed.finalized.manifest.phase2_progress.spool_fenced);
            assert!(
                !git_sqlite_db_path(&storage).exists(),
                "AC3 must never resurrect libra.db"
            );
            assert!(
                !capture_sqlite_db_path(&storage).exists(),
                "AC3 must never resurrect capture.db"
            );

            for slot in CAPTURE_SPOOL_TOMBSTONE_NAMES {
                let path = capture_spool_dir_path(&storage).join(slot);
                assert_eq!(
                    fs::read(&path).expect("read AC3 tombstone"),
                    CAPTURE_SPOOL_TOMBSTONE_SENTINEL,
                    "AC3 tombstone {slot}"
                );
                #[cfg(unix)]
                {
                    use std::os::unix::fs::PermissionsExt as _;
                    let mode = fs::symlink_metadata(&path)
                        .expect("stat AC3 tombstone")
                        .permissions()
                        .mode()
                        & 0o777;
                    assert_eq!(mode, 0o400, "AC3 tombstone {slot} must be 0400");
                }
            }

            // CRITICAL AC3 PROOF: BOTH the pre-crash backed-up spool event
            // (`prov-rb10h-hook`) AND BOTH concurrent-hook live events
            // (`prov-rb10h-hook-live-1` & `prov-rb10h-hook-live-collision`)
            // MUST be 100% present in `capture.gen-00000002.redb`!
            let cap_store = RedbCaptureStore::open_read_only(&resumed.finalized.capture_redb_path)
                .await
                .expect("open capture.gen-00000002.redb");
            let sessions = cap_store
                .list_sessions_by_started_desc()
                .await
                .expect("list capture sessions");
            let provider_ids: Vec<&str> = sessions
                .iter()
                .map(|s| s.provider_session_id.as_str())
                .collect();
            assert!(
                provider_ids.contains(&"prov-rb10h-hook"),
                "AC3 pre-crash backed-up spool event MUST NOT be lost: {provider_ids:?}"
            );
            assert!(
                provider_ids.contains(&"prov-rb10h-hook-live-1"),
                "AC3 concurrent-hook live event 1 must be preserved: {provider_ids:?}"
            );
            assert!(
                provider_ids.contains(&"prov-rb10h-hook-live-collision"),
                "AC3 concurrent-hook colliding-filename event must be preserved: {provider_ids:?}"
            );
            assert!(
                provider_ids.contains(&"prov-rb10h-hook-live-disambig-collision"),
                "AC3 concurrent-hook secondary disambiguated-filename collision event must be preserved: {provider_ids:?}"
            );
            assert!(
                !provider_ids.contains(&"prov-rb10h-hook-dup-ignored"),
                "AC3 duplicate-dedup-key replay must be deduplicated cleanly: {provider_ids:?}"
            );

            // Also verify `gen-00000002` spool backup contains all 5 union files
            // (4 live files + 1 secondary-disambiguated `prior-gen-00000001-<sha8>-0001-*`
            // prior-gen file, proving zero silent omission even under secondary name collision)!
            let gen2_ready_bk =
                sqlite_backup_capture_spool_dir_path(&storage, 2).join(CAPTURE_SPOOL_READY_SUBDIR);
            let bk_entries: Vec<String> = fs::read_dir(&gen2_ready_bk)
                .expect("read gen-2 spool ready backup")
                .map(|e| e.expect("entry").file_name().to_string_lossy().to_string())
                .collect();
            assert_eq!(
                bk_entries.len(),
                5,
                "gen-2 backup must preserve full backup ∪ live union including secondary-disambiguated colliding filename: {bk_entries:?}"
            );
            let expected_secondary_name =
                format!("prior-gen-00000001-{gen1_sha8}-0001-0001-rb10h-hook.json");
            assert!(
                bk_entries.contains(&expected_secondary_name),
                "gen-2 backup must allocate unique secondary disambiguated filename {expected_secondary_name}: {bk_entries:?}"
            );
        }

        // --------------------------------------------------------------------
        // Snapshot authenticity regression (`ready/` AND `quarantine/`):
        // 1. Mutating the original `.libra/sqlite-backup/<gen>/capture-spool/`
        //    AFTER `verify_spool_backup_manifest_for_recovery` still consumes
        //    the exact originally authenticated bytes during both redb ingest
        //    and union backup.
        // 2. Tampering with or removing any `ready/` or `quarantine/` file inside
        //    the snapshot itself fails closed (`LBR-IO-001`) before publication.
        // --------------------------------------------------------------------
        {
            let dir = tempdir().expect("rb10h snapshot regression tempdir");
            let storage = dir.path().join(".libra");
            build_rb10c_layout_c_fixture(&storage, "rb10h-snap").await;
            let q_dir = capture_spool_dir_path(&storage).join(CAPTURE_SPOOL_QUARANTINE_SUBDIR);
            fs::create_dir_all(&q_dir).expect("create live quarantine dir");
            fs::write(q_dir.join("q-0001.json"), b"{\"quarantined\":\"orig\"}")
                .expect("write quarantine fixture");
            let prepared = prepare_forward_phase1(&storage, 1)
                .await
                .expect("Phase 1 prepare");
            let expected_spool_sha = prepared.backup.spool_backup.spool_manifest_sha256.clone();
            let _ = execute_forward_phase2_fence_and_unlink(prepared)
                .await
                .expect("Phase 2 fence + unlink");

            let snap = verify_spool_backup_manifest_for_recovery(
                &storage,
                "sqlite-backup/00000001",
                &expected_spool_sha,
                #[cfg(unix)]
                &[],
            )
            .expect("authenticate gen-1 spool backup snapshot");

            // 1. Mutate BOTH `ready/` and `quarantine/` in the original on-disk
            //    gen-1 backup AFTER authentication.
            let orig_bk_spool = sqlite_backup_capture_spool_dir_path(&storage, 1);
            fs::write(
                orig_bk_spool
                    .join(CAPTURE_SPOOL_READY_SUBDIR)
                    .join("0001-rb10h-snap.json"),
                b"CORRUPTED-ORIGINAL-BACKUP",
            )
            .expect("corrupt original backup ready file");
            fs::remove_file(
                orig_bk_spool
                    .join(CAPTURE_SPOOL_QUARANTINE_SUBDIR)
                    .join("q-0001.json"),
            )
            .expect("remove original backup quarantine file");

            // Downstream union backup & ingest still succeed with exact original bytes!
            let dst_gen_dir = sqlite_backup_dir_path(&storage, 9);
            fs::create_dir_all(&dst_gen_dir).expect("create test dst gen dir");
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt as _;
                fs::set_permissions(&dst_gen_dir, fs::Permissions::from_mode(0o700))
                    .expect("chmod test dst gen dir");
            }
            let dst_spool_dir = dst_gen_dir.join(CAPTURE_SPOOL_SUBDIR);
            let union_ok = backup_capture_spool_union_inner(
                &storage,
                &snap,
                1,
                &dst_spool_dir,
                "sqlite-backup/00000009/capture-spool",
                "sqlite-backup/00000009",
                #[cfg(unix)]
                &[],
                None,
            )
            .expect(
                "union backup must consume authenticated snapshot unaffected by original mutation",
            );
            assert_eq!(union_ok.spool_manifest_sha256, expected_spool_sha);
            assert_eq!(
                fs::read(
                    dst_spool_dir
                        .join(CAPTURE_SPOOL_QUARANTINE_SUBDIR)
                        .join("q-0001.json")
                )
                .expect("read preserved quarantine file"),
                b"{\"quarantined\":\"orig\"}"
            );

            let ok_redb_path = dir.path().join("snap-ingest-ok.redb");
            let ok_redb = RedbDatabase::create(&ok_redb_path).expect("create ok test redb");
            initialize_capture_export_redb_schema(&ok_redb, true)
                .expect("init ok capture redb schema");
            let mut ok_telemetry = ExportStreamTelemetry::new();
            let ok_ingest = ingest_capture_spool_ready_from_backup_readonly(
                &storage,
                &snap,
                &ok_redb,
                &mut ok_telemetry,
                #[cfg(unix)]
                &[],
            )
            .expect("ingest must consume authenticated snapshot unaffected by original mutation");
            assert_eq!(ok_ingest.files_read, 1);
            assert_eq!(ok_ingest.applied_events, 1);

            // 2. Tamper `ready/` inside the private snapshot -> BOTH ingest AND
            //    union backup MUST fail closed `LBR-IO-001`.
            let snap_ready = snap
                .snapshot_spool_dir
                .join(CAPTURE_SPOOL_READY_SUBDIR)
                .join("0001-rb10h-snap.json");
            let saved_ready = fs::read(&snap_ready).expect("save snap ready");
            fs::write(&snap_ready, b"TAMPERED-SNAPSHOT-READY").expect("tamper snap ready");

            let test_redb_path = dir.path().join("snap-ingest-check.redb");
            let test_redb = RedbDatabase::create(&test_redb_path).expect("create test redb");
            initialize_capture_export_redb_schema(&test_redb, true)
                .expect("init capture redb schema");
            let mut telemetry = ExportStreamTelemetry::new();
            let ingest_err = ingest_capture_spool_ready_from_backup_readonly(
                &storage,
                &snap,
                &test_redb,
                &mut telemetry,
                #[cfg(unix)]
                &[],
            )
            .expect_err("tampered snapshot ready file must fail closed during ingest");
            assert_eq!(ingest_err.stable_code_str(), "LBR-IO-001");

            let dst_gen_dir2 = sqlite_backup_dir_path(&storage, 10);
            fs::create_dir_all(&dst_gen_dir2).expect("create test dst gen dir 2");
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt as _;
                fs::set_permissions(&dst_gen_dir2, fs::Permissions::from_mode(0o700))
                    .expect("chmod test dst gen dir 2");
            }
            let union_ready_err = backup_capture_spool_union_inner(
                &storage,
                &snap,
                1,
                &dst_gen_dir2.join(CAPTURE_SPOOL_SUBDIR),
                "sqlite-backup/00000010/capture-spool",
                "sqlite-backup/00000010",
                #[cfg(unix)]
                &[],
                None,
            )
            .expect_err("tampered snapshot ready file must fail closed during union backup");
            assert_eq!(union_ready_err.stable_code_str(), "LBR-IO-001");

            // Restore `ready/`, then delete `quarantine/` inside the private
            // snapshot -> union backup MUST fail closed `LBR-IO-001`.
            fs::write(&snap_ready, saved_ready).expect("restore snap ready");
            fs::remove_file(
                snap.snapshot_spool_dir
                    .join(CAPTURE_SPOOL_QUARANTINE_SUBDIR)
                    .join("q-0001.json"),
            )
            .expect("delete snap quarantine file");
            let dst_gen_dir3 = sqlite_backup_dir_path(&storage, 11);
            fs::create_dir_all(&dst_gen_dir3).expect("create test dst gen dir 3");
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt as _;
                fs::set_permissions(&dst_gen_dir3, fs::Permissions::from_mode(0o700))
                    .expect("chmod test dst gen dir 3");
            }
            let union_q_err = backup_capture_spool_union_inner(
                &storage,
                &snap,
                1,
                &dst_gen_dir3.join(CAPTURE_SPOOL_SUBDIR),
                "sqlite-backup/00000011/capture-spool",
                "sqlite-backup/00000011",
                #[cfg(unix)]
                &[],
                None,
            )
            .expect_err("deleted snapshot quarantine file must fail closed during union backup");
            assert_eq!(union_q_err.stable_code_str(), "LBR-IO-001");
        }
    }

    /// Build a finalized Redb repository fixture (`storage-format.json` with
    /// `backend = "redb", finalized = true, generation = 1`, `git.gen-00000001.redb`,
    /// `capture.gen-00000001.redb`, initialized `capture-queue/`, and `capture-spool/`
    /// tombstones) for reverse migration Phase 1/2 tests (`RB-11`+).
    async fn build_rb11_finalized_redb_repo_fixture(storage: &Path) -> (PathBuf, PathBuf) {
        use crate::storage::{
            RedbCaptureStore, RedbGitStore, StorageFormatManifest, init_capture_queue,
            init_redb_capture_spool_tombstones, publish_storage_manifest,
        };

        fs::create_dir_all(storage.join(REDB_SUBDIR)).expect("create .libra/redb");
        fs::create_dir_all(storage.join(PRIVATE_SUBDIR)).expect("create .libra/private");
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;
            fs::set_permissions(
                storage.join(PRIVATE_SUBDIR),
                fs::Permissions::from_mode(0o700),
            )
            .expect("chmod 0700 private");
        }

        let git_path = git_redb_path(storage, 1);
        let cap_path = capture_redb_path(storage, 1);
        let git_store = RedbGitStore::create(&git_path).expect("create git.gen-00000001.redb");
        drop(git_store);
        let cap_store = RedbCaptureStore::create(&cap_path)
            .await
            .expect("create capture.gen-00000001.redb");
        drop(cap_store);
        let _q = init_capture_queue(storage).expect("init capture-queue");
        let _tomb = init_redb_capture_spool_tombstones(storage)
            .expect("init fresh redb capture-spool tombstones");

        let manifest =
            StorageFormatManifest::new_redb_finalized(1).expect("new finalized redb manifest");
        publish_storage_manifest(storage, &manifest).expect("publish finalized redb manifest");
        (git_path, cap_path)
    }

    /// `RB-11` AC1–AC5: symmetric reverse migration Phase 1 redb writer
    /// quiescence gate and strict `ADR-RB-07` #2 global lock order:
    /// - AC1 + AC2: external OS-process `git.redb` writer -> fail-closed
    ///   `LBR-IO-001` with exact byte-for-byte unchanged `git.redb` & `capture.redb`.
    /// - AC3 + AC4: external OS-process `capture.redb` writer -> fail-closed
    ///   `LBR-IO-001` with exact byte-for-byte unchanged `git.redb` & `capture.redb`.
    /// - AC5: strict 8-step canonical global lock order
    ///   `migration.lock -> maintenance.lock -> capture-spool-consumer.lock ->
    ///    writer.lock -> capture-queue/append.lock -> capture-spool/capacity.lock ->
    ///    (git_wtx, cap_wtx)`, verified via observer + live OS-child busy probes
    ///   on all 8 locks + uncontended latency budget `<= 50ms` + `GC-13` role
    ///   rejection + unfinalized/SQLite manifest rejection.
    #[tokio::test]
    async fn reverse_phase1_quiescence_rejects_redb_writers_and_enforces_lock_order() {
        struct RecordingReverseObserver {
            stages: Vec<ReversePhase1QuiesceStage>,
        }
        impl ReversePhase1LockObserver for RecordingReverseObserver {
            fn on_stage_acquired(&mut self, stage: ReversePhase1QuiesceStage) {
                self.stages.push(stage);
            }
        }

        let dir = tempdir().expect("rb11 tempdir");
        let storage = dir.path().join(".libra");
        let (git_path, cap_path) = build_rb11_finalized_redb_repo_fixture(&storage).await;

        let cap_bytes_initial = fs::read(&cap_path).expect("snapshot initial capture.redb");

        // --------------------------------------------------------------------
        // AC1 + AC2: External OS-process `git.redb` writer returns `LBR-IO-001`
        // AND preserves BOTH `git.redb` and `capture.redb` byte-for-byte!
        // --------------------------------------------------------------------
        {
            let holder = ChildLockHolder::spawn("hold_redb_git_write_tx", &git_path);
            let git_bytes_before = fs::read(&git_path).expect("snapshot git.redb before AC1");
            let cap_bytes_before = fs::read(&cap_path).expect("snapshot capture.redb before AC1");
            let err = quiesce_reverse_repository_phase1(&storage)
                .expect_err("AC1: active external git.redb writer must fail closed");
            assert_eq!(
                err.stable_code_str(),
                "LBR-IO-001",
                "AC1: external git.redb writer must return LBR-IO-001, got: {err}"
            );
            assert_eq!(
                fs::read(&git_path).expect("read git.redb after AC1"),
                git_bytes_before,
                "AC2: git.redb must remain byte-for-byte identical across AC1 rejection"
            );
            assert_eq!(
                fs::read(&cap_path).expect("read capture.redb after AC1"),
                cap_bytes_before,
                "AC2: capture.redb must remain byte-for-byte identical across AC1 rejection"
            );
            assert_eq!(
                cap_bytes_before, cap_bytes_initial,
                "AC2: uncontended capture.redb must match initial clean snapshot"
            );
            // Also verify preflight created ZERO stray `migration.lock` on rejection!
            assert!(
                !migration_lock_path(&storage).exists(),
                "AC2: rejected preflight must not create migration.lock"
            );
            holder.release_and_wait();
        }

        // Refresh clean resting snapshots after external git child exited cleanly
        // (redb's own `Database::drop()` on the child commits allocator state).
        let git_bytes_resting = fs::read(&git_path).expect("snapshot resting git.redb");
        let cap_bytes_resting = fs::read(&cap_path).expect("snapshot resting capture.redb");
        assert_eq!(
            cap_bytes_resting, cap_bytes_initial,
            "AC2: uncontended capture.redb must stay unchanged after external git writer exits"
        );

        // --------------------------------------------------------------------
        // AC3 + AC4: External OS-process `capture.redb` writer returns
        // `LBR-IO-001` AND preserves BOTH `git.redb` and `capture.redb`
        // byte-for-byte!
        // --------------------------------------------------------------------
        {
            let holder = ChildLockHolder::spawn("hold_redb_capture_write_tx", &cap_path);
            let git_bytes_before = fs::read(&git_path).expect("snapshot git.redb before AC3");
            let cap_bytes_before = fs::read(&cap_path).expect("snapshot capture.redb before AC3");
            let err = quiesce_reverse_repository_phase1(&storage)
                .expect_err("AC3: active external capture.redb writer must fail closed");
            assert_eq!(
                err.stable_code_str(),
                "LBR-IO-001",
                "AC3: external capture.redb writer must return LBR-IO-001, got: {err}"
            );
            assert_eq!(
                fs::read(&git_path).expect("read git.redb after AC3"),
                git_bytes_before,
                "AC4: git.redb must remain byte-for-byte identical across AC3 rejection"
            );
            assert_eq!(
                git_bytes_before, git_bytes_resting,
                "AC4: uncontended git.redb must match resting snapshot"
            );
            assert_eq!(
                fs::read(&cap_path).expect("read capture.redb after AC3"),
                cap_bytes_before,
                "AC4: capture.redb must remain byte-for-byte identical across AC3 rejection"
            );
            assert!(
                !migration_lock_path(&storage).exists(),
                "AC4: rejected preflight must not create migration.lock"
            );
            holder.release_and_wait();
        }

        let git_bytes_clean = fs::read(&git_path).expect("snapshot clean git.redb before AC5");
        let cap_bytes_clean = fs::read(&cap_path).expect("snapshot clean capture.redb before AC5");
        assert_eq!(
            git_bytes_clean, git_bytes_resting,
            "AC4: uncontended git.redb must stay unchanged after external capture writer exits"
        );

        // --------------------------------------------------------------------
        // AC5: Strict global lock order + live OS-process mutual exclusion on
        // ALL 8 locks + zero-byte-touch Phase 1 CoW + `<= 50ms` uncontended
        // performance budget!
        // --------------------------------------------------------------------
        {
            // First verify full acquire + hold + abort writes ZERO bytes to
            // EITHER `git.redb` or `capture.redb` on disk (both while held AND
            // after `abort_and_release()`)!
            let mut recorder = RecordingReverseObserver { stages: Vec::new() };
            let guard = quiesce_reverse_repository_phase1_inner(&storage, Some(&mut recorder))
                .expect("AC5: uncontended reverse quiescence must succeed");
            assert_eq!(
                recorder.stages,
                vec![
                    ReversePhase1QuiesceStage::MigrationLock,
                    ReversePhase1QuiesceStage::MaintenanceLock,
                    ReversePhase1QuiesceStage::CaptureSpoolConsumerLock,
                    ReversePhase1QuiesceStage::CaptureQueueWriterLock,
                    ReversePhase1QuiesceStage::CaptureQueueAppendLock,
                    ReversePhase1QuiesceStage::CaptureSpoolCapacityLock,
                    ReversePhase1QuiesceStage::GitRedbWriteTransaction,
                    ReversePhase1QuiesceStage::CaptureRedbWriteTransaction,
                ],
                "AC5: reverse migration MUST acquire all 8 locks in exact ADR-RB-07 #2 order"
            );
            assert_eq!(guard.redb().generation(), 1);
            assert_eq!(guard.redb().git_redb_path(), git_path.as_path());
            assert_eq!(guard.redb().capture_redb_path(), cap_path.as_path());

            // Even WHILE `(git_wtx, cap_wtx)` are held, disk bytes stay 100%
            // clean and byte-for-byte identical to pre-quiescence snapshots!
            assert_eq!(
                fs::read(&git_path).expect("read git.redb while quiesced"),
                git_bytes_clean,
                "Phase 1 CoW overlay must leave git.redb byte-identical while quiesced"
            );
            assert_eq!(
                fs::read(&cap_path).expect("read capture.redb while quiesced"),
                cap_bytes_clean,
                "Phase 1 CoW overlay must leave capture.redb byte-identical while quiesced"
            );

            // Confirm via real OS child processes that ALL 8 locks are held!
            run_child_busy_probe("probe_flock_busy", &migration_lock_path(&storage));
            run_child_busy_probe("probe_maintenance_shared_busy", &storage);
            run_child_busy_probe(
                "probe_flock_busy",
                &capture_spool_consumer_lock_path(&storage),
            );
            run_child_busy_probe(
                "probe_flock_busy",
                &capture_queue_writer_lock_path(&storage),
            );
            run_child_busy_probe(
                "probe_flock_busy",
                &capture_queue_append_lock_path(&storage),
            );
            run_child_busy_probe(
                "probe_flock_busy",
                &capture_spool_capacity_lock_path(&storage),
            );
            run_child_busy_probe("probe_redb_git_write_busy", &git_path);
            run_child_busy_probe("probe_redb_capture_write_busy", &cap_path);

            guard
                .abort_and_release()
                .expect("abort and release reverse quiesce guard");
            assert_eq!(
                fs::read(&git_path).expect("read git.redb after abort"),
                git_bytes_clean,
                "abort_and_release must leave git.redb byte-identical"
            );
            assert_eq!(
                fs::read(&cap_path).expect("read capture.redb after abort"),
                cap_bytes_clean,
                "abort_and_release must leave capture.redb byte-identical"
            );

            // Second warm uncontended run (all 6 lock files materialized):
            // verify `<= 50ms` uncontended performance budget!
            let mut recorder2 = RecordingReverseObserver { stages: Vec::new() };
            let started = Instant::now();
            let guard2 = quiesce_reverse_repository_phase1_inner(&storage, Some(&mut recorder2))
                .expect("warm uncontended reverse quiescence must succeed");
            let elapsed = started.elapsed();
            guard2
                .abort_and_release()
                .expect("release warm reverse quiesce guard");
            assert!(
                elapsed <= Duration::from_millis(50),
                "RB-11 uncontended quiescence budget exceeded: {elapsed:?} > 50ms"
            );
            assert_eq!(recorder2.stages.len(), 8);
            assert_eq!(fs::read(&git_path).expect("warm git"), git_bytes_clean);
            assert_eq!(fs::read(&cap_path).expect("warm cap"), cap_bytes_clean);

            // Pre-open real OS child `RedbGitStore` and `RedbCaptureStore`
            // handles BEFORE quiescence and verify BOTH immediately receive
            // `StorageBackendError::WriteLockBusy { role }` while `guard` holds
            // `(git_wtx, cap_wtx)`!
            let preopen_git = ChildLockHolder::spawn("preopen_redb_git_then_probe_busy", &git_path);
            let preopen_cap =
                ChildLockHolder::spawn("preopen_redb_capture_then_probe_busy", &cap_path);
            let guard3 = quiesce_reverse_repository_phase1(&storage)
                .expect("quiescence with idle pre-opened external handles must succeed");
            preopen_git.release_and_wait();
            preopen_cap.release_and_wait();
            guard3
                .abort_and_release()
                .expect("release guard3 after pre-opened probes");

            // Deterministic regression test for Phase 1 CoW overlay vs peer
            // commit between `git.redb` open and `git_wtx` acquisition:
            // a pre-opened external `RedbGitStore` commits a new ref right
            // after `git_db` opens and drops its open-time `WRITER_BYTE`,
            // immediately before `try_begin_reverse_source_write_tx(&git_db)`.
            // The resulting `guard.redb().git_wtx()` MUST see the newly
            // committed row (never a stale overlaid header snapshot)!
            {
                struct MidOpenPeerCommitObserver {
                    peer: Option<ChildLockHolder>,
                    fired: bool,
                }
                impl ReversePhase1LockObserver for MidOpenPeerCommitObserver {
                    fn on_stage_acquired(&mut self, _stage: ReversePhase1QuiesceStage) {}

                    fn on_after_git_db_open_before_git_wtx(&mut self) {
                        if let Some(peer) = self.peer.take() {
                            peer.release_and_wait();
                            self.fired = true;
                        }
                    }
                }
                let peer =
                    ChildLockHolder::spawn("preopen_redb_git_then_commit_mid_open", &git_path);
                let mut mid_obs = MidOpenPeerCommitObserver {
                    peer: Some(peer),
                    fired: false,
                };
                let guard_mid =
                    quiesce_reverse_repository_phase1_inner(&storage, Some(&mut mid_obs))
                        .expect("quiescence must reconcile mid-open peer commit");
                assert!(mid_obs.fired, "mid-open peer commit hook must have fired");
                {
                    let refs = guard_mid
                        .redb()
                        .git_wtx()
                        .open_table(redb_git::REFERENCE_TABLE)
                        .expect("open REFERENCE_TABLE in quiesced git_wtx");
                    let got = refs
                        .get((0u8, "refs/heads/rb11-mid-open-commit", ""))
                        .expect("read mid-open committed ref")
                        .expect("quiesced git_wtx MUST observe peer commit made between open and write_tx");
                    assert_eq!(got.value(), b"rb11-committed-mid-open");
                }
                guard_mid
                    .abort_and_release()
                    .expect("release guard_mid after verifying mid-open peer commit");
            }

            // Re-verify AC1–AC4 when all 6 lock files already exist (exercises
            // Phase 1 lock acquisition + zero-write rejection with zero residual
            // lock held after rejection!).
            for (mode, target_path, label) in [
                ("hold_redb_git_write_tx", &git_path, "git.redb post-lock"),
                (
                    "hold_redb_capture_write_tx",
                    &cap_path,
                    "capture.redb post-lock",
                ),
            ] {
                let holder = ChildLockHolder::spawn(mode, target_path);
                let git_snap = fs::read(&git_path).expect("git snap before post-lock reject");
                let cap_snap = fs::read(&cap_path).expect("cap snap before post-lock reject");
                let err = quiesce_reverse_repository_phase1(&storage)
                    .expect_err(&format!("{label} writer must fail closed"));
                assert_eq!(err.stable_code_str(), "LBR-IO-001");
                assert_eq!(fs::read(&git_path).expect("git bytes"), git_snap);
                assert_eq!(fs::read(&cap_path).expect("cap bytes"), cap_snap);
                holder.release_and_wait();
            }
        }

        // --------------------------------------------------------------------
        // GC-13 role isolation & manifest authority checks:
        // --------------------------------------------------------------------
        for forbidden_role in [
            DatabaseRole::GlobalConfig,
            DatabaseRole::SystemConfig,
            DatabaseRole::Derived,
        ] {
            let err = quiesce_reverse_repository_phase1_for_role(&storage, forbidden_role)
                .expect_err("GC-13 must reject non-repository role");
            assert_eq!(err.stable_code_str(), "LBR-IO-001");
        }

        // Unfinalized manifest MUST fail closed `LBR-IO-001`.
        let dummy_sha = "0".repeat(64);
        let unfinalized = StorageFormatManifest::new_redb_in_progress(
            1,
            Some("sqlite-backup/00000001".to_string()),
            Phase2Progress {
                git_db: Some(Phase2DbState::FencedReadyToUnlink),
                capture_db: Some(Phase2DbState::FencedReadyToUnlink),
                spool_fenced: false,
                git_redb: None,
                cap_redb: None,
                queue_fenced: false,
            },
            SourceDigests {
                git_logical_sha256: Some(dummy_sha.clone()),
                git_backup_sha256: Some(dummy_sha.clone()),
                cap_logical_sha256: Some(dummy_sha.clone()),
                cap_backup_sha256: Some(dummy_sha.clone()),
                spool_manifest_sha256: Some(dummy_sha.clone()),
                queue_manifest_sha256: Some(dummy_sha.clone()),
                git_redb_sha256: None,
                cap_redb_sha256: None,
            },
        )
        .expect("build unfinalized redb manifest");
        crate::storage::publish_storage_manifest(&storage, &unfinalized)
            .expect("write unfinalized manifest");
        let unfin_err = quiesce_reverse_repository_phase1(&storage)
            .expect_err("unfinalized manifest must fail closed");
        assert_eq!(unfin_err.stable_code_str(), "LBR-IO-001");

        // Finalized SQLite manifest MUST fail closed `LBR-IO-001`.
        let mut sqlite_manifest = StorageFormatManifest::new_sqlite_in_progress(
            2,
            0x1234_5678,
            Some("redb-backup/00000001".to_string()),
            Phase2Progress {
                git_redb: Some(Phase2DbState::Unlinked),
                cap_redb: Some(Phase2DbState::Unlinked),
                queue_fenced: true,
                spool_fenced: true,
                git_db: None,
                capture_db: None,
            },
            SourceDigests {
                git_redb_sha256: Some(dummy_sha.clone()),
                cap_redb_sha256: Some(dummy_sha.clone()),
                queue_manifest_sha256: Some(dummy_sha.clone()),
                spool_manifest_sha256: Some(dummy_sha),
                git_logical_sha256: None,
                git_backup_sha256: None,
                cap_logical_sha256: None,
                cap_backup_sha256: None,
            },
        )
        .expect("build reverse sqlite manifest");
        sqlite_manifest.targets_staged_for_rename = true;
        let mut sqlite_finalized = sqlite_manifest
            .into_finalized()
            .expect("finalize reverse sqlite manifest");
        sqlite_finalized.spool_unfenced = true;
        crate::storage::publish_storage_manifest(&storage, &sqlite_finalized)
            .expect("write finalized sqlite manifest");
        let sqlite_err = quiesce_reverse_repository_phase1(&storage)
            .expect_err("sqlite manifest must fail closed for reverse migration");
        assert_eq!(sqlite_err.stable_code_str(), "LBR-IO-001");
    }

    /// `RB-11z` AC1–AC8: symmetric reverse migration Phase 1 rejects active
    /// external queue producers holding in-place `capture-queue/append.lock`
    /// AND active in-flight `capture-spool/tmp/` publishers (`spool.rs:119-145`),
    /// returning fail-closed `LBR-IO-001` with 1:1 single-domain byte-identical
    /// snapshots across source redb (`git.redb`/`capture.redb`),
    /// `capture-queue/`, and `capture-spool/` (both when all optional lock files
    /// already exist AND when optional lock files are initially absent).
    #[tokio::test]
    async fn reverse_phase1_rejects_queue_producer_and_inflight_spool_tmp() {
        use crate::storage::{
            CaptureQueueLane, FRAME_FLAG_NONE, FRAME_FLAG_PRIORITY, append_frame,
        };

        /// Seed a finalized Redb repo with real queued frames in BOTH
        /// `capture-queue/{priority,normal}/` and a populated `capture-spool/`
        /// (`ready/` + `tmp/` directory mode when `use_active_spool_dirs`, or
        /// `0400` tombstones otherwise).
        async fn setup_rb11z_fixture(
            storage: &Path,
            create_optional_locks: bool,
            use_active_spool_dirs: bool,
        ) -> (PathBuf, PathBuf) {
            let (git_path, cap_path) = build_rb11_finalized_redb_repo_fixture(storage).await;

            // Append real capture-queue frames to BOTH `priority` and `normal` lanes!
            append_frame(
                storage,
                CaptureQueueLane::Priority,
                FRAME_FLAG_PRIORITY,
                "rb11z-prio-1",
                b"{\"session\":\"s-prio\",\"event\":\"start\"}",
            )
            .expect("append priority queue frame");
            append_frame(
                storage,
                CaptureQueueLane::Normal,
                FRAME_FLAG_NONE,
                "rb11z-norm-1",
                b"{\"session\":\"s-norm\",\"event\":\"tool\"}",
            )
            .expect("append normal queue frame");

            let spool_dir = capture_spool_dir_path(storage);
            if use_active_spool_dirs {
                // Replace `0400` tombstones with active legacy `ready/`/`tmp/`/`quarantine/`
                // directories to simulate an unfenced/in-flight `spool.rs` publisher.
                for name in CAPTURE_SPOOL_TOMBSTONE_NAMES {
                    let p = spool_dir.join(name);
                    if p.exists() {
                        #[cfg(unix)]
                        {
                            use std::os::unix::fs::PermissionsExt as _;
                            let _ = fs::set_permissions(&p, fs::Permissions::from_mode(0o600));
                        }
                        #[cfg(windows)]
                        {
                            if let Ok(mut perms) = fs::metadata(&p).map(|m| m.permissions()) {
                                perms.set_readonly(false);
                                let _ = fs::set_permissions(&p, perms);
                            }
                        }
                        fs::remove_file(&p).expect("remove tombstone for active spool dir fixture");
                    }
                    fs::create_dir_all(&p).expect("create active spool subdir");
                    #[cfg(unix)]
                    {
                        use std::os::unix::fs::PermissionsExt as _;
                        fs::set_permissions(&p, fs::Permissions::from_mode(0o700))
                            .expect("chmod 0700 active spool subdir");
                    }
                }
                fs::write(
                    spool_dir.join("ready").join("0001-rb11z-ready.json"),
                    b"{\"event\":\"ready\"}",
                )
                .expect("seed ready spool file");
            }

            let writer_lock = capture_queue_writer_lock_path(storage);
            let capacity_lock = capture_spool_capacity_lock_path(storage);
            let consumer_lock = capture_spool_consumer_lock_path(storage);
            if create_optional_locks {
                for p in [&writer_lock, &capacity_lock, &consumer_lock] {
                    if !p.exists() {
                        fs::write(p, b"").expect("create optional lock file");
                        #[cfg(unix)]
                        {
                            use std::os::unix::fs::PermissionsExt as _;
                            fs::set_permissions(p, fs::Permissions::from_mode(0o600))
                                .expect("chmod 0600 optional lock");
                        }
                    }
                }
            } else {
                for p in [&writer_lock, &capacity_lock, &consumer_lock] {
                    if p.exists() {
                        fs::remove_file(p).expect("remove optional lock for absent-lock variant");
                    }
                }
            }

            (git_path, cap_path)
        }

        for (create_optional_locks, variant) in [
            (true, "all-locks-present"),
            (false, "optional-locks-absent"),
        ] {
            // ================================================================
            // AC1–AC4: External OS-process queue producer holding in-place
            // `capture-queue/append.lock` (both exclusive & shared flock).
            // ================================================================
            for (lock_mode, mode_label) in [
                ("hold_flock_exclusive", "exclusive-append-lock"),
                ("hold_flock_shared", "shared-append-lock"),
            ] {
                let dir = tempdir().expect("rb11z append.lock tempdir");
                let storage = dir.path().join(".libra");
                let (git_path, cap_path) =
                    setup_rb11z_fixture(&storage, create_optional_locks, false).await;

                let queue_dir = capture_queue_dir_path(&storage);
                let spool_dir = capture_spool_dir_path(&storage);
                let append_lock = capture_queue_append_lock_path(&storage);

                let before_git = fs::read(&git_path).expect("snapshot git.redb before AC1");
                let before_cap = fs::read(&cap_path).expect("snapshot capture.redb before AC1");
                let before_queue = snapshot_directory_tree(&queue_dir);
                let before_spool = snapshot_directory_tree(&spool_dir);

                let holder = ChildLockHolder::spawn(lock_mode, &append_lock);

                // AC1: fail-closed `LBR-IO-001` (and zero private path leak).
                let err = quiesce_reverse_repository_phase1(&storage).expect_err(&format!(
                    "AC1 ({variant}/{mode_label}): held append.lock must fail closed"
                ));
                assert_eq!(
                    err.stable_code_str(),
                    "LBR-IO-001",
                    "AC1 ({variant}/{mode_label}): expected LBR-IO-001, got {err}"
                );
                assert!(
                    !err.to_string().contains(&storage.display().to_string()),
                    "AC1 ({variant}/{mode_label}): error message must not leak private path: {err}"
                );

                // AC2: source redb (`git.redb` & `capture.redb`) byte-identical.
                assert_eq!(
                    fs::read(&git_path).expect("read git.redb after AC1"),
                    before_git,
                    "AC2 ({variant}/{mode_label}): git.redb must remain byte-identical"
                );
                assert_eq!(
                    fs::read(&cap_path).expect("read capture.redb after AC1"),
                    before_cap,
                    "AC2 ({variant}/{mode_label}): capture.redb must remain byte-identical"
                );

                // AC3: `capture-queue/` ALL files byte-identical (no new locks/files).
                assert_eq!(
                    snapshot_directory_tree(&queue_dir),
                    before_queue,
                    "AC3 ({variant}/{mode_label}): capture-queue/ must remain byte-identical"
                );

                // AC4: `capture-spool/` ALL files byte-identical.
                assert_eq!(
                    snapshot_directory_tree(&spool_dir),
                    before_spool,
                    "AC4 ({variant}/{mode_label}): capture-spool/ must remain byte-identical"
                );
                assert!(
                    !migration_lock_path(&storage).exists(),
                    "AC1–AC4 ({variant}/{mode_label}): must not create stray migration.lock"
                );

                holder.release_and_wait();
            }

            // ================================================================
            // AC5–AC8: Unexpired in-flight `capture-spool/tmp/` file (and
            // future-mtime staging file) simulating `spool.rs:119-145`.
            // ================================================================
            for (use_future_mtime, tmp_label) in
                [(false, "fresh-unexpired-tmp"), (true, "future-mtime-tmp")]
            {
                let dir = tempdir().expect("rb11z spool tmp tempdir");
                let storage = dir.path().join(".libra");
                let (git_path, cap_path) =
                    setup_rb11z_fixture(&storage, create_optional_locks, true).await;

                let queue_dir = capture_queue_dir_path(&storage);
                let spool_dir = capture_spool_dir_path(&storage);
                let inflight_tmp =
                    capture_spool_tmp_dir_path(&storage).join("1-0000000000000099-0001~inflight");
                fs::write(&inflight_tmp, b"{\"partial_envelope\":true}")
                    .expect("write in-flight capture-spool/tmp file");
                if use_future_mtime {
                    let f = OpenOptions::new()
                        .write(true)
                        .open(&inflight_tmp)
                        .expect("open inflight tmp for future mtime");
                    f.set_modified(SystemTime::now() + Duration::from_secs(3600))
                        .expect("set future mtime on inflight tmp");
                }

                let before_git = fs::read(&git_path).expect("snapshot git.redb before AC5");
                let before_cap = fs::read(&cap_path).expect("snapshot capture.redb before AC5");
                let before_spool = snapshot_directory_tree(&spool_dir);
                let before_queue = snapshot_directory_tree(&queue_dir);

                // AC5: fail-closed `LBR-IO-001` (and zero private path leak).
                let err = quiesce_reverse_repository_phase1(&storage).expect_err(&format!(
                    "AC5 ({variant}/{tmp_label}): in-flight capture-spool/tmp must fail closed"
                ));
                assert_eq!(
                    err.stable_code_str(),
                    "LBR-IO-001",
                    "AC5 ({variant}/{tmp_label}): expected LBR-IO-001, got {err}"
                );
                assert!(
                    !err.to_string().contains(&storage.display().to_string()),
                    "AC5 ({variant}/{tmp_label}): error message must not leak private path: {err}"
                );

                // AC6: source redb (`git.redb` & `capture.redb`) byte-identical.
                assert_eq!(
                    fs::read(&git_path).expect("read git.redb after AC5"),
                    before_git,
                    "AC6 ({variant}/{tmp_label}): git.redb must remain byte-identical"
                );
                assert_eq!(
                    fs::read(&cap_path).expect("read capture.redb after AC5"),
                    before_cap,
                    "AC6 ({variant}/{tmp_label}): capture.redb must remain byte-identical"
                );

                // AC7: `capture-spool/` ALL files byte-identical.
                assert_eq!(
                    snapshot_directory_tree(&spool_dir),
                    before_spool,
                    "AC7 ({variant}/{tmp_label}): capture-spool/ must remain byte-identical"
                );

                // AC8: `capture-queue/` ALL files byte-identical.
                assert_eq!(
                    snapshot_directory_tree(&queue_dir),
                    before_queue,
                    "AC8 ({variant}/{tmp_label}): capture-queue/ must remain byte-identical"
                );
                assert!(
                    !migration_lock_path(&storage).exists(),
                    "AC5–AC8 ({variant}/{tmp_label}): must not create stray migration.lock"
                );
            }
        }

        // ====================================================================
        // Deterministic post-lock TOCTOU regression: an in-flight publisher
        // writes a staging file into `capture-spool/tmp/` AFTER Phase 0
        // preflight passed and AFTER `capacity.lock` was acquired (the real
        // `spool.rs:119-145` window!). Post-lock `verify_no_inflight_spool_tmp_files`
        // MUST reject with `LBR-IO-001` before touching redb, preserving all 3
        // domains and releasing all 6 locks cleanly!
        // ====================================================================
        {
            struct PostLockInflightTmpInjector {
                tmp_file: PathBuf,
                injected: bool,
            }
            impl ReversePhase1LockObserver for PostLockInflightTmpInjector {
                fn on_stage_acquired(&mut self, stage: ReversePhase1QuiesceStage) {
                    if stage == ReversePhase1QuiesceStage::CaptureSpoolCapacityLock {
                        fs::write(&self.tmp_file, b"{\"late_inflight\":true}")
                            .expect("inject late in-flight capture-spool/tmp file");
                        self.injected = true;
                    }
                }
            }

            let dir = tempdir().expect("rb11z post-lock TOCTOU tempdir");
            let storage = dir.path().join(".libra");
            let (git_path, cap_path) = setup_rb11z_fixture(&storage, true, true).await;
            let queue_dir = capture_queue_dir_path(&storage);
            let late_tmp = capture_spool_tmp_dir_path(&storage).join("2-late-inflight~tmp");

            let before_git = fs::read(&git_path).expect("snapshot git before post-lock TOCTOU");
            let before_cap = fs::read(&cap_path).expect("snapshot cap before post-lock TOCTOU");
            let before_queue = snapshot_directory_tree(&queue_dir);

            let mut injector = PostLockInflightTmpInjector {
                tmp_file: late_tmp.clone(),
                injected: false,
            };
            let err = quiesce_reverse_repository_phase1_inner(&storage, Some(&mut injector))
                .expect_err("post-lock in-flight tmp must fail closed");
            assert!(injector.injected, "TOCTOU injector hook must have fired");
            assert_eq!(err.stable_code_str(), "LBR-IO-001");
            assert_eq!(fs::read(&git_path).expect("git after TOCTOU"), before_git);
            assert_eq!(fs::read(&cap_path).expect("cap after TOCTOU"), before_cap);
            assert_eq!(snapshot_directory_tree(&queue_dir), before_queue);
            assert!(
                late_tmp.exists(),
                "rejected post-lock check must not delete in-flight tmp file"
            );

            // Now age the abandoned tmp file past `CAPTURE_SPOOL_TMP_MAX_AGE` (25h)
            // -> uncontended quiescence MUST succeed within `<= 50ms` budget AND
            // preserve the expired tmp file untouched across `abort_and_release()`!
            let f = OpenOptions::new()
                .write(true)
                .open(&late_tmp)
                .expect("open tmp file to age past 24h");
            f.set_modified(SystemTime::now() - Duration::from_secs(25 * 3600))
                .expect("set expired mtime > 24h");
            drop(f);

            let spool_dir = capture_spool_dir_path(&storage);
            let before_spool_expired = snapshot_directory_tree(&spool_dir);
            let started = Instant::now();
            let guard = quiesce_reverse_repository_phase1(&storage)
                .expect("expired >24h capture-spool/tmp file must allow reverse quiescence");
            let elapsed = started.elapsed();
            guard
                .abort_and_release()
                .expect("abort and release after expired tmp check");
            assert!(
                elapsed <= Duration::from_millis(50),
                "RB-11z uncontended quiescence budget exceeded: {elapsed:?} > 50ms"
            );
            assert_eq!(fs::read(&git_path).expect("git after expired"), before_git);
            assert_eq!(fs::read(&cap_path).expect("cap after expired"), before_cap);
            assert_eq!(
                snapshot_directory_tree(&spool_dir),
                before_spool_expired,
                "expired >24h tmp file must be preserved untouched during Phase 1 quiescence"
            );
            assert_eq!(snapshot_directory_tree(&queue_dir), before_queue);
        }

        // ====================================================================
        // Unix safety regression: tampered / symlinked / hard-linked
        // `capture-spool/tmp` tombstones MUST fail closed `LBR-IO-001`.
        // ====================================================================
        #[cfg(unix)]
        {
            let dir = tempdir().expect("rb11z symlink/hardlink tombstone tempdir");
            let storage = dir.path().join(".libra");
            let _ = setup_rb11z_fixture(&storage, true, true).await;
            let tmp_path = capture_spool_tmp_dir_path(&storage);
            fs::remove_dir(&tmp_path).expect("remove empty tmp dir");

            let decoy = dir.path().join("tombstone-decoy");
            fs::write(&decoy, CAPTURE_SPOOL_TOMBSTONE_SENTINEL).expect("write decoy tombstone");

            fs::hard_link(&decoy, &tmp_path).expect("plant hard-linked tmp tombstone");
            let hl_err = quiesce_reverse_repository_phase1(&storage)
                .expect_err("hard-linked capture-spool/tmp tombstone must fail closed");
            assert_eq!(hl_err.stable_code_str(), "LBR-IO-001");
            fs::remove_file(&tmp_path).expect("remove hard-linked tmp");

            std::os::unix::fs::symlink(&decoy, &tmp_path).expect("plant symlinked tmp tombstone");
            let sym_err = quiesce_reverse_repository_phase1(&storage)
                .expect_err("symlinked capture-spool/tmp must fail closed");
            assert_eq!(sym_err.stable_code_str(), "LBR-IO-001");
        }
    }

    /// `RB-11q`: Verifies reverse migration Phase 1:
    /// - AC1–AC3: External OS process holding `capture-spool-consumer.lock`
    ///   (`drain.rs:87`) fails closed with `LBR-IO-001` while keeping source
    ///   `git.redb`/`capture.redb` and `capture-spool/` 100% byte-identical;
    /// - AC4: While reverse migration holds `capture-spool-consumer.lock`,
    ///   concurrent `drain_storage` sees the busy lock immediately and exits
    ///   with zero file moves (never moving `ready/` into `quarantine/`);
    /// - AC5–AC6: Non-empty `capture-spool/quarantine/` fails closed with
    ///   `LBR-IO-001` within the `<= 20ms` lock-probe + dir-check budget while
    ///   preserving every quarantined file 100% byte-for-byte intact.
    #[cfg(all(
        feature = "storage-sqlite",
        feature = "storage-redb",
        feature = "storage-queue"
    ))]
    #[tokio::test]
    async fn reverse_phase1_consumer_lock_excludes_concurrent_drain_and_rejects_quarantine() {
        use crate::internal::ai::capture::drain;

        async fn setup_rb11q_fixture(
            storage: &Path,
            create_optional_locks: bool,
            use_active_spool_dirs: bool,
        ) -> (PathBuf, PathBuf) {
            let (git_path, cap_path) = build_rb11_finalized_redb_repo_fixture(storage).await;

            let spool_dir = capture_spool_dir_path(storage);
            if use_active_spool_dirs {
                for name in CAPTURE_SPOOL_TOMBSTONE_NAMES {
                    let p = spool_dir.join(name);
                    if p.exists() {
                        #[cfg(unix)]
                        {
                            use std::os::unix::fs::PermissionsExt as _;
                            let _ = fs::set_permissions(&p, fs::Permissions::from_mode(0o600));
                        }
                        #[cfg(windows)]
                        {
                            if let Ok(mut perms) = fs::metadata(&p).map(|m| m.permissions()) {
                                perms.set_readonly(false);
                                let _ = fs::set_permissions(&p, perms);
                            }
                        }
                        fs::remove_file(&p).expect("remove spool tombstone for active dir fixture");
                    }
                    fs::create_dir_all(&p).expect("create active spool subdir");
                    #[cfg(unix)]
                    {
                        use std::os::unix::fs::PermissionsExt as _;
                        fs::set_permissions(&p, fs::Permissions::from_mode(0o700))
                            .expect("chmod 0700 active spool subdir");
                    }
                }
            }

            let consumer_lock = capture_spool_consumer_lock_path(storage);
            if !consumer_lock.exists() {
                fs::write(&consumer_lock, b"").expect("create capture-spool-consumer.lock");
                #[cfg(unix)]
                {
                    use std::os::unix::fs::PermissionsExt as _;
                    fs::set_permissions(&consumer_lock, fs::Permissions::from_mode(0o600))
                        .expect("chmod 0600 consumer lock");
                }
            }

            let writer_lock = capture_queue_writer_lock_path(storage);
            let capacity_lock = capture_spool_capacity_lock_path(storage);
            let append_lock = capture_queue_append_lock_path(storage);
            if create_optional_locks {
                for p in [&writer_lock, &capacity_lock, &append_lock] {
                    if !p.exists() {
                        fs::write(p, b"").expect("create optional lock file");
                        #[cfg(unix)]
                        {
                            use std::os::unix::fs::PermissionsExt as _;
                            fs::set_permissions(p, fs::Permissions::from_mode(0o600))
                                .expect("chmod 0600 optional lock");
                        }
                    }
                }
            } else {
                for p in [&writer_lock, &capacity_lock, &append_lock] {
                    if p.exists() {
                        fs::remove_file(p).expect("remove optional lock");
                    }
                }
            }

            (git_path, cap_path)
        }

        // ====================================================================
        // AC1–AC3: External OS spool consumer holding `capture-spool-consumer.lock`
        // ====================================================================
        for (create_optional_locks, variant) in [
            (true, "all-locks-present"),
            (false, "optional-locks-absent"),
        ] {
            for (lock_mode, mode_label) in [
                ("hold_flock_exclusive", "exclusive-consumer-lock"),
                ("hold_flock_shared", "shared-consumer-lock"),
            ] {
                let dir = tempdir().expect("rb11q consumer lock tempdir");
                let storage = dir.path().join(".libra");
                let (git_path, cap_path) =
                    setup_rb11q_fixture(&storage, create_optional_locks, true).await;

                let spool_dir = capture_spool_dir_path(&storage);
                let queue_dir = capture_queue_dir_path(&storage);
                let consumer_lock = capture_spool_consumer_lock_path(&storage);
                fs::write(
                    spool_dir.join("ready").join("0001-ready.json"),
                    b"{\"event\":\"ready-during-consumer-lock\"}",
                )
                .expect("seed ready spool file");

                let before_git = fs::read(&git_path).expect("snapshot git.redb before AC1");
                let before_cap = fs::read(&cap_path).expect("snapshot capture.redb before AC1");
                let before_spool = snapshot_directory_tree(&spool_dir);
                let before_queue = snapshot_directory_tree(&queue_dir);

                let holder = ChildLockHolder::spawn(lock_mode, &consumer_lock);

                let started = Instant::now();
                let err = quiesce_reverse_repository_phase1(&storage).expect_err(&format!(
                    "AC1 ({variant}/{mode_label}): held consumer lock must fail closed"
                ));
                let elapsed = started.elapsed();
                assert_eq!(err.stable_code_str(), "LBR-IO-001");
                assert!(
                    !err.to_string().contains(&storage.display().to_string()),
                    "AC1 ({variant}/{mode_label}): must not leak private path: {err}"
                );
                assert!(
                    elapsed <= Duration::from_millis(20),
                    "AC1 ({variant}/{mode_label}): lock probe exceeded 20ms budget: {elapsed:?}"
                );

                // AC2: source redb byte-identical
                assert_eq!(fs::read(&git_path).expect("git after AC1"), before_git);
                assert_eq!(fs::read(&cap_path).expect("cap after AC1"), before_cap);
                // AC3: capture-spool/ (and capture-queue/) byte-identical, no stray migration.lock
                assert_eq!(snapshot_directory_tree(&spool_dir), before_spool);
                assert_eq!(snapshot_directory_tree(&queue_dir), before_queue);
                assert!(!migration_lock_path(&storage).exists());

                holder.release_and_wait();
            }
        }

        // ====================================================================
        // AC4: While reverse quiescence holds `capture-spool-consumer.lock`,
        // concurrent `drain_storage` exits immediately with zero moves (never
        // quarantining an unparseable `ready/` file).
        // ====================================================================
        {
            let dir = tempdir().expect("rb11q concurrent drain tempdir");
            let storage = dir.path().join(".libra");
            let _ = setup_rb11q_fixture(&storage, true, true).await;

            let spool_dir = capture_spool_dir_path(&storage);
            let ready_file = spool_dir.join("ready").join("0001-unparseable-ready.json");
            let ready_bytes = b"{not-valid-envelope-json".to_vec();
            fs::write(&ready_file, &ready_bytes).expect("seed unparseable ready envelope");
            let quar_dir = spool_dir.join(CAPTURE_SPOOL_QUARANTINE_SUBDIR);

            let guard = quiesce_reverse_repository_phase1(&storage)
                .expect("uncontended reverse quiescence with empty quarantine must succeed");

            let before_spool = snapshot_directory_tree(&spool_dir);
            let drain_started = Instant::now();
            drain::drain_storage(&storage, |_| None)
                .await
                .expect("concurrent drain_storage must see busy consumer lock and exit Ok");
            let drain_elapsed = drain_started.elapsed();
            assert!(
                drain_elapsed <= Duration::from_millis(20),
                "AC4: busy drain_storage probe exceeded 20ms budget: {drain_elapsed:?}"
            );
            assert_eq!(
                fs::read(&ready_file).expect("ready file must stay untouched in ready/"),
                ready_bytes
            );
            assert_eq!(
                fs::read_dir(&quar_dir)
                    .expect("read quarantine dir")
                    .count(),
                0,
                "AC4: concurrent drain_storage must NEVER move ready/ files into quarantine/"
            );
            assert_eq!(snapshot_directory_tree(&spool_dir), before_spool);

            guard
                .abort_and_release()
                .expect("abort and release reverse quiescence guard");
        }

        // ====================================================================
        // AC5–AC6: Non-empty `capture-spool/quarantine/` fails closed with
        // `LBR-IO-001` and preserves every quarantined file 100% byte-intact.
        // ====================================================================
        for (create_optional_locks, variant) in [
            (true, "all-locks-present"),
            (false, "optional-locks-absent"),
        ] {
            let dir = tempdir().expect("rb11q non-empty quarantine tempdir");
            let storage = dir.path().join(".libra");
            let (git_path, cap_path) =
                setup_rb11q_fixture(&storage, create_optional_locks, true).await;

            let spool_dir = capture_spool_dir_path(&storage);
            let queue_dir = capture_queue_dir_path(&storage);
            let quar_dir = spool_dir.join(CAPTURE_SPOOL_QUARANTINE_SUBDIR);
            let quar_file_a = quar_dir.join("0001-corrupt-a.json");
            let quar_file_b = quar_dir.join("0002-corrupt-b.json");
            let bytes_a = b"{\"quarantined\":\"event-a\",\"raw\":123}".to_vec();
            let bytes_b = b"not-json-binary-\x00\xff-payload".to_vec();
            fs::write(&quar_file_a, &bytes_a).expect("write quarantined file A");
            fs::write(&quar_file_b, &bytes_b).expect("write quarantined file B");

            let before_git = fs::read(&git_path).expect("snapshot git.redb before AC5");
            let before_cap = fs::read(&cap_path).expect("snapshot capture.redb before AC5");
            let before_spool = snapshot_directory_tree(&spool_dir);
            let before_queue = snapshot_directory_tree(&queue_dir);

            let started = Instant::now();
            let err = quiesce_reverse_repository_phase1(&storage).expect_err(&format!(
                "AC5 ({variant}): non-empty capture-spool/quarantine/ must fail closed"
            ));
            let elapsed = started.elapsed();
            assert_eq!(err.stable_code_str(), "LBR-IO-001");
            assert!(
                !err.to_string().contains(&storage.display().to_string()),
                "AC5 ({variant}): must not leak private path: {err}"
            );
            assert!(
                elapsed <= Duration::from_millis(20),
                "AC5 ({variant}): quarantine dir check exceeded 20ms budget: {elapsed:?}"
            );

            // AC6: Every quarantined file 100% byte-for-byte intact; zero mutations anywhere.
            assert_eq!(fs::read(&quar_file_a).expect("read quar A"), bytes_a);
            assert_eq!(fs::read(&quar_file_b).expect("read quar B"), bytes_b);
            assert_eq!(snapshot_directory_tree(&spool_dir), before_spool);
            assert_eq!(snapshot_directory_tree(&queue_dir), before_queue);
            assert_eq!(fs::read(&git_path).expect("git after AC5"), before_git);
            assert_eq!(fs::read(&cap_path).expect("cap after AC5"), before_cap);
            assert!(!migration_lock_path(&storage).exists());
        }

        // ====================================================================
        // Post-lock TOCTOU regression + Unix hardlink/symlink quarantine guard
        // ====================================================================
        {
            struct PostLockQuarantineInjector {
                quar_file: PathBuf,
                injected: bool,
            }
            impl ReversePhase1LockObserver for PostLockQuarantineInjector {
                fn on_stage_acquired(&mut self, stage: ReversePhase1QuiesceStage) {
                    if stage == ReversePhase1QuiesceStage::CaptureSpoolConsumerLock {
                        fs::write(&self.quar_file, b"{\"late_quarantine\":true}")
                            .expect("inject late quarantine file");
                        self.injected = true;
                    }
                }
            }

            let dir = tempdir().expect("rb11q post-lock quarantine TOCTOU tempdir");
            let storage = dir.path().join(".libra");
            let (git_path, cap_path) = setup_rb11q_fixture(&storage, true, true).await;
            let late_quar = capture_spool_dir_path(&storage)
                .join(CAPTURE_SPOOL_QUARANTINE_SUBDIR)
                .join("9999-late-quarantine.json");

            let before_git = fs::read(&git_path).expect("git before post-lock TOCTOU");
            let before_cap = fs::read(&cap_path).expect("cap before post-lock TOCTOU");
            let mut injector = PostLockQuarantineInjector {
                quar_file: late_quar.clone(),
                injected: false,
            };
            let err = quiesce_reverse_repository_phase1_inner(&storage, Some(&mut injector))
                .expect_err("post-lock non-empty quarantine must fail closed");
            assert!(injector.injected);
            assert_eq!(err.stable_code_str(), "LBR-IO-001");
            assert_eq!(
                fs::read(&late_quar).expect("late quarantine file must remain intact"),
                b"{\"late_quarantine\":true}"
            );
            assert_eq!(fs::read(&git_path).expect("git after TOCTOU"), before_git);
            assert_eq!(fs::read(&cap_path).expect("cap after TOCTOU"), before_cap);
        }

        #[cfg(unix)]
        {
            let dir = tempdir().expect("rb11q symlink/hardlink quarantine tempdir");
            let storage = dir.path().join(".libra");
            let _ = setup_rb11q_fixture(&storage, true, true).await;
            let quar_path = capture_spool_dir_path(&storage).join(CAPTURE_SPOOL_QUARANTINE_SUBDIR);
            fs::remove_dir(&quar_path).expect("remove empty quarantine dir");

            let decoy = dir.path().join("quar-tombstone-decoy");
            fs::write(&decoy, CAPTURE_SPOOL_TOMBSTONE_SENTINEL)
                .expect("write decoy quarantine tombstone");

            fs::hard_link(&decoy, &quar_path).expect("plant hard-linked quarantine tombstone");
            let hl_err = quiesce_reverse_repository_phase1(&storage)
                .expect_err("hard-linked capture-spool/quarantine tombstone must fail closed");
            assert_eq!(hl_err.stable_code_str(), "LBR-IO-001");
            fs::remove_file(&quar_path).expect("remove hard-linked quarantine");

            std::os::unix::fs::symlink(&decoy, &quar_path)
                .expect("plant symlinked quarantine tombstone");
            let sym_err = quiesce_reverse_repository_phase1(&storage)
                .expect_err("symlinked capture-spool/quarantine must fail closed");
            assert_eq!(sym_err.stable_code_str(), "LBR-IO-001");
        }
    }

    fn snapshot_dir_tree_bytes(root: &Path) -> BTreeMap<String, Vec<u8>> {
        fn walk(base: &Path, dir: &Path, out: &mut BTreeMap<String, Vec<u8>>) {
            let Ok(rd) = fs::read_dir(dir) else {
                return;
            };
            let mut entries: Vec<_> = rd.flatten().collect();
            entries.sort_by_key(|e| e.file_name());
            for entry in entries {
                let path = entry.path();
                let rel = path
                    .strip_prefix(base)
                    .expect("strip prefix")
                    .to_string_lossy()
                    .replace('\\', "/");
                if let Ok(meta) = fs::symlink_metadata(&path) {
                    if meta.file_type().is_dir() {
                        walk(base, &path, out);
                    } else if meta.file_type().is_file() {
                        out.insert(rel, fs::read(&path).expect("read snapshot file"));
                    }
                }
            }
        }
        let mut out = BTreeMap::new();
        walk(root, root, &mut out);
        out
    }

